window.CONTENT={"readings":[{"id":"l01","lvl":"A2","t":"In treno da Roma a Firenze","tp":"In tréno da Róma a Firéntse","es_t":"En tren de Roma a Florencia","topic":"viaje","s":[["Carmen è una cuoca di Siviglia e quest'estate visita l'Italia.","Cármen e úna cuóca di Sivíll-lla e cuestestáte vísita litália.","Carmen es una cocinera de Sevilla y este verano visita Italia."],["Arriva a Roma in aereo e dopo tre giorni prende il treno per Firenze.","Ar-ríva a Róma in aéreo e dópo tre dyórni prénde il tréno per Firéntse.","Llega a Roma en avión y después de tres días coge el tren para Florencia."],["Compra il biglietto a una macchinetta automatica della stazione Termini.","Cómpra il bill-llét-to a úna mak-kinét-ta automática dél-la stat-tsióne Términi.","Compra el billete en una máquina automática de la estación Termini."],["Sceglie un Frecciarossa, un treno ad alta velocità.","Shéll-lle un Fret-charós-sa, un tréno ad álta velochitá.","Elige un Frecciarossa, un tren de alta velocidad."],["Il viaggio dura circa un'ora e mezza.","Il viád-dyo dúra chírca unóra e méd-dsa.","El viaje dura más o menos una hora y media."],["Il treno è comodo e puntuale.","Il tréno e cómodo e puntuále.","El tren es cómodo y puntual."],["Dal finestrino Carmen guarda le colline della Toscana.","Dal finestríno Cármen guárda le col-líne dél-la Toscána.","Por la ventanilla Carmen mira las colinas de la Toscana."],["A Firenze scende alla stazione di Santa Maria Novella, vicino al centro.","A Firéntse shénde ál-la stat-tsióne di Sánta María Novél-la, vichíno al chéntro.","En Florencia se baja en la estación de Santa Maria Novella, cerca del centro."],["Prima di partire, però, Carmen ha imparato una regola importante.","Príma di partíre, peró, Cármen a imparáto úna régola importánte.","Antes de salir, sin embargo, Carmen ha aprendido una regla importante."],["Sui treni regionali bisogna convalidare il biglietto di carta prima di salire.","Sui tréni redyonáli bisóñ-ña convalidáre il bill-llét-to di cárta príma di salíre.","En los trenes regionales hay que validar el billete de papel antes de subir."],["Chi non lo fa rischia una multa.","Ki non lo fa rískia úna múlta.","Quien no lo hace se arriesga a una multa."]],"q":[["¿De dónde es Carmen y en qué trabaja?",["Es cocinera y es de Sevilla.","Es profesora y es de Roma.","Es camarera y es de Florencia."],0,"El texto dice «Carmen è una cuoca di Siviglia»."],["¿Cómo llega Carmen a Roma?",["En tren","En avión","En coche"],1,"«Arriva a Roma in aereo»: llega en avión."],["¿Cuánto dura el viaje en el Frecciarossa?",["Unos tres días","Media hora","Una hora y media, más o menos"],2,"«Il viaggio dura circa un'ora e mezza»."],["¿Qué ve Carmen por la ventanilla?",["Las colinas de la Toscana","El mar","Las montañas de los Alpes"],0,"«Dal finestrino Carmen guarda le colline della Toscana»."],["¿Qué hay que hacer con el billete de papel en los trenes regionales?",["Comprarlo dentro del tren","Validarlo antes de subir","Enseñarlo solo al llegar"],1,"«Bisogna convalidare il biglietto di carta prima di salire»."]],"w":[["biglietto","bill-llét-to","billete"],["convalidare","convalidáre","validar"],["viaggio","viád-dyo","viaje"],["finestrino","finestríno","ventanilla"],["velocità","velochitá","velocidad"],["comodo","cómodo","cómodo"],["macchinetta","mak-kinét-ta","máquina expendedora"],["multa","múlta","multa"]]},{"id":"l02","lvl":"A2","t":"Il caffè al bar","tp":"Il caf-fé al bar","es_t":"El café en el bar","topic":"costumbres","s":[["In Italia il caffè è un piccolo rito quotidiano.","In Itália il caf-fé e un píc-colo ríto cuotidiáno.","En Italia el café es un pequeño rito diario."],["Molti italiani lo bevono al bar, in piedi al banco.","Mólti italiáni lo bévono al bar, in piédi al bánco.","Muchos italianos se lo toman en el bar, de pie en la barra."],["Quando chiedi «un caffè», il barista ti porta un espresso, piccolo e forte.","Cuándo kiédi «un caf-fé», il barísta ti pórta un esprés-so, píc-colo e fórte.","Cuando pides «un caffè», el camarero te trae un espresso, pequeño y fuerte."],["Se vuoi un po' di latte, puoi ordinare un caffè macchiato.","Se vuoi un po di lát-te, puoi ordináre un caf-fé mak-kiáto.","Si quieres un poco de leche, puedes pedir un café cortado."],["Il cappuccino, invece, è una bevanda della mattina.","Il cap-put-chíno, invéche, e úna bevánda dél-la mat-tína.","El capuchino, en cambio, es una bebida de la mañana."],["Molti italiani non lo prendono dopo pranzo o dopo cena.","Mólti italiáni non lo préndono dópo prántso o dópo chéna.","Muchos italianos no lo toman después de comer o después de cenar."],["In molti bar si paga prima alla cassa e poi si dà lo scontrino al barista.","In mólti bar si pága príma ál-la cás-sa e poi si da lo scontríno al barísta.","En muchos bares se paga primero en la caja y luego se da el tique al camarero."],["Al banco il caffè costa meno che al tavolo.","Al bánco il caf-fé cósta méno ke al távolo.","En la barra el café cuesta menos que en la mesa."],["Spesso, insieme al caffè, il barista serve un bicchiere d'acqua.","Spés-so, insiéme al caf-fé, il barísta sérve un bik-kiére dác-cua.","A menudo, junto con el café, el camarero sirve un vaso de agua."],["E la mattina, con il caffè, tanti mangiano un cornetto.","E la mat-tína, con il caf-fé, tánti mándyano un cornét-to.","Y por la mañana, con el café, muchos se comen un cornetto."]],"q":[["¿Qué te sirve el camarero si pides «un caffè»?",["Un café con leche","Un espresso","Un café americano"],1,"«Il barista ti porta un espresso»: «un caffè» es siempre un espresso."],["¿Dónde toman el café muchos italianos?",["De pie, en la barra del bar","Sentados en la terraza","Siempre en casa"],0,"«Lo bevono al bar, in piedi al banco»."],["Según el texto, ¿cuándo se toma el capuchino?",["Después de cenar","Después de comer","Por la mañana"],2,"«È una bevanda della mattina»; muchos no lo toman después de comer ni de cenar."],["¿Qué se hace primero en muchos bares?",["Se busca una mesa","Se pide el cornetto","Se paga en la caja"],2,"«Si paga prima alla cassa e poi si dà lo scontrino al barista»."],["¿Dónde es más barato el café?",["En la mesa","En la barra","Cuesta lo mismo"],1,"«Al banco il caffè costa meno che al tavolo»."]],"w":[["banco","bánco","barra (del bar)"],["scontrino","scontríno","tique de caja"],["cassa","cás-sa","caja"],["macchiato","mak-kiáto","cortado (café con unas gotas de leche)"],["bevanda","bevánda","bebida"],["bicchiere","bik-kiére","vaso"],["tavolo","távolo","mesa"],["cornetto","cornét-to","cruasán italiano"]]},{"id":"l03","lvl":"A2","t":"Il Parmigiano Reggiano","tp":"Il Parmidyáno Red-dyáno","es_t":"El Parmigiano Reggiano","topic":"gastronomía","s":[["Il Parmigiano Reggiano è un formaggio italiano molto famoso.","Il Parmidyáno Red-dyáno e un formád-dyo italiáno mólto famóso.","El Parmigiano Reggiano es un queso italiano muy famoso."],["È un prodotto DOP, cioè a denominazione di origine protetta.","E un prodót-to Dop, choé a denominat-tsióne di orídyine protét-ta.","Es un producto DOP, es decir, con denominación de origen protegida."],["Si produce solo in alcune province dell'Emilia-Romagna e della Lombardia.","Si prodúche sólo in alcúne provínche del-lemília-Romáñ-ña e dél-la Lombardía.","Solo se produce en algunas provincias de Emilia-Romaña y de Lombardía."],["Per farlo servono latte crudo, sale e caglio.","Per fárlo sérvono lát-te crúdo, sále e cáll-llo.","Para hacerlo hacen falta leche cruda, sal y cuajo."],["Non si usano conservanti.","Non si úsano conservánti.","No se usan conservantes."],["Le forme sono grandi e rotonde e restano a lungo in magazzino.","Le fórme sóno grándi e rotónde e réstano a lúngo in magad-dsíno.","Las piezas son grandes y redondas y se quedan mucho tiempo en el almacén."],["La stagionatura minima è di dodici mesi.","La stadyonatúra mínima e di dódichi mési.","La curación mínima es de doce meses."],["Spesso però il formaggio stagiona ventiquattro mesi o anche di più.","Spés-so peró il formád-dyo stadyóna venticuát-tro mési o ánke di piu.","Pero a menudo el queso se cura veinticuatro meses o incluso más."],["Più è stagionato, più il sapore è intenso e la pasta è friabile.","Piu e stadyonáto, piu il sapóre e inténso e la pásta e friábile.","Cuanto más curado está, más intenso es el sabor y más quebradiza es la pasta."],["Si mangia a scaglie, con un po' di miele o di aceto balsamico, oppure si grattugia sulla pasta.","Si mándya a scáll-lle, con un po di miéle o di achéto balsámico, op-púre si grat-túdya súl-la pásta.","Se come en lascas, con un poco de miel o de vinagre balsámico, o se ralla sobre la pasta."],["La crosta non si butta: si usa per insaporire il minestrone.","La crósta non si bút-ta: si úsa per insaporíre il minestróne.","La corteza no se tira: se usa para dar sabor al minestrone."]],"q":[["¿Qué significa que el Parmigiano Reggiano sea DOP?",["Que tiene denominación de origen protegida","Que es un queso sin sal","Que es un queso de cabra"],0,"«DOP, cioè a denominazione di origine protetta»."],["¿Dónde se produce?",["En toda Italia","En la Toscana y en el Lacio","En algunas provincias de Emilia-Romaña y Lombardía"],2,"«Solo in alcune province dell'Emilia-Romagna e della Lombardia»."],["¿Qué ingredientes lleva?",["Leche pasteurizada, sal y conservantes","Leche cruda, sal y cuajo","Leche, nata y azúcar"],1,"«Servono latte crudo, sale e caglio» y no lleva conservantes."],["¿Cuál es la curación mínima?",["Seis meses","Veinticuatro meses","Doce meses"],2,"«La stagionatura minima è di dodici mesi»; 24 meses es frecuente, pero no es el mínimo."],["¿Qué se hace con la corteza?",["Se tira","Se usa para dar sabor al minestrone","Se ralla sobre la pasta"],1,"«Si usa per insaporire il minestrone»."]],"w":[["formaggio","formád-dyo","queso"],["stagionatura","stadyonatúra","curación, maduración"],["caglio","cáll-llo","cuajo"],["crosta","crósta","corteza"],["grattugiare","grat-tudyáre","rallar"],["insaporire","insaporíre","dar sabor"],["forma","fórma","pieza (de queso)"],["scaglia","scáll-lla","lasca, escama"]]},{"id":"l04","lvl":"A2","t":"Il pranzo della domenica","tp":"Il prántso dél-la doménica","es_t":"La comida del domingo","topic":"costumbres","s":[["In molte famiglie italiane il pranzo della domenica è un momento speciale.","In mólte famíll-lle italiáne il prántso dél-la doménica e un moménto spechále.","En muchas familias italianas la comida del domingo es un momento especial."],["Nonni, genitori, figli e nipoti si ritrovano spesso a casa dei nonni.","Nón-ni, dyenitóri, fíll-lli e nipóti si ritróvano spés-so a cása dei nón-ni.","Abuelos, padres, hijos y nietos se reúnen a menudo en casa de los abuelos."],["Il pranzo comincia tardi, verso l'una, e dura qualche ora.","Il prántso comíncha tárdi, vérso lúna, e dúra cuálke óra.","La comida empieza tarde, hacia la una, y dura unas horas."],["Prima arrivano gli antipasti: salumi, formaggi e verdure.","Príma ar-rívano lli antipásti: salúmi, formád-dyi e verdúre.","Primero llegan los entrantes: embutidos, quesos y verduras."],["Poi c'è il primo, per esempio le lasagne o la pasta al forno.","Poi che il prímo, per esémpio le lasáñ-ñe o la pásta al fórno.","Luego está el primer plato, por ejemplo la lasaña o la pasta al horno."],["Dopo viene il secondo, di carne o di pesce, con un contorno di verdure.","Dópo viéne il secóndo, di cárne o di pésh-she, con un contórno di verdúre.","Después viene el segundo, de carne o de pescado, con una guarnición de verduras."],["Alla fine non mancano il dolce, la frutta e il caffè.","Ál-la fíne non máncano il dólche, la frút-ta e il caf-fé.","Al final no faltan el postre, la fruta y el café."],["Spesso il dolce è una torta fatta in casa oppure arriva dalla pasticceria.","Spés-so il dólche e úna tórta fát-ta in cása op-púre ar-ríva dál-la pastit-chería.","A menudo el postre es una tarta casera o llega de la pastelería."],["A tavola si parla molto: di calcio, di lavoro, di politica e della famiglia.","A távola si párla mólto: di cálcho, di lavóro, di política e dél-la famíll-lla.","En la mesa se habla mucho: de fútbol, de trabajo, de política y de la familia."],["Per molti italiani una domenica senza questo pranzo non è una vera domenica.","Per mólti italiáni úna doménica séntsa cuésto prántso non e úna véra doménica.","Para muchos italianos un domingo sin esta comida no es un verdadero domingo."]],"q":[["¿Quién participa en la comida del domingo?",["Solo los padres y los hijos","Abuelos, padres, hijos y nietos","Los compañeros de trabajo"],1,"«Nonni, genitori, figli e nipoti»."],["¿A qué hora empieza la comida, más o menos?",["A la una","A las doce","A las tres"],0,"«Verso l'una»: hacia la una."],["¿Qué es el «secondo»?",["Un plato de pasta","Un postre","Un plato de carne o de pescado"],2,"«Il secondo, di carne o di pesce, con un contorno»."],["¿De dónde viene a menudo el postre?",["Del supermercado","De casa o de la pastelería","Del restaurante"],1,"«Una torta fatta in casa oppure arriva dalla pasticceria»."],["¿Qué plato se pone como ejemplo de «primo»?",["La lasaña o la pasta al horno","Los embutidos","La fruta"],0,"«Il primo, per esempio le lasagne o la pasta al forno»."]],"w":[["pranzo","prántso","comida (del mediodía)"],["domenica","doménica","domingo"],["contorno","contórno","guarnición"],["salumi","salúmi","embutidos"],["pasticceria","pastit-chería","pastelería"],["nipoti","nipóti","nietos (también: sobrinos)"],["torta","tórta","tarta"],["genitori","dyenitóri","padres"]]},{"id":"l05","lvl":"A2","t":"Una giornata in cucina","tp":"Úna dyornáta in cuchína","es_t":"Un día en la cocina","topic":"trabajo","s":[["Marco fa il cuoco in una trattoria di Bologna.","Márco fa il cuóco in úna trat-toría di Bolóñ-ña.","Marco trabaja de cocinero en una trattoria de Bolonia."],["Ogni mattina arriva al ristorante alle nove.","Óñ-ñi mat-tína ar-ríva al ristoránte ál-le nóve.","Cada mañana llega al restaurante a las nueve."],["Prima controlla la merce: carne, verdure, uova e formaggi.","Príma contról-la la mérche: cárne, verdúre, uóva e formád-dyi.","Primero controla la mercancía: carne, verduras, huevos y quesos."],["Poi prepara le verdure e le salse con i colleghi.","Poi prepára le verdúre e le sálse con i col-légui.","Luego prepara las verduras y las salsas con los compañeros."],["La specialità della casa sono le tagliatelle al ragù.","La spechalitá dél-la cása sóno le tall-llatél-le al ragú.","La especialidad de la casa son los tagliatelle al ragú."],["Marco prepara la pasta fresca a mano, con farina e uova.","Márco prepára la pásta frésca a máno, con farína e uóva.","Marco prepara la pasta fresca a mano, con harina y huevos."],["Il ragù cuoce piano per alcune ore.","Il ragú cuóche piáno per alcúne óre.","El ragú se cuece a fuego lento durante unas horas."],["A mezzogiorno il ristorante è pieno e in cucina c'è molto lavoro.","A med-dsodyórno il ristoránte e piéno e in cuchína che mólto lavóro.","A mediodía el restaurante está lleno y en la cocina hay mucho trabajo."],["I camerieri entrano ed escono di continuo con i piatti.","I cameriéri éntrano ed éscono di contínuo con i piát-ti.","Los camareros entran y salen continuamente con los platos."],["Alle tre la cucina chiude e tutti mangiano insieme.","Ál-le tre la cuchína kiúde e tút-ti mándyano insiéme.","A las tres la cocina cierra y todos comen juntos."],["Poi Marco pulisce il suo posto di lavoro e torna a casa a riposare.","Poi Márco pulísh-she il suo pósto di lavóro e tórna a cása a riposáre.","Después Marco limpia su puesto de trabajo y vuelve a casa a descansar."],["La sera c'è un altro turno, ma Marco è libero.","La séra che un áltro túrno, ma Márco e líbero.","Por la noche hay otro turno, pero Marco está libre."]],"q":[["¿Dónde trabaja Marco?",["En un hotel de Roma","En una trattoria de Bolonia","En una pizzería de Nápoles"],1,"«Fa il cuoco in una trattoria di Bologna»."],["¿Qué hace primero por la mañana?",["Controla la mercancía","Prepara el ragú","Limpia la cocina"],0,"«Prima controlla la merce»."],["¿Cuál es la especialidad de la casa?",["La lasaña","Los tortellini","Los tagliatelle al ragú"],2,"«La specialità della casa sono le tagliatelle al ragù»."],["¿Cómo se cuece el ragú?",["Rápido, a fuego fuerte","A fuego lento durante unas horas","En el horno"],1,"«Il ragù cuoce piano per alcune ore»."],["¿Qué hacen todos a las tres?",["Comen juntos","Abren el restaurante","Hacen la compra"],0,"«Alle tre la cucina chiude e tutti mangiano insieme»."]],"w":[["cuoco","cuóco","cocinero"],["merce","mérche","mercancía, género"],["farina","farína","harina"],["cuocere","cuóchere","cocer"],["cameriere","cameriére","camarero"],["piatto","piát-to","plato"],["pulire","pulíre","limpiar"],["turno","túrno","turno"]]},{"id":"l06","lvl":"B1","t":"Venezia, la città senza macchine","tp":"Venét-tsia, la chit-tá séntsa mák-kine","es_t":"Venecia, la ciudad sin coches","topic":"viaje","s":[["Venezia è una città unica al mondo, costruita su più di cento isole in mezzo a una laguna.","Venét-tsia e úna chit-tá única al móndo, costruíta su piu di chénto ísole in méd-dso a úna lagúna.","Venecia es una ciudad única en el mundo, construida sobre más de cien islas en medio de una laguna."],["Al posto delle strade ci sono i canali e al posto delle automobili ci sono le barche.","Al pósto dél-le stráde chi sóno i canáli e al pósto dél-le automóbili chi sóno le bárke.","En lugar de calles hay canales y en lugar de coches hay barcas."],["Chi arriva in macchina deve lasciarla a Piazzale Roma o al Tronchetto; chi arriva in treno scende alla stazione di Santa Lucia, che si trova già sul Canal Grande.","Ki ar-ríva in mák-kina déve lash-shárla a Piat-tsále Róma o al Tronkét-to; ki ar-ríva in tréno shénde ál-la stat-tsióne di Sánta Luchía, ke si tróva dya sul Canál Gránde.","Quien llega en coche tiene que dejarlo en Piazzale Roma o en el Tronchetto; quien llega en tren se baja en la estación de Santa Lucia, que ya está en el Gran Canal."],["Il mezzo pubblico più usato è il vaporetto, una specie di autobus sull'acqua.","Il méd-dso púb-blico piu usáto e il vaporét-to, úna spéche di áutobus sul-lác-cua.","El medio de transporte público más usado es el vaporetto, una especie de autobús sobre el agua."],["Con i vaporetti si possono visitare anche le isole della laguna, come Murano, famosa per il vetro, e Burano, conosciuta per i merletti e le case colorate.","Con i vaporét-ti si pós-sono visitáre ánke le ísole dél-la lagúna, cóme Muráno, famósa per il vétro, e Buráno, conosh-shúta per i merlét-ti e le cáse coloráte.","Con los vaporetti se pueden visitar también las islas de la laguna, como Murano, famosa por el vidrio, y Burano, conocida por los encajes y las casas de colores."],["Le gondole, invece, oggi servono soprattutto ai turisti, ma in alcuni punti il «traghetto», una gondola semplice, porta ancora le persone da una riva all'altra del Canal Grande.","Le góndole, invéche, ód-dyi sérvono soprat-tút-to ai turísti, ma in alcúni púnti il «traguét-to», úna góndola sémpliche, pórta ancóra le persóne da úna ríva al-láltra del Canál Gránde.","Las góndolas, en cambio, hoy sirven sobre todo a los turistas, pero en algunos puntos el «traghetto», una góndola sencilla, todavía lleva a la gente de una orilla a otra del Gran Canal."],["A piedi ci si perde facilmente nelle calli, le strette vie veneziane, ma perdersi è il modo migliore per scoprire la città.","A piédi chi si pérde fachilménte nél-le cál-li, le strét-te vie venet-tsiáne, ma pérdersi e il módo mill-llóre per scopríre la chit-tá.","A pie es fácil perderse en las calli, las estrechas callejuelas venecianas, pero perderse es la mejor manera de descubrir la ciudad."],["In autunno e in inverno può arrivare l'acqua alta: il mare sale e copre una parte della città, soprattutto piazza San Marco.","In autún-no e in invérno puo ar-riváre lác-cua álta: il máre sále e cópre úna párte dél-la chit-tá, soprat-tút-to piát-tsa San Márco.","En otoño y en invierno puede llegar el «agua alta»: el mar sube y cubre una parte de la ciudad, sobre todo la plaza de San Marcos."],["In quei giorni i veneziani camminano su passerelle rialzate e indossano stivali di gomma.","In cuei dyórni i venet-tsiáni cam-mínano su pas-serél-le rialtsáte e indós-sano stiváli di góm-ma.","En esos días los venecianos caminan sobre pasarelas elevadas y se ponen botas de goma."]],"q":[["Su che cosa è costruita Venezia?",["Su una montagna","Su più di cento isole in una laguna","Sulle rive di un grande fiume"],1,"El texto dice «costruita su più di cento isole in mezzo a una laguna»."],["Dove arriva chi viaggia in treno?",["Alla stazione di Santa Lucia","A Piazzale Roma","Al Tronchetto"],0,"«Chi arriva in treno scende alla stazione di Santa Lucia»; Piazzale Roma y el Tronchetto son para quien llega en coche."],["Che cos'è il vaporetto?",["Una gondola per turisti","Una barca privata","Il mezzo pubblico più usato, come un autobus sull'acqua"],2,"«Il mezzo pubblico più usato è il vaporetto, una specie di autobus sull'acqua»."],["Per che cosa è conosciuta Burano?",["Per il vetro","Per i merletti e le case colorate","Per le gondole"],1,"Murano es famosa por el vidrio; Burano, por los encajes y las casas de colores."],["Che cosa succede con l'acqua alta?",["Chiudono tutti i canali","I vaporetti non viaggiano mai","Il mare sale e copre una parte della città"],2,"«Il mare sale e copre una parte della città, soprattutto piazza San Marco»."]],"w":[["laguna","lagúna","laguna"],["barca","bárca","barca"],["mezzo pubblico","méd-dso púb-blico","medio de transporte público"],["calle","cál-le","callejuela (en Venecia)"],["vetro","vétro","vidrio"],["merletto","merlét-to","encaje"],["riva","ríva","orilla"],["stivale","stivále","bota"]]},{"id":"l07","lvl":"B1","t":"L'aceto balsamico tradizionale di Modena","tp":"Lachéto balsámico tradit-tsionále di Módena","es_t":"El vinagre balsámico tradicional de Módena","topic":"gastronomía","s":[["L'aceto balsamico tradizionale di Modena DOP non è il normale aceto balsamico che si trova in tutti i supermercati.","Lachéto balsámico tradit-tsionále di Módena Dop non e il normále achéto balsámico ke si tróva in tút-ti i supermercáti.","El vinagre balsámico tradicional de Módena DOP no es el vinagre balsámico normal que se encuentra en todos los supermercados."],["È un prodotto molto più raro e costoso, e la sua produzione segue regole antiche e precise.","E un prodót-to mólto piu ráro e costóso, e la sua produt-tsióne ségüe régole antíke e prechíse.","Es un producto mucho más raro y caro, y su elaboración sigue reglas antiguas y precisas."],["Si parte dal mosto cotto, cioè dal succo d'uva cotto lentamente per molte ore.","Si párte dal mósto cót-to, choé dal súc-co dúva cót-to lentaménte per mólte óre.","Se parte del mosto cocido, es decir, del zumo de uva cocido lentamente durante muchas horas."],["Il mosto si mette poi in una serie di botti di legno di dimensioni diverse, chiamata «batteria».","Il mósto si mét-te poi in úna série di bót-ti di léñ-ño di dimensióni divérse, kiamáta «bat-tería».","Después el mosto se pone en una serie de toneles de madera de distintos tamaños, llamada «batería»."],["Le botti sono di legni diversi, come il rovere, il castagno e il ciliegio, e ognuno dà al prodotto un aroma particolare.","Le bót-ti sóno di léñ-ñi divérsi, cóme il róvere, il castáñ-ño e il chiliédyo, e oñ-ñúno da al prodót-to un aróma particoláre.","Los toneles son de maderas distintas, como el roble, el castaño y el cerezo, y cada una le da al producto un aroma particular."],["Ogni anno si toglie un po' di aceto dalla botte più piccola, e ogni botte viene riempita con il liquido della botte più grande vicina.","Óñ-ñi án-no si tóll-lle un po di achéto dál-la bót-te piu píc-cola, e óñ-ñi bót-te viéne riempíta con il lícuido dél-la bót-te piu gránde vichína.","Cada año se saca un poco de vinagre del tonel más pequeño, y cada tonel se rellena con el líquido del tonel más grande que tiene al lado."],["L'invecchiamento dura almeno dodici anni; se supera i venticinque anni, l'aceto si chiama «extravecchio».","Linvek-kiaménto dúra alméno dódichi án-ni; se súpera i ventichíncue án-ni, lachéto si kiáma «ecstravék-kio».","El envejecimiento dura al menos doce años; si supera los veinticinco años, el vinagre se llama «extravecchio»."],["Alla fine il prodotto è denso, scuro e lucido, con un sapore dolce e acido insieme.","Ál-la fíne il prodót-to e dénso, scúro e lúchido, con un sapóre dólche e áchido insiéme.","Al final el producto es denso, oscuro y brillante, con un sabor dulce y ácido a la vez."],["Si vende solo in piccole bottiglie da 100 millilitri, con una forma speciale, uguale per tutti i produttori.","Si vénde sólo in píc-cole bot-tíll-lle da 100 mil-lilítri, con úna fórma spechále, uguále per tút-ti i produt-tóri.","Solo se vende en botellas pequeñas de 100 mililitros, con una forma especial, igual para todos los productores."],["In cucina se ne usano poche gocce, a crudo: sul Parmigiano, sulle fragole, sul gelato o su un risotto appena fatto.","In cuchína se ne úsano póke gót-che, a crúdo: sul Parmidyáno, súl-le frágole, sul dyeláto o su un risót-to ap-péna fát-to.","En la cocina se usan pocas gotas, en crudo: sobre el Parmigiano, sobre las fresas, sobre el helado o sobre un risotto recién hecho."]],"q":[["Che cosa distingue l'aceto tradizionale da quello del supermercato?",["È più giovane ed economico","È più raro e costoso e segue regole precise","Si fa con il vino bianco"],1,"«È un prodotto molto più raro e costoso, e la sua produzione segue regole antiche e precise»."],["Da che cosa si parte per produrlo?",["Dal mosto d'uva cotto","Dal vino rosso","Dal succo di mela"],0,"«Si parte dal mosto cotto, cioè dal succo d'uva cotto lentamente»."],["Che cos'è la «batteria»?",["Un tipo di bottiglia","Una macchina per cuocere il mosto","Una serie di botti di legno di dimensioni diverse"],2,"La «batteria» es la serie de toneles de distintos tamaños."],["Quanti anni deve invecchiare come minimo?",["Cinque","Dodici","Venticinque"],1,"«Almeno dodici anni»; veinticinco es el mínimo del «extravecchio»."],["Come si usa in cucina?",["In grandi quantità, per cuocere la carne","Solo per condire l'insalata","Poche gocce, a crudo"],2,"«Se ne usano poche gocce, a crudo»."]],"w":[["aceto","achéto","vinagre"],["mosto","mósto","mosto"],["botte","bót-te","tonel, barrica"],["rovere","róvere","roble"],["invecchiamento","invek-kiaménto","envejecimiento"],["denso","dénso","denso, espeso"],["goccia","gót-cha","gota"],["fragola","frágola","fresa"]]},{"id":"l08","lvl":"B1","t":"L'aperitivo all'italiana","tp":"Laperitívo al-litaliána","es_t":"El aperitivo a la italiana","topic":"costumbres","s":[["Tra le sei e le otto di sera, in molte città italiane, i bar si riempiono di gente per l'aperitivo.","Tra le sei e le ót-to di séra, in mólte chit-tá italiáne, i bar si riémpiono di dyénte per laperitívo.","Entre las seis y las ocho de la tarde, en muchas ciudades italianas, los bares se llenan de gente para el aperitivo."],["È un momento per incontrare gli amici o i colleghi dopo il lavoro, bere qualcosa e mangiare qualche stuzzichino prima di cena.","E un moménto per incontráre lli amíchi o i col-légui dópo il lavóro, bére cualcósa e mandyáre cuálke stut-tsikíno príma di chéna.","Es un momento para quedar con los amigos o los compañeros después del trabajo, tomar algo y picar algo antes de cenar."],["Torino è considerata la patria del vermut: secondo la tradizione, fu inventato qui nel 1786 da Antonio Benedetto Carpano.","Toríno e consideráta la pátria del vérmut: secóndo la tradit-tsióne, fu inventáto cui nel 1786 da António Benedét-to Carpáno.","Turín está considerada la patria del vermut: según la tradición, se inventó aquí en 1786, obra de Antonio Benedetto Carpano."],["In Veneto la bevanda più tipica è lo spritz, preparato con prosecco, un bitter e un po' di soda.","In Véneto la bevánda piu típica e lo spritts, preparáto con proséc-co, un bít-ter e un po di sóda.","En el Véneto la bebida más típica es el spritz, preparado con prosecco, un bitter y un poco de soda."],["A Firenze, secondo la tradizione, è nato il Negroni: il conte Camillo Negroni chiese al barista di sostituire la soda dell'Americano con il gin.","A Firéntse, secóndo la tradit-tsióne, e náto il Negróni: il cónte Camíl-lo Negróni kiése al barísta di sostituíre la sóda del-lamericáno con il dyin.","En Florencia, según la tradición, nació el Negroni: el conde Camillo Negroni le pidió al camarero que sustituyera la soda del Americano por ginebra."],["Oggi il Negroni si prepara con parti uguali di gin, vermut rosso e bitter Campari.","Ód-dyi il Negróni si prepára con párti uguáli di dyin, vérmut rós-so e bít-ter Campári.","Hoy el Negroni se prepara con partes iguales de ginebra, vermut rojo y bitter Campari."],["Chi non beve alcol può ordinare un analcolico o una spremuta.","Ki non béve álcol puo ordináre un analcólico o úna spremúta.","Quien no bebe alcohol puede pedir una bebida sin alcohol o un zumo natural."],["Con il bicchiere arrivano quasi sempre patatine, olive e salatini.","Con il bik-kiére ar-rívano cuási sémpre patatíne, olíve e salatíni.","Con la copa llegan casi siempre patatas fritas, aceitunas y galletitas saladas."],["In alcuni locali, soprattutto a Milano, si trovano anche pasta fredda, focaccia e verdure: in questo caso si parla di «apericena», una via di mezzo tra aperitivo e cena.","In alcúni locáli, soprat-tút-to a Miláno, si tróvano ánke pásta fréd-da, focát-cha e verdúre: in cuésto cáso si párla di «aperichéna», úna via di méd-dso tra aperitívo e chéna.","En algunos locales, sobre todo en Milán, también se encuentran pasta fría, focaccia y verduras: en este caso se habla de «apericena», un término medio entre aperitivo y cena."],["Per qualcuno è un modo economico per uscire la sera; per i più tradizionalisti, però, l'apericena non sostituisce una vera cena.","Per cualcúno e un módo económico per ush-shíre la séra; per i piu tradit-tsionalísti, peró, laperichéna non sostituísh-she úna véra chéna.","Para algunos es una forma económica de salir por la noche; para los más tradicionalistas, sin embargo, la apericena no sustituye a una verdadera cena."]],"q":[["Quando si fa di solito l'aperitivo?",["Dopo cena","Tra le sei e le otto di sera","A mezzogiorno"],1,"«Tra le sei e le otto di sera»."],["Quale città è considerata la patria del vermut?",["Torino","Firenze","Venezia"],0,"«Torino è considerata la patria del vermut»."],["Come è nato il Negroni, secondo la tradizione?",["Un barista di Milano ha aggiunto il prosecco allo spritz","È una ricetta antica del Veneto","Il conte Negroni ha chiesto il gin al posto della soda nell'Americano"],2,"El conde pidió sustituir la soda del Americano por ginebra."],["Che cos'è l'apericena?",["Un aperitivo così abbondante che è quasi una cena","Una cena elegante","Una bevanda analcolica"],0,"Es «una via di mezzo tra aperitivo e cena», con pasta, focaccia y verduras."],["Che cosa può ordinare chi non beve alcol?",["Uno spritz","Un Negroni","Un analcolico o una spremuta"],2,"«Chi non beve alcol può ordinare un analcolico o una spremuta»."]],"w":[["stuzzichino","stut-tsikíno","aperitivo para picar, tapa"],["bevanda","bevánda","bebida"],["analcolico","analcólico","bebida sin alcohol"],["spremuta","spremúta","zumo natural exprimido"],["salatini","salatíni","galletitas saladas"],["bicchiere","bik-kiére","vaso, copa"],["locale","locále","local"],["via di mezzo","via di méd-dso","término medio"]]},{"id":"l09","lvl":"B1","t":"La pizza Margherita","tp":"La pít-tsa Margueríta","es_t":"La pizza Margherita","topic":"cultura","s":[["La pizza è uno dei piatti italiani più conosciuti al mondo, ma la sua patria è Napoli.","La pít-tsa e úno dei piát-ti italiáni piu conosh-shúti al móndo, ma la sua pátria e Nápoli.","La pizza es uno de los platos italianos más conocidos del mundo, pero su patria es Nápoles."],["Secondo la tradizione, nel 1889 la regina Margherita di Savoia era in visita a Napoli con il re Umberto.","Secóndo la tradit-tsióne, nel 1889 la redyína Margueríta di Savóia éra in vísita a Nápoli con il re Umbérto.","Según la tradición, en 1889 la reina Margarita de Saboya estaba de visita en Nápoles con el rey Umberto."],["Il pizzaiolo Raffaele Esposito preparò per lei tre pizze diverse.","Il pit-tsaiólo Raf-faéle Espósito preparó per lei tre pít-tse divérse.","El pizzero Raffaele Esposito preparó para ella tres pizzas distintas."],["Alla regina piacque soprattutto quella con pomodoro, mozzarella e basilico, che ricordava i colori della bandiera italiana: rosso, bianco e verde.","Ál-la redyína piác-cue soprat-tút-to cuél-la con pomodóro, mot-tsarél-la e basílico, ke ricordáva i colóri dél-la bandiéra italiána: rós-so, biánco e vérde.","A la reina le gustó sobre todo la de tomate, mozzarella y albahaca, que recordaba los colores de la bandera italiana: rojo, blanco y verde."],["Per questo la pizza prese il nome di «Margherita».","Per cuésto la pít-tsa prése il nóme di «Margueríta».","Por eso la pizza tomó el nombre de «Margherita»."],["Gli storici, però, ricordano che a Napoli una pizza simile esisteva già prima.","Lli stórichi, peró, ricórdano ke a Nápoli úna pít-tsa símile esistéva dya príma.","Los historiadores, sin embargo, recuerdan que en Nápoles ya existía antes una pizza parecida."],["Oggi la pizza napoletana è una Specialità Tradizionale Garantita dell'Unione Europea.","Ód-dyi la pít-tsa napoletána e úna Spechalitá Tradit-tsionále Garantíta del-lunióne Européa.","Hoy la pizza napolitana es una Especialidad Tradicional Garantizada de la Unión Europea."],["Il disciplinare stabilisce gli ingredienti e il metodo: l'impasto si fa con farina, acqua, sale e lievito, e la pizza si cuoce nel forno a legna, a temperature molto alte.","Il dish-shiplináre stabilísh-she lli ingrediénti e il método: limpásto si fa con farína, ác-cua, sále e liévito, e la pít-tsa si cuóche nel fórno a léñ-ña, a temperatúre mólto álte.","El pliego de condiciones fija los ingredientes y el método: la masa se hace con harina, agua, sal y levadura, y la pizza se cuece en horno de leña, a temperaturas muy altas."],["Il bordo, chiamato «cornicione», deve essere morbido e gonfio.","Il bórdo, kiamáto «cornichóne», déve és-sere mórbido e gónfio.","El borde, llamado «cornicione», tiene que ser blando e hinchado."],["A Napoli la pizza si mangia anche per strada, piegata in quattro: è la cosiddetta pizza «a portafoglio».","A Nápoli la pít-tsa si mándya ánke per stráda, piegáta in cuát-tro: e la cosid-dét-ta pít-tsa «a portafóll-llo».","En Nápoles la pizza se come también por la calle, doblada en cuatro: es la llamada pizza «a portafoglio» (en cartera)."],["Nel 2017, inoltre, l'UNESCO ha riconosciuto l'arte dei pizzaiuoli napoletani come patrimonio culturale immateriale dell'umanità.","Nel 2017, inóltre, lunésco a riconosh-shúto lárte dei pit-tsaiuóli napoletáni cóme património culturále im-materiále del-lumanitá.","En 2017, además, la UNESCO reconoció el arte de los pizzeros napolitanos como patrimonio cultural inmaterial de la humanidad."]],"q":[["Qual è la patria della pizza?",["Roma","Napoli","Milano"],1,"«La sua patria è Napoli»."],["Chi preparò le pizze per la regina, secondo la tradizione?",["Il pizzaiolo Raffaele Esposito","Il re Umberto","Un cuoco della corte di Torino"],0,"«Il pizzaiolo Raffaele Esposito preparò per lei tre pizze diverse»."],["Che cosa ricordavano i colori della pizza Margherita?",["I colori della città di Napoli","I colori della casa Savoia","I colori della bandiera italiana"],2,"Rojo, blanco y verde: «i colori della bandiera italiana»."],["Che cosa dicono gli storici?",["Che la pizza è nata a Roma","Che a Napoli una pizza simile esisteva già prima","Che la regina non ha mai mangiato la pizza"],1,"«Una pizza simile esisteva già prima»."],["Che cosa ha riconosciuto l'UNESCO nel 2017?",["La pizza Margherita come piatto nazionale","Il forno a legna","L'arte dei pizzaiuoli napoletani"],2,"Reconoció «l'arte dei pizzaiuoli napoletani» como patrimonio inmaterial."]],"w":[["pizzaiolo","pit-tsaiólo","pizzero"],["impasto","impásto","masa"],["lievito","liévito","levadura"],["forno a legna","fórno a léñ-ña","horno de leña"],["cornicione","cornichóne","borde (de la pizza)"],["morbido","mórbido","blando, tierno"],["bandiera","bandiéra","bandera"],["disciplinare","dish-shiplináre","pliego de condiciones"]]},{"id":"l10","lvl":"B1","t":"Un tirocinio a Torino","tp":"Un tirochínio a Toríno","es_t":"Unas prácticas en Turín","topic":"trabajo","s":[["Paula è una studentessa spagnola di cucina e sta facendo un tirocinio di tre mesi in un ristorante di Torino.","Páula e úna studentés-sa spañ-ñóla di cuchína e sta fachéndo un tirochínio di tre mési in un ristoránte di Toríno.","Paula es una estudiante española de cocina y está haciendo unas prácticas de tres meses en un restaurante de Turín."],["Il primo giorno era molto nervosa: non conosceva nessuno e capiva poco l'italiano.","Il prímo dyórno éra mólto nervósa: non conosh-shéva nes-súno e capíva póco litaliáno.","El primer día estaba muy nerviosa: no conocía a nadie y entendía poco el italiano."],["Il capocuoco l'ha presentata alla brigata e l'ha messa alla partita degli antipasti, con un capo partita molto paziente.","Il capocuóco la presentáta ál-la brigáta e la més-sa ál-la partíta déll-lli antipásti, con un cápo partíta mólto pat-tsiénte.","El jefe de cocina la presentó a la brigada y la puso en la partida de entrantes, con un jefe de partida muy paciente."],["In cucina tutti parlano velocemente, ma Paula ha imparato subito le parole più importanti: «In arrivo!», «Pronto!» e «Attenzione, caldo!».","In cuchína tút-ti párlano velocheménte, ma Páula a imparáto súbito le paróle piu importánti: «In ar-rívo!», «Prónto!» e «At-tentsióne, cáldo!».","En la cocina todos hablan deprisa, pero Paula aprendió enseguida las palabras más importantes: «¡Marchando!», «¡Listo!» y «¡Cuidado, quema!»."],["Il ristorante propone piatti tipici piemontesi.","Il ristoránte propóne piát-ti típichi piemontési.","El restaurante ofrece platos típicos piamonteses."],["Paula ha imparato a preparare il vitello tonnato, carne di vitello fredda con una salsa di tonno, capperi e acciughe, e gli agnolotti del plin, piccoli ravioli chiusi con un pizzico delle dita.","Páula a imparáto a preparáre il vitél-lo ton-náto, cárne di vitél-lo fréd-da con úna sálsa di tón-no, cáp-peri e at-chúgue, e lli añ-ñolót-ti del plin, píc-coli ravióli kiúsi con un pít-tsico dél-le díta.","Paula ha aprendido a preparar el vitello tonnato, carne de ternera fría con una salsa de atún, alcaparras y anchoas, y los agnolotti del plin, pequeños raviolis cerrados con un pellizco de los dedos."],["In autunno, poi, è arrivata la stagione del tartufo bianco d'Alba, e il capocuoco lo tagliava a lamelle sottilissime sulla pasta fresca e sulle uova.","In autún-no, poi, e ar-riváta la stadyóne del tartúfo biánco dálba, e il capocuóco lo tall-lláva a lamél-le sot-tilís-sime súl-la pásta frésca e súl-le uóva.","En otoño, además, llegó la temporada de la trufa blanca de Alba, y el jefe de cocina la cortaba en láminas finísimas sobre la pasta fresca y sobre los huevos."],["Il lavoro è duro: Paula lavora dieci ore al giorno e ha un solo giorno libero alla settimana.","Il lavóro e dúro: Páula lavóra diéchi óre al dyórno e a un sólo dyórno líbero ál-la set-timána.","El trabajo es duro: Paula trabaja diez horas al día y tiene un solo día libre a la semana."],["Però è contenta, perché ogni giorno impara qualcosa di nuovo e il suo italiano migliora.","Peró e conténta, perké óñ-ñi dyórno impára cualcósa di nuóvo e il suo italiáno mill-llóra.","Pero está contenta, porque cada día aprende algo nuevo y su italiano mejora."],["Alla fine del tirocinio vuole chiedere al capocuoco una lettera di referenze.","Ál-la fíne del tirochínio vuóle kiédere al capocuóco úna lét-tera di referéntse.","Al final de las prácticas quiere pedirle al jefe de cocina una carta de referencias."]],"q":[["Che cosa fa Paula a Torino?",["Un corso di italiano","Un tirocinio di tre mesi in un ristorante","Una vacanza"],1,"«Sta facendo un tirocinio di tre mesi in un ristorante di Torino»."],["In quale partita lavora Paula?",["Agli antipasti","Ai dolci","Alla carne"],0,"La ponen «alla partita degli antipasti»."],["Che cos'è il vitello tonnato?",["Tonno cotto con il vino","Un tipo di ravioli","Carne di vitello fredda con una salsa di tonno, capperi e acciughe"],2,"Es ternera fría con salsa de atún, alcaparras y anchoas."],["Come si chiudono gli agnolotti del plin?",["Con una forchetta","Con un pizzico delle dita","Con una macchina"],1,"Son «piccoli ravioli chiusi con un pizzico delle dita»."],["Perché Paula è contenta?",["Perché ogni giorno impara qualcosa di nuovo","Perché lavora poche ore","Perché ha molti giorni liberi"],0,"Trabaja diez horas y tiene un solo día libre, pero aprende algo nuevo cada día."]],"w":[["tirocinio","tirochínio","prácticas"],["brigata","brigáta","brigada (de cocina)"],["capo partita","cápo partíta","jefe de partida"],["cappero","cáp-pero","alcaparra"],["acciuga","at-chúga","anchoa"],["pizzico","pít-tsico","pellizco"],["tartufo","tartúfo","trufa"],["capocuoco","capocuóco","jefe de cocina"]]},{"id":"l11","lvl":"B2","t":"Firenze e il Rinascimento","tp":"Firéntse e il Rinash-shiménto","es_t":"Florencia y el Renacimiento","topic":"cultura","s":[["Nel Quattrocento Firenze divenne il centro di una straordinaria stagione artistica e culturale, che oggi chiamiamo Rinascimento.","Nel Cuat-trochénto Firéntse divén-ne il chéntro di úna straordinária stadyóne artística e culturále, ke ód-dyi kiamiámo Rinash-shiménto.","En el siglo XV Florencia se convirtió en el centro de una extraordinaria época artística y cultural, que hoy llamamos Renacimiento."],["Gli artisti cercavano di riscoprire i modelli dell'antichità greca e romana e mettevano al centro l'uomo, studiato con uno sguardo nuovo, quasi scientifico.","Lli artísti chercávano di riscopríre i modél-li del-lantikitá gréca e romána e met-tévano al chéntro luómo, studiáto con úno sguárdo nuóvo, cuási shentífico.","Los artistas intentaban redescubrir los modelos de la Antigüedad griega y romana y ponían en el centro al ser humano, estudiado con una mirada nueva, casi científica."],["Un ruolo fondamentale ebbe la famiglia dei Medici, ricchi banchieri che governarono la città per gran parte del secolo.","Un ruólo fondamentále éb-be la famíll-lla dei Médichi, rík-ki bankiéri ke governárono la chit-tá per gran párte del sécolo.","Un papel fundamental lo tuvo la familia de los Médici, ricos banqueros que gobernaron la ciudad durante gran parte del siglo."],["Cosimo il Vecchio e, più tardi, suo nipote Lorenzo, detto il Magnifico, spesero somme enormi per finanziare pittori, scultori e architetti.","Cósimo il Vék-kio e, piu tárdi, suo nipóte Loréntso, dét-to il Mañ-ñífico, spésero sóm-me enórmi per finantsiáre pit-tóri, scultóri e arkitét-ti.","Cosme el Viejo y, más tarde, su nieto Lorenzo, llamado el Magnífico, gastaron sumas enormes para financiar a pintores, escultores y arquitectos."],["L'opera più famosa di quegli anni è forse la cupola della cattedrale di Santa Maria del Fiore, progettata da Filippo Brunelleschi e completata nel 1436.","Lópera piu famósa di cuéll-lli án-ni e fórse la cúpola dél-la cat-tedrále di Sánta María del Fióre, prodyet-táta da Filíp-po Brunel-léski e completáta nel 1436.","La obra más famosa de aquellos años es quizá la cúpula de la catedral de Santa Maria del Fiore, proyectada por Filippo Brunelleschi y terminada en 1436."],["Ancora oggi è la più grande cupola in muratura mai costruita.","Ancóra ód-dyi e la piu gránde cúpola in muratúra mai costruíta.","Todavía hoy es la cúpula de mampostería más grande jamás construida."],["Brunelleschi riuscì a realizzarla senza le grandi centine di legno che di solito sostenevano le cupole durante la costruzione, grazie anche a un sistema di mattoni disposti «a spina di pesce».","Brunel-léski riush-shí a realid-dsárla séntsa le grándi chéntine di léñ-ño ke di sólito sostenévano le cúpole duránte la costrut-tsióne, grát-tsie ánke a un sistéma di mat-tóni dispósti «a spína di pésh-she».","Brunelleschi consiguió construirla sin las grandes cimbras de madera que solían sostener las cúpulas durante la obra, gracias también a un sistema de ladrillos colocados «en espiga»."],["Nel corso del secolo lavorarono a Firenze Donatello, Botticelli e il giovane Michelangelo.","Nel córso del sécolo lavorárono a Firéntse Donatél-lo, Bot-tichél-li e il dyóvane Mikelándyelo.","A lo largo del siglo trabajaron en Florencia Donatello, Botticelli y el joven Miguel Ángel."],["Molte delle loro opere si possono ammirare agli Uffizi, dove si trova anche la celebre Nascita di Venere di Botticelli.","Mólte dél-le lóro ópere si pós-sono am-miráre áll-lli Uf-fít-tsi, dóve si tróva ánke la chélebre Násh-shita di Vénere di Bot-tichél-li.","Muchas de sus obras se pueden admirar en los Uffizi, donde se encuentra también el célebre Nacimiento de Venus de Botticelli."],["Il David di Michelangelo, invece, è conservato alla Galleria dell'Accademia; in piazza della Signoria se ne vede una copia.","Il Dávid di Mikelándyelo, invéche, e conserváto ál-la Gal-lería del-lac-cadémia; in piát-tsa dél-la Siñ-ñoría se ne véde úna cópia.","El David de Miguel Ángel, en cambio, se conserva en la Galería de la Academia; en la plaza de la Signoria se ve una copia."],["Michelangelo lo scolpì tra il 1501 e il 1504 da un unico blocco di marmo, già lavorato e abbandonato da altri scultori.","Mikelándyelo lo scolpí tra il 1501 e il 1504 da un único blóc-co di mármo, dya lavoráto e ab-bandonáto da áltri scultóri.","Miguel Ángel lo esculpió entre 1501 y 1504 a partir de un único bloque de mármol, ya trabajado y abandonado por otros escultores."],["Il Rinascimento fiorentino si diffuse poi in tutta Italia e in Europa, e cambiò per sempre il modo di guardare l'arte e il mondo.","Il Rinash-shiménto fiorentíno si dif-fúse poi in tút-ta Itália e in Európa, e cambió per sémpre il módo di guardáre lárte e il móndo.","El Renacimiento florentino se difundió luego por toda Italia y por Europa, y cambió para siempre la manera de mirar el arte y el mundo."]],"q":[["In quale secolo Firenze divenne il centro del Rinascimento?",["Nel Trecento","Nel Quattrocento","Nel Seicento"],1,"«Nel Quattrocento»: el siglo XV."],["Che ruolo ebbero i Medici?",["Finanziarono artisti e architetti","Progettarono la cupola del Duomo","Dipinsero la Nascita di Venere"],0,"«Spesero somme enormi per finanziare pittori, scultori e architetti»."],["Che cosa ha di speciale la cupola di Brunelleschi?",["È la più antica d'Italia","È tutta di marmo bianco","È la più grande cupola in muratura mai costruita"],2,"«Ancora oggi è la più grande cupola in muratura mai costruita»."],["Dove si trova oggi il David originale?",["In piazza della Signoria","Alla Galleria dell'Accademia","Agli Uffizi"],1,"En la plaza de la Signoria hay una copia; el original está en la Galleria dell'Accademia."],["Che cosa cercavano gli artisti del Rinascimento?",["Di riscoprire i modelli dell'antichità greca e romana","Di copiare l'arte gotica","Di dipingere solo temi religiosi"],0,"«Cercavano di riscoprire i modelli dell'antichità greca e romana»."]],"w":[["Rinascimento","Rinash-shiménto","Renacimiento"],["cupola","cúpola","cúpula"],["mattone","mat-tóne","ladrillo"],["banchiere","bankiére","banquero"],["pittore","pit-tóre","pintor"],["scultore","scultóre","escultor"],["centina","chéntina","cimbra"],["celebre","chélebre","célebre"]]},{"id":"l12","lvl":"B2","t":"I marchi di origine dei prodotti italiani","tp":"I márki di orídyine dei prodót-ti italiáni","es_t":"Los sellos de origen de los productos italianos","topic":"gastronomía","s":[["Sulle etichette dei prodotti alimentari italiani si trovano spesso dei marchi europei che garantiscono l'origine e la qualità.","Súl-le etikét-te dei prodót-ti alimentári italiáni si tróvano spés-so dei márki européi ke garantíscono lorídyine e la cualitá.","En las etiquetas de los productos alimentarios italianos se encuentran a menudo sellos europeos que garantizan el origen y la calidad."],["Il più rigoroso è la Denominazione di Origine Protetta, la DOP: tutte le fasi della produzione, dalla materia prima al prodotto finito, devono avvenire in una zona geografica precisa.","Il piu rigoróso e la Denominat-tsióne di Orídyine Protét-ta, la Dop: tút-te le fási dél-la produt-tsióne, dál-la matéria príma al prodót-to finíto, dévono av-veníre in úna dsóna dyeográfica prechísa.","El más riguroso es la Denominación de Origen Protegida, la DOP: todas las fases de la producción, desde la materia prima hasta el producto acabado, tienen que tener lugar en una zona geográfica concreta."],["Ne sono esempi il Prosciutto di Parma, la Mozzarella di Bufala Campana e il Parmigiano Reggiano.","Ne sóno esémpi il Prosh-shút-to di Párma, la Mot-tsarél-la di Búfala Campána e il Parmidyáno Red-dyáno.","Son ejemplos el jamón de Parma, la mozzarella de búfala de Campania y el Parmigiano Reggiano."],["L'Indicazione Geografica Protetta è meno restrittiva: basta che almeno una fase della produzione si svolga nel territorio indicato.","Lindicat-tsióne Dyeográfica Protét-ta e méno restrit-tíva: básta ke alméno úna fáse dél-la produt-tsióne si svólga nel ter-ritório indicáto.","La Indicación Geográfica Protegida es menos restrictiva: basta con que al menos una fase de la producción se lleve a cabo en el territorio indicado."],["Per questo la bresaola della Valtellina può essere prodotta con carne bovina che non proviene dalla Valtellina, purché la lavorazione avvenga in quella zona.","Per cuésto la bresaóla dél-la Valtel-lína puo és-sere prodót-ta con cárne bovína ke non proviéne dál-la Valtel-lína, purké la lavorat-tsióne av-vénga in cuél-la dsóna.","Por eso la bresaola de la Valtellina puede elaborarse con carne de vacuno que no procede de la Valtellina, siempre que el procesado se haga en esa zona."],["Tra i prodotti con indicazione geografica protetta ci sono anche l'aceto balsamico di Modena e il lardo di Colonnata.","Tra i prodót-ti con indicat-tsióne dyeográfica protét-ta chi sóno ánke lachéto balsámico di Módena e il lárdo di Colon-náta.","Entre los productos con indicación geográfica protegida están también el vinagre balsámico de Módena y el lardo de Colonnata."],["La Specialità Tradizionale Garantita, infine, non tutela l'origine geografica, ma una ricetta o un metodo di produzione tradizionale: la pizza napoletana, per esempio, si può fare con quel nome anche fuori dalla Campania, se si rispetta il disciplinare.","La Spechalitá Tradit-tsionále Garantíta, infíne, non tutéla lorídyine dyeográfica, ma úna richét-ta o un método di produt-tsióne tradit-tsionále: la pít-tsa napoletána, per esémpio, si puo fáre con cuel nóme ánke fuóri dál-la Campánia, se si rispét-ta il dish-shiplináre.","La Especialidad Tradicional Garantizada, por último, no protege el origen geográfico, sino una receta o un método de producción tradicional: la pizza napolitana, por ejemplo, puede hacerse con ese nombre también fuera de Campania, si se respeta el pliego de condiciones."],["Il disciplinare è un documento ufficiale che descrive in modo dettagliato le materie prime, le tecniche di lavorazione e le caratteristiche del prodotto finale.","Il dish-shiplináre e un documénto uf-fichále ke descríve in módo det-tall-lláto le matérie príme, le técnike di lavorat-tsióne e le carat-terístike del prodót-to finále.","El pliego de condiciones es un documento oficial que describe de forma detallada las materias primas, las técnicas de elaboración y las características del producto final."],["A controllare che le regole vengano rispettate sono i consorzi di tutela e gli organismi di controllo autorizzati.","A control-láre ke le régole véngano rispet-táte sóno i consórtsi di tutéla e lli organísmi di contról-lo autorid-dsáti.","De controlar que se respeten las normas se encargan los consorcios de protección y los organismos de control autorizados."],["Anche il vino ha le sue denominazioni, come la Denominazione di Origine Controllata e Garantita, riservata a vini di particolare pregio, tra cui il Barolo, il Brunello di Montalcino e il Chianti Classico.","Ánke il víno a le sue denominat-tsióni, cóme la Denominat-tsióne di Orídyine Control-láta e Garantíta, riserváta a víni di particoláre prédyo, tra cui il Barólo, il Brunél-lo di Montalchíno e il Kiánti Clás-sico.","También el vino tiene sus denominaciones, como la Denominación de Origen Controlada y Garantizada, reservada a vinos de especial calidad, entre ellos el Barolo, el Brunello di Montalcino y el Chianti Classico."],["L'Italia è il paese dell'Unione Europea con il maggior numero di prodotti alimentari a denominazione di origine e a indicazione geografica.","Litália e il paése del-lunióne Européa con il mad-dyór número di prodót-ti alimentári a denominat-tsióne di orídyine e a indicat-tsióne dyeográfica.","Italia es el país de la Unión Europea con el mayor número de productos alimentarios con denominación de origen e indicación geográfica."],["Per un cuoco, conoscere questi marchi significa saper scegliere materie prime di qualità e saperle raccontare ai clienti.","Per un cuóco, conósh-shere cuésti márki siñ-ñífica sapér shéll-llere matérie príme di cualitá e sapérle rac-contáre ai cliénti.","Para un cocinero, conocer estos sellos significa saber elegir materias primas de calidad y saber explicárselas a los clientes."]],"q":[["Che cosa garantisce la DOP?",["Che tutte le fasi della produzione avvengono in una zona precisa","Che almeno una fase avviene in Italia","Che il prodotto è biologico"],0,"En la DOP «tutte le fasi della produzione [...] devono avvenire in una zona geografica precisa»."],["Perché la bresaola della Valtellina può essere fatta con carne che non viene dalla Valtellina?",["Perché è una Specialità Tradizionale Garantita","Perché ha l'indicazione geografica protetta: basta che la lavorazione avvenga in quella zona","Perché non ha nessun marchio"],1,"Es IGP: basta con que una fase, aquí el procesado, se haga en la zona."],["Che cosa tutela la Specialità Tradizionale Garantita?",["Una zona geografica","Il prezzo del prodotto","Una ricetta o un metodo di produzione tradizionale"],2,"«Non tutela l'origine geografica, ma una ricetta o un metodo di produzione tradizionale»."],["Che cos'è il disciplinare?",["Un documento ufficiale che descrive materie prime, tecniche e caratteristiche del prodotto","Una multa per chi non rispetta le regole","Un consorzio di produttori"],0,"Es el pliego de condiciones de cada producto."],["Quale di questi vini è citato nel testo?",["Il Prosecco","Il Brunello di Montalcino","Il Lambrusco"],1,"El texto cita Barolo, Brunello di Montalcino y Chianti Classico."]],"w":[["etichetta","etikét-ta","etiqueta"],["marchio","márkio","sello, marca"],["materia prima","matéria príma","materia prima"],["disciplinare","dish-shiplináre","pliego de condiciones"],["tutelare","tuteláre","proteger, tutelar"],["lavorazione","lavorat-tsióne","elaboración, procesado"],["consorzio","consórtsio","consorcio"],["pregio","prédyo","valor, calidad"]]},{"id":"l13","lvl":"B2","t":"Dormire in un agriturismo","tp":"Dormíre in un agriturísmo","es_t":"Dormir en un agroturismo","topic":"viaje","s":[["Chi viaggia in Italia ha molte possibilità di alloggio: dagli alberghi alle pensioni, dagli ostelli agli appartamenti in affitto per brevi periodi.","Ki viád-dya in Itália a mólte pos-sibilitá di al-lód-dyo: dáll-lli albérgui ál-le pensióni, dáll-lli ostél-li áll-lli ap-partaménti in af-fít-to per brévi períodi.","Quien viaja por Italia tiene muchas posibilidades de alojamiento: desde los hoteles hasta las pensiones, desde los albergues hasta los apartamentos de alquiler por periodos cortos."],["Una delle formule più interessanti, soprattutto per chi ama la cucina, è però l'agriturismo.","Úna dél-le fórmule piu interes-sánti, soprat-tút-to per ki áma la cuchína, e peró lagriturísmo.","Una de las fórmulas más interesantes, sobre todo para quien ama la cocina, es sin embargo el agroturismo."],["Per legge, un agriturismo è un'impresa agricola che, accanto all'attività di coltivazione o di allevamento, offre ospitalità ai turisti.","Per léd-dye, un agriturísmo e unimprésa agrícola ke, ac-cánto al-lat-tivitá di coltivat-tsióne o di al-levaménto, óf-fre ospitalitá ai turísti.","Por ley, un agroturismo es una empresa agrícola que, junto a la actividad de cultivo o de cría de animales, ofrece alojamiento a los turistas."],["L'attività agricola deve rimanere quella principale: l'ospitalità è un'attività in più e non può sostituirla.","Lat-tivitá agrícola déve rimanére cuél-la princhipále: lospitalitá e unat-tivitá in piu e non puo sostituírla.","La actividad agrícola tiene que seguir siendo la principal: el alojamiento es una actividad añadida y no puede sustituirla."],["Molti agriturismi si trovano in campagna, in vecchi casali ristrutturati, e hanno un ristorante dove si servono i prodotti della fattoria: olio, vino, formaggi, salumi e verdure dell'orto.","Mólti agriturísmi si tróvano in campáñ-ña, in vék-ki casáli ristrut-turáti, e án-no un ristoránte dóve si sérvono i prodót-ti dél-la fat-toría: ólio, víno, formád-dyi, salúmi e verdúre del-lórto.","Muchos agroturismos están en el campo, en viejas casas de campo rehabilitadas, y tienen un restaurante donde se sirven los productos de la finca: aceite, vino, quesos, embutidos y verduras del huerto."],["In regioni come la Toscana, l'Umbria e le Marche ce ne sono moltissimi.","In redyóni cóme la Toscána, lúmbria e le Márke che ne sóno moltís-simi.","En regiones como la Toscana, Umbría y las Marcas hay muchísimos."],["Di solito si prenota in rete o per telefono, e conviene chiedere in anticipo se la cena è compresa nel prezzo.","Di sólito si prenóta in réte o per teléfono, e conviéne kiédere in antíchipo se la chéna e comprésa nel prét-tso.","Normalmente se reserva por internet o por teléfono, y conviene preguntar con antelación si la cena está incluida en el precio."],["Al momento dell'arrivo il gestore chiede un documento d'identità: la legge italiana obbliga chi offre alloggio a comunicare alla polizia i dati degli ospiti.","Al moménto del-lar-rívo il dyestóre kiéde un documénto didentitá: la léd-dye italiána ób-bliga ki óf-fre al-lód-dyo a comunicáre ál-la polit-tsía i dáti déll-lli óspiti.","En el momento de la llegada, el encargado pide un documento de identidad: la ley italiana obliga a quien ofrece alojamiento a comunicar a la policía los datos de los huéspedes."],["Inoltre, in molti comuni si paga la tassa di soggiorno, un piccolo importo per persona e per notte che spesso va pagato a parte.","Inóltre, in mólti comúni si pága la tás-sa di sod-dyórno, un píc-colo impórto per persóna e per nót-te ke spés-so va pagáto a párte.","Además, en muchos municipios se paga la tasa turística, un pequeño importe por persona y noche que a menudo hay que pagar aparte."],["La cifra cambia da un comune all'altro e, in alcune località, anche a seconda della stagione.","La chífra cámbia da un comúne al-láltro e, in alcúne localitá, ánke a secónda dél-la stadyóne.","La cantidad cambia de un municipio a otro y, en algunas localidades, también según la temporada."],["Chi sceglie un agriturismo, comunque, non cerca il lusso, ma la tranquillità, il contatto con la natura e la possibilità di mangiare i piatti della tradizione locale, preparati con ingredienti a chilometro zero.","Ki shéll-lle un agriturísmo, comúncue, non chérca il lús-so, ma la trancuil-litá, il contát-to con la natúra e la pos-sibilitá di mandyáre i piát-ti dél-la tradit-tsióne locále, preparáti con ingrediénti a kilómetro dséro.","En cualquier caso, quien elige un agroturismo no busca el lujo, sino la tranquilidad, el contacto con la naturaleza y la posibilidad de comer los platos de la tradición local, preparados con ingredientes de kilómetro cero."],["Alcune strutture organizzano anche corsi di cucina, visite in cantina o la raccolta delle olive in autunno.","Alcúne strut-túre organíd-dsano ánke córsi di cuchína, vísite in cantína o la rac-cólta dél-le olíve in autún-no.","Algunos alojamientos organizan también cursos de cocina, visitas a la bodega o la recogida de la aceituna en otoño."]],"q":[["Che cos'è un agriturismo, secondo la legge?",["Un albergo di lusso in campagna","Un'impresa agricola che offre anche ospitalità ai turisti","Un ristorante tipico"],1,"«Un'impresa agricola che, accanto all'attività di coltivazione o di allevamento, offre ospitalità»."],["Quale attività deve restare principale?",["L'attività agricola","La ristorazione","L'ospitalità"],0,"«L'attività agricola deve rimanere quella principale»."],["Perché il gestore chiede un documento d'identità?",["Per fare la fattura","Per controllare l'età degli ospiti","Perché la legge obbliga a comunicare alla polizia i dati degli ospiti"],2,"Es una obligación legal de quien ofrece alojamiento."],["Che cos'è la tassa di soggiorno?",["Il prezzo della cena","Un piccolo importo per persona e per notte","Una multa per chi arriva tardi"],1,"«Un piccolo importo per persona e per notte», que cambia según el municipio."],["Che cosa cerca chi sceglie un agriturismo, secondo il testo?",["Il lusso e la vita notturna","I prezzi più bassi d'Italia","La tranquillità, la natura e la cucina locale"],2,"«Non cerca il lusso, ma la tranquillità, il contatto con la natura» y la cocina local."]],"w":[["alloggio","al-lód-dyo","alojamiento"],["casale","casále","casa de campo, cortijo"],["allevamento","al-levaménto","cría de animales, ganadería"],["tassa di soggiorno","tás-sa di sod-dyórno","tasa turística"],["gestore","dyestóre","encargado, gerente"],["ospite","óspite","huésped (también: anfitrión)"],["a chilometro zero","a kilómetro dséro","de kilómetro cero"],["raccolta","rac-cólta","recogida, cosecha"]]},{"id":"l14","lvl":"B2","t":"Diventare cuoco in Italia: l'istituto alberghiero","tp":"Diventáre cuóco in Itália: listitúto alberguiéro","es_t":"Hacerse cocinero en Italia: el instituto de hostelería","topic":"trabajo","s":[["In Italia molti cuochi cominciano la loro formazione a quattordici anni, quando si iscrivono all'istituto alberghiero.","In Itália mólti cuóki comínchano la lóro format-tsióne a cuat-tórdichi án-ni, cuándo si iscrívono al-listitúto alberguiéro.","En Italia muchos cocineros empiezan su formación a los catorce años, cuando se matriculan en el instituto de hostelería."],["Il nome ufficiale di queste scuole è più lungo, «Istituto professionale per i servizi per l'enogastronomia e l'ospitalità alberghiera», ma tutti le chiamano semplicemente «l'alberghiero».","Il nóme uf-fichále di cuéste scuóle e piu lúngo, «Istitúto profes-sionále per i servít-tsi per lenogastronomía e lospitalitá alberguiéra», ma tút-ti le kiámano semplicheménte «lalberguiéro».","El nombre oficial de estos centros es más largo, «Instituto profesional para los servicios de enogastronomía y hostelería», pero todos los llaman simplemente «l'alberghiero»."],["Il percorso dura cinque anni e si conclude con l'esame di Stato, la cosiddetta maturità, che permette anche di iscriversi all'università.","Il percórso dúra chíncue án-ni e si conclúde con lesáme di Státo, la cosid-dét-ta maturitá, ke permét-te ánke di iscríversi al-luniversitá.","El itinerario dura cinco años y termina con el examen de Estado, la llamada «maturità», que permite también matricularse en la universidad."],["Accanto alle materie generali, come l'italiano, la matematica e le lingue straniere, gli studenti fanno esperienza nei laboratori di cucina, di sala e vendita e di accoglienza turistica.","Ac-cánto ál-le matérie dyeneráli, cóme litaliáno, la matemática e le língüe straniére, lli studénti fán-no esperiéntsa nei laboratóri di cuchína, di sála e véndita e di ac-coll-lléntsa turística.","Junto a las asignaturas generales, como el italiano, las matemáticas y las lenguas extranjeras, los alumnos hacen prácticas en los talleres de cocina, de sala y venta y de recepción turística."],["Dal terzo anno in poi gli studenti si specializzano: c'è chi sceglie la cucina o la pasticceria, chi il servizio di sala e chi l'accoglienza negli alberghi.","Dal tértso án-no in poi lli studénti si spechalíd-dsano: che ki shéll-lle la cuchína o la pastit-chería, ki il servít-tsio di sála e ki lac-coll-lléntsa néll-lli albérgui.","A partir del tercer año los alumnos se especializan: hay quien elige la cocina o la pastelería, quien el servicio de sala y quien la recepción en los hoteles."],["Una parte importante della formazione si svolge fuori dalla scuola: con i percorsi che un tempo si chiamavano «alternanza scuola-lavoro», gli studenti lavorano per alcune settimane in ristoranti, alberghi e pasticcerie.","Úna párte importánte dél-la format-tsióne si svóldye fuóri dál-la scuóla: con i percórsi ke un témpo si kiamávano «alternántsa scuóla-lavóro», lli studénti lavórano per alcúne set-timáne in ristoránti, albérgui e pastit-cheríe.","Una parte importante de la formación se desarrolla fuera del centro: con los itinerarios que antes se llamaban «alternancia escuela-trabajo», los alumnos trabajan algunas semanas en restaurantes, hoteles y pastelerías."],["Molti ragazzi fanno anche la stagione estiva negli alberghi delle località turistiche, al mare o in montagna.","Mólti ragát-tsi fán-no ánke la stadyóne estíva néll-lli albérgui dél-le localitá turístike, al máre o in montáñ-ña.","Muchos chicos hacen también la temporada de verano en los hoteles de las localidades turísticas, en la playa o en la montaña."],["Accanto alla scuola statale esiste un'altra strada, quella dei corsi regionali di istruzione e formazione professionale, che durano di solito tre anni e rilasciano una qualifica, per esempio quella di «operatore della ristorazione».","Ac-cánto ál-la scuóla statále esíste unáltra stráda, cuél-la dei córsi redyonáli di istrut-tsióne e format-tsióne profes-sionále, ke dúrano di sólito tre án-ni e rilásh-shano úna cualífica, per esémpio cuél-la di «operatóre dél-la ristorat-tsióne».","Junto al centro estatal existe otro camino, el de los cursos regionales de educación y formación profesional, que suelen durar tres años y otorgan una cualificación, por ejemplo la de «operador de restauración»."],["Rispetto al ciclo formativo di grado medio spagnolo, a cui si accede di solito a sedici anni dopo l'ESO, il percorso italiano comincia prima e dura più a lungo.","Rispét-to al chíclo formatívo di grádo médio spañ-ñólo, a cui si at-chéde di sólito a sédichi án-ni dópo léso, il percórso italiáno comíncha príma e dúra piu a lúngo.","En comparación con el ciclo formativo de grado medio español, al que normalmente se accede a los dieciséis años después de la ESO, el itinerario italiano empieza antes y dura más."],["In tutti e due i paesi, però, l'idea di fondo è la stessa: in cucina si impara soprattutto facendo.","In tút-ti e due i paési, peró, lidéa di fóndo e la stés-sa: in cuchína si impára soprat-tút-to fachéndo.","En los dos países, sin embargo, la idea de fondo es la misma: en la cocina se aprende sobre todo haciendo."]],"q":[["A che età si comincia di solito l'istituto alberghiero?",["A sedici anni","A quattordici anni","A diciotto anni"],1,"«A quattordici anni, quando si iscrivono all'istituto alberghiero»."],["Con che cosa si conclude il percorso di cinque anni?",["Con l'esame di Stato, la maturità","Con una qualifica regionale","Con un concorso pubblico"],0,"«Si conclude con l'esame di Stato, la cosiddetta maturità»."],["Come si chiamavano un tempo i percorsi di formazione fuori dalla scuola?",["Stagioni estive","Tirocini regionali","Alternanza scuola-lavoro"],2,"«Un tempo si chiamavano “alternanza scuola-lavoro”»."],["Quanto durano di solito i corsi regionali di istruzione e formazione professionale?",["Cinque anni","Un anno","Tre anni"],2,"«Durano di solito tre anni e rilasciano una qualifica»."],["Qual è, secondo il testo, la differenza principale con il grado medio spagnolo?",["In Italia non si fanno tirocini","Il percorso italiano comincia prima e dura più a lungo","In Spagna si comincia a quattordici anni"],1,"En España se accede normalmente a los 16 años, después de la ESO; en Italia, a los 14."]],"w":[["istituto alberghiero","istitúto alberguiéro","instituto de hostelería"],["pasticciere","pastit-chére","pastelero"],["accoglienza","ac-coll-lléntsa","recepción, acogida"],["tirocinio","tirochínio","prácticas"],["qualifica","cualífica","cualificación, título"],["stagione","stadyóne","temporada"],["maturità","maturitá","examen de Estado de fin de secundaria"],["iscriversi","iscríversi","matricularse"]]},{"id":"l15","lvl":"B2","t":"Il panettone e le feste di Natale","tp":"Il panet-tóne e le féste di Natále","es_t":"El panettone y las fiestas de Navidad","topic":"costumbres","s":[["Tra novembre e dicembre, nelle vetrine delle pasticcerie e dei supermercati italiani compaiono le grandi scatole del panettone, il dolce natalizio più famoso del paese.","Tra novémbre e dichémbre, nél-le vetríne dél-le pastit-cheríe e dei supermercáti italiáni compáiono le grándi scátole del panet-tóne, il dólche natalít-tsio piu famóso del paése.","Entre noviembre y diciembre, en los escaparates de las pastelerías y de los supermercados italianos aparecen las grandes cajas del panettone, el dulce navideño más famoso del país."],["Nato a Milano, è un grande lievitato a forma di cupola, con uvetta e scorze di arancia candite.","Náto a Miláno, e un gránde lievitáto a fórma di cúpola, con uvét-ta e scórtse di aráncha candíte.","Nacido en Milán, es un gran bollo fermentado con forma de cúpula, con pasas y cortezas de naranja confitadas."],["Sulla sua origine esistono diverse leggende: secondo la più nota, alla corte di Ludovico il Moro, alla fine del Quattrocento, il cuoco bruciò il dolce preparato per il banchetto di Natale, e un giovane aiutante di nome Toni salvò la situazione con un pane dolce preparato con gli avanzi della cucina.","Súl-la sua orídyine esístono divérse led-dyénde: secóndo la piu nóta, ál-la córte di Ludovíco il Móro, ál-la fíne del Cuat-trochénto, il cuóco bruchó il dólche preparáto per il bankét-to di Natále, e un dyóvane aiutánte di nóme Tóni salvó la situat-tsióne con un páne dólche preparáto con lli avántsi dél-la cuchína.","Sobre su origen existen varias leyendas: según la más conocida, en la corte de Ludovico el Moro, a finales del siglo XV, el cocinero quemó el dulce preparado para el banquete de Navidad, y un joven ayudante llamado Toni salvó la situación con un pan dulce hecho con las sobras de la cocina."],["Da qui, secondo la leggenda, il nome «pan del Toni».","Da cui, secóndo la led-dyénda, il nóme «pan del Tóni».","De ahí, según la leyenda, el nombre «pan del Toni»."],["Al di là delle leggende, il panettone è un prodotto molto difficile da preparare.","Al di la dél-le led-dyénde, il panet-tóne e un prodót-to mólto dif-fíchile da preparáre.","Más allá de las leyendas, el panettone es un producto muy difícil de elaborar."],["Si fa con il lievito madre, una pasta acida che si rinfresca regolarmente con farina e acqua, e richiede una lavorazione lunga, con più impasti e lievitazioni che, in tutto, durano spesso più di un giorno.","Si fa con il liévito mádre, úna pásta áchida ke si rinfrésca regolarménte con farína e ác-cua, e rikiéde úna lavorat-tsióne lúnga, con piu impásti e lievitat-tsióni ke, in tút-to, dúrano spés-so piu di un dyórno.","Se hace con masa madre, una masa ácida que se refresca con regularidad con harina y agua, y requiere una elaboración larga, con varios amasados y fermentaciones que, en total, a menudo duran más de un día."],["Una volta cotto, il panettone si appende a testa in giù per alcune ore, perché non si sgonfi mentre si raffredda.","Úna vólta cót-to, il panet-tóne si ap-pénde a tésta in dyu per alcúne óre, perké non si sgónfi méntre si raf-fréd-da.","Una vez cocido, el panettone se cuelga boca abajo durante unas horas, para que no se desinfle mientras se enfría."],["A Verona, invece, è nato il pandoro, senza canditi né uvetta, a forma di stella a otto punte e coperto di zucchero a velo.","A Veróna, invéche, e náto il pandóro, séntsa candíti ne uvét-ta, a fórma di stél-la a ót-to púnte e copérto di dsúk-kero a vélo.","En Verona, en cambio, nació el pandoro, sin fruta confitada ni pasas, con forma de estrella de ocho puntas y cubierto de azúcar glas."],["Ogni anno la sfida tra panettone e pandoro divide famiglie e amici, ma molti italiani, alla fine, li comprano tutti e due.","Óñ-ñi án-no la sfída tra panet-tóne e pandóro divíde famíll-lle e amíchi, ma mólti italiáni, ál-la fíne, li cómprano tút-ti e due.","Cada año el duelo entre panettone y pandoro divide a familias y amigos, pero muchos italianos, al final, compran los dos."],["Il panettone, comunque, non è l'unico protagonista delle feste: in molte regioni la sera della Vigilia si fa una cena di magro, spesso a base di pesce, e il pranzo del giorno di Natale riunisce tutta la famiglia.","Il panet-tóne, comúncue, non e lúnico protagonísta dél-le féste: in mólte redyóni la séra dél-la Vidyília si fa úna chéna di mágro, spés-so a báse di pésh-she, e il prántso del dyórno di Natále riunísh-she tút-ta la famíll-lla.","El panettone, de todos modos, no es el único protagonista de las fiestas: en muchas regiones la noche de Nochebuena se hace una cena sin carne, a menudo a base de pescado, y la comida del día de Navidad reúne a toda la familia."],["Le feste si chiudono il 6 gennaio con l'Epifania, quando, secondo la tradizione popolare, la Befana porta dolci ai bambini buoni e carbone a quelli cattivi.","Le féste si kiúdono il 6 dyen-náio con lepifanía, cuándo, secóndo la tradit-tsióne popoláre, la Befána pórta dólchi ai bambíni buóni e carbóne a cuél-li cat-tívi.","Las fiestas terminan el 6 de enero con la Epifanía, cuando, según la tradición popular, la Befana trae dulces a los niños buenos y carbón a los malos."]],"q":[["In quale città è nato il panettone?",["Verona","Milano","Torino"],1,"«Nato a Milano»; el pandoro, en cambio, nació en Verona."],["Secondo la leggenda più nota, chi salvò il banchetto di Ludovico il Moro?",["Un giovane aiutante di nome Toni","Il cuoco della corte","Ludovico il Moro in persona"],0,"El cocinero quemó el dulce y el joven ayudante Toni salvó la situación."],["Perché il panettone si appende a testa in giù dopo la cottura?",["Per farlo asciugare più in fretta","Per decorarlo","Perché non si sgonfi mentre si raffredda"],2,"«Perché non si sgonfi mentre si raffredda»."],["Come si riconosce il pandoro?",["Ha uvetta e canditi","Ha la forma di una stella a otto punte ed è coperto di zucchero a velo","È ricoperto di cioccolato"],1,"No lleva fruta confitada ni pasas y tiene forma de estrella de ocho puntas."],["Che cosa porta la Befana ai bambini cattivi, secondo la tradizione?",["Carbone","Dolci","Un panettone"],0,"«Dolci ai bambini buoni e carbone a quelli cattivi»."]],"w":[["lievito madre","liévito mádre","masa madre"],["uvetta","uvét-ta","pasas"],["canditi","candíti","fruta confitada"],["vetrina","vetrína","escaparate"],["zucchero a velo","dsúk-kero a vélo","azúcar glas"],["Vigilia di Natale","Vidyília di Natále","Nochebuena"],["cena di magro","chéna di mágro","cena sin carne"],["sgonfiarsi","sgonfiársi","desinflarse"]]}],"exams":[{"id":"A2","t":"Simulacro de examen A2","intro":"Simulacro completo de la prueba de certificación de nivel Básico A2 de italiano de las Escuelas Oficiales de Idiomas de Andalucía, con la estructura que describe la Guía del candidato (EOI de Chiclana, 2022-23). Tiene cuatro partes: comprensión de textos orales (máx. 30 min), comprensión de textos escritos (40 min), producción y coproducción escritas (45 min) y producción, coproducción y mediación orales. Cada audio se escucha dos veces. Según esa guía, el nivel Básico A2 se califica como Apto o No apto; como referencia, en B1 se exige al menos un 5 en cada parte y una media de 6,5 o más. Confirma en tu escuela los criterios del curso actual. Las tareas de expresión se autoevalúan con la respuesta modelo y la lista de criterios.","parts":[{"k":"cto","t":"Comprensión de textos orales","min":30,"tasks":[{"t":"Tarea 1","ins":"Va a escuchar seis mensajes breves (anuncios y mensajes de voz). Escuchará la grabación dos veces. Para cada mensaje, elija la opción correcta (a, b o c).","audio":[["1","Attenzione. Il treno regionale per Pisa Centrale, in partenza alle ore undici e venti, partirà dal binario sette, invece che dal binario quattro. Ci scusiamo per il disagio.","At-tentsióne. Il tréno redyonále per Písa Chentrále, in parténtsa ál-le óre úndichi e vénti, partirá dal binário sét-te, invéche ke dal binário cuát-tro. Chi scusiámo per il disádyo."],["2","Gentili clienti, solo per oggi, nel reparto pescheria, trovate il salmone fresco a quindici euro al kilo. Vi aspettiamo al banco del pesce, in fondo al negozio, accanto alla frutta e verdura.","Dyentíli cliénti, sólo per ód-dyi, nel repárto peskería, trováte il salmóne frésco a cuíndichi éuro al kílo. Vi aspet-tiámo al bánco del pésh-she, in fóndo al negót-tsio, ac-cánto ál-la frút-ta e verdúra."],["3","Gentili visitatori, vi informiamo che il museo chiuderà tra quindici minuti. La biglietteria è già chiusa. Il negozio del museo resterà aperto fino alle diciannove. Grazie e arrivederci.","Dyentíli visitatóri, vi informiámo ke il muséo kiuderá tra cuíndichi minúti. La bill-llet-tería e dya kiúsa. Il negót-tsio del muséo resterá apérto fíno ál-le dichan-nóve. Grát-tsie e ar-rivedérchi."],["4","Buongiorno, signor Ruiz, sono Laura dello studio dentistico Bianchi. La chiamo perché domani mattina la dottoressa non c'è. Possiamo spostare il suo appuntamento a giovedì, alle quattro del pomeriggio? Ci richiami, per favore. Grazie.","Buondyórno, siñ-ñór Ruits, sóno Láura dél-lo stúdio dentístico Biánki. La kiámo perké dománi mat-tína la dot-tóres-sa non che. Pos-siámo spostáre il suo ap-puntaménto a dyovedí, ál-le cuát-tro del pomeríd-dyo? Chi rikiámi, per favóre. Grát-tsie."],["5","E ora il meteo per domani a Roma. Al mattino cielo nuvoloso e un po' di pioggia; nel pomeriggio tornerà il sole. Temperature tra i quattordici e i ventuno gradi.","E óra il méteo per dománi a Róma. Al mat-tíno chélo nuvolóso e un po di piód-dya; nel pomeríd-dyo tornerá il sóle. Temperatúre tra i cuat-tórdichi e i ventúno grádi."],["6","Buonasera, qui è la trattoria Il Girasole. Confermiamo la sua prenotazione per sabato sera, alle venti e trenta, per quattro persone. Se ci sono cambiamenti, ci mandi un messaggio entro venerdì. A presto!","Buonaséra, cui e la trat-toría Il Dyirasóle. Confermiámo la súa prenotat-tsióne per sábato séra, ál-le vénti e trénta, per cuát-tro persóne. Se chi sóno cambiaménti, chi mándi un mes-sád-dyo éntro venerdí. A présto!"]],"items":[{"q":"1. Da quale binario parte il treno per Pisa?","o":["Dal binario 4","Dal binario 7","Dal binario 11"],"a":1},{"q":"2. Dove si trova il banco del pesce?","o":["Vicino alle casse","All'ingresso del negozio","In fondo al negozio"],"a":2},{"q":"3. Che cosa resta aperto fino alle 19?","o":["La biglietteria","Il negozio del museo","Le sale del museo"],"a":1},{"q":"4. Perché telefona Laura?","o":["Per confermare l'appuntamento di domani","Per chiedere un nuovo numero di telefono","Per cambiare il giorno dell'appuntamento"],"a":2},{"q":"5. Che tempo farà domani pomeriggio a Roma?","o":["Ci sarà il sole","Pioverà","Tirerà vento"],"a":0},{"q":"6. Entro quando bisogna avvisare se ci sono cambiamenti?","o":["Entro sabato mattina","Entro venerdì","Entro le 20:30 di sabato"],"a":1}]},{"t":"Tarea 2","ins":"Va a escuchar una conversación entre dos amigos, Marco y Elena, que hablan de sus planes para el sábado. Escuchará la grabación dos veces. Indique si las afirmaciones son verdaderas (Vero) o falsas (Falso).","audio":[["Marco","Ciao Elena! Che cosa fai sabato?","Cháo Eléna! Ke cósa fai sábato?"],["Elena","Ciao Marco! Ancora non lo so. Perché?","Cháo Márco! Ancóra non lo so. Perké?"],["Marco","C'è una sagra del tartufo in un paese vicino ad Alba. Ci vuoi venire?","Che úna ságra del tartúfo in un paése vichíno ad Álba. Chi vuoi veníre?"],["Elena","Che bello! Ma come ci andiamo? La mia macchina in questo periodo è dal meccanico.","Ke bél-lo! Ma cóme chi andiámo? La mia mák-kina in cuésto período e dal mec-cánico."],["Marco","Nessun problema, guido io. Passo a prenderti alle nove e mezza.","Nes-sún probléma, güído io. Pás-so a prénderti ál-le nóve e méd-dsa."],["Elena","Perfetto. E per il pranzo? Mangiamo lì?","Perfét-to. E per il prántso? Mandyámo li?"],["Marco","Sì, ci sono tanti stand con piatti tipici: tajarin al tartufo, carne cruda, formaggi… Però il tartufo bianco costa molto, eh!","Si, chi sóno tánti stand con piát-ti típichi: tajarín al tartúfo, cárne crúda, formád-dyi… Peró il tartúfo biánco cósta mólto, e!"],["Elena","Allora porto un po' di soldi in più. Viene anche tua sorella?","Al-lóra pórto un po di sóldi in piu. Viéne ánke tua sorél-la?"],["Marco","No, sabato lavora. Ma forse viene Paolo, il mio collega.","No, sábato lavóra. Ma fórse viéne Páolo, il mio col-léga."],["Elena","Ah, bene. Senti, e se piove?","A, béne. Sénti, e se pióve?"],["Marco","La sagra è al coperto, sotto un grande tendone, quindi non c'è problema.","La ságra e al copérto, sót-to un gránde tendóne, cuíndi non che probléma."],["Elena","Ottimo. Allora a sabato!","Ót-timo. Al-lóra a sábato!"]],"items":[{"q":"1. Elena ha già dei programmi per sabato.","o":["Vero","Falso"],"a":1},{"q":"2. Elena in questo momento non può usare la sua macchina.","o":["Vero","Falso"],"a":0},{"q":"3. Marco passa a prendere Elena alle 9:30.","o":["Vero","Falso"],"a":0},{"q":"4. Alla sagra non si vendono piatti pronti.","o":["Vero","Falso"],"a":1},{"q":"5. La sorella di Marco va alla sagra con loro.","o":["Vero","Falso"],"a":1},{"q":"6. La sagra si svolge in uno spazio coperto.","o":["Vero","Falso"],"a":0}]},{"t":"Tarea 3","ins":"Va a escuchar a seis personas que hablan de sus últimas vacaciones. Escuchará la grabación dos veces. Relacione a cada persona con la frase que le corresponde (A–I). Hay tres frases que no necesitará.","audio":[["Giulia","Quest'estate sono andata in Toscana, in un agriturismo vicino a Siena. Ogni mattina la padrona di casa ci insegnava a fare la pasta fresca: pici, ravioli, tagliatelle. È stato bellissimo, e adesso a casa cucino molto di più.","Cuestestáte sóno andáta in Toscána, in un agriturísmo vichíno a Siéna. Óñ-ñi mat-tína la padróna di cása chi inseñ-ñáva a fáre la pásta frésca: píchi, ravióli, tall-llatél-le. E státo bel-lís-simo, e adés-so a cása cuchíno mólto di piu."],["Luca","Io ho preso l'Interrail con due amici: in tre settimane abbiamo visto Vienna, Praga e Berlino, sempre in treno. Abbiamo dormito poco, ma ci siamo divertiti un sacco.","Io o préso línter-rail con due amíchi: in tre set-timáne ab-biámo vísto Vién-na, Prága e Berlíno, sémpre in tréno. Ab-biámo dormíto póco, ma chi siámo divertíti un sác-co."],["Sara","Io amo la montagna. Ad agosto sono stata in Valle d'Aosta e ho camminato ogni giorno sei o sette ore. Dormivo nei rifugi. Sono tornata stanca ma felice.","Io ámo la montáñ-ña. Ad agósto sóno státa in Vál-le daósta e o cam-mináto óñ-ñi dyórno sei o sét-te óre. Dormívo nei rifúdyi. Sóno tornáta stánca ma felíche."],["Paolo","Mia sorella vive a Buenos Aires da dieci anni, così a luglio sono andato a trovarla con mia moglie. Siamo stati da lei un mese intero.","Mia sorél-la víve a Buénos Áires da diéchi án-ni, cosí a lúll-llo sóno andáto a trovárla con mia móll-lle. Siámo státi da lei un mése intéro."],["Anna","Doveva essere una vacanza perfetta in Grecia, ma il volo è stato cancellato e siamo partiti con un giorno di ritardo. E al ritorno hanno perso la mia valigia!","Dovéva és-sere úna vacántsa perfét-ta in Grécha, ma il vólo e státo canchel-láto e siámo partíti con un dyórno di ritárdo. E al ritórno án-no pérso la mia valídya!"],["Roberto","Io quest'anno niente vacanze: ho un ristorante a Rimini e d'estate c'è tantissimo lavoro. Andrò in vacanza a novembre, quando la città è tranquilla.","Io cuestán-no niénte vacántse: o un ristoránte a Rímini e destáte che tantís-simo lavóro. Andró in vacántsa a novémbre, cuándo la chit-tá e trancuíl-la."]],"items":[{"q":"Giulia","o":["A. Ha fatto una vacanza al mare con la famiglia.","B. Ha imparato a preparare piatti tipici.","C. Non ha fatto vacanze perché doveva lavorare.","D. Ha visitato diverse città in treno.","E. Ha camminato molto in montagna.","F. È andato/a a trovare una persona della famiglia che vive all'estero.","G. Ha dormito in tenda in un campeggio.","H. Ha seguito un corso di lingua.","I. Ha avuto problemi con il viaggio in aereo."],"a":1},{"q":"Luca","o":["A. Ha fatto una vacanza al mare con la famiglia.","B. Ha imparato a preparare piatti tipici.","C. Non ha fatto vacanze perché doveva lavorare.","D. Ha visitato diverse città in treno.","E. Ha camminato molto in montagna.","F. È andato/a a trovare una persona della famiglia che vive all'estero.","G. Ha dormito in tenda in un campeggio.","H. Ha seguito un corso di lingua.","I. Ha avuto problemi con il viaggio in aereo."],"a":3},{"q":"Sara","o":["A. Ha fatto una vacanza al mare con la famiglia.","B. Ha imparato a preparare piatti tipici.","C. Non ha fatto vacanze perché doveva lavorare.","D. Ha visitato diverse città in treno.","E. Ha camminato molto in montagna.","F. È andato/a a trovare una persona della famiglia che vive all'estero.","G. Ha dormito in tenda in un campeggio.","H. Ha seguito un corso di lingua.","I. Ha avuto problemi con il viaggio in aereo."],"a":4},{"q":"Paolo","o":["A. Ha fatto una vacanza al mare con la famiglia.","B. Ha imparato a preparare piatti tipici.","C. Non ha fatto vacanze perché doveva lavorare.","D. Ha visitato diverse città in treno.","E. Ha camminato molto in montagna.","F. È andato/a a trovare una persona della famiglia che vive all'estero.","G. Ha dormito in tenda in un campeggio.","H. Ha seguito un corso di lingua.","I. Ha avuto problemi con il viaggio in aereo."],"a":5},{"q":"Anna","o":["A. Ha fatto una vacanza al mare con la famiglia.","B. Ha imparato a preparare piatti tipici.","C. Non ha fatto vacanze perché doveva lavorare.","D. Ha visitato diverse città in treno.","E. Ha camminato molto in montagna.","F. È andato/a a trovare una persona della famiglia che vive all'estero.","G. Ha dormito in tenda in un campeggio.","H. Ha seguito un corso di lingua.","I. Ha avuto problemi con il viaggio in aereo."],"a":8},{"q":"Roberto","o":["A. Ha fatto una vacanza al mare con la famiglia.","B. Ha imparato a preparare piatti tipici.","C. Non ha fatto vacanze perché doveva lavorare.","D. Ha visitato diverse città in treno.","E. Ha camminato molto in montagna.","F. È andato/a a trovare una persona della famiglia che vive all'estero.","G. Ha dormito in tenda in un campeggio.","H. Ha seguito un corso di lingua.","I. Ha avuto problemi con il viaggio in aereo."],"a":2}]}]},{"k":"cte","t":"Comprensión de textos escritos","min":40,"tasks":[{"t":"Tarea 1","ins":"Lea los seis anuncios y elija la opción correcta (a, b o c) para cada uno.","text":"1. PISCINA COMUNALE\nDa lunedì 3 giugno la piscina è aperta anche la domenica mattina, dalle 9 alle 13. Il martedì e il giovedì la piscina chiude alle 22. Ricordiamo che la cuffia è obbligatoria.\n\n2. AFFITTASI\nCamera singola in appartamento con altre due studentesse, a cinque minuti dalla stazione. 350 euro al mese, spese incluse. Solo ragazze non fumatrici. Chiamare Chiara dopo le 18.\n\n3. PANIFICIO ROSSI\nChiuso per ferie dal 10 al 24 agosto. Durante la chiusura trovate il nostro pane al Bar Centrale, in piazza Garibaldi. Riapriamo il 25 agosto con il solito orario.\n\n4. CORSO DI CUCINA REGIONALE\nOgni giovedì, dalle 19 alle 21, prepariamo insieme un piatto tipico di una regione italiana. Il prezzo comprende gli ingredienti e la cena. Il corso dura dieci settimane. Massimo 12 persone. Iscrizioni in segreteria.\n\n5. AVVISO AI VIAGGIATORI\nPer lavori sulla linea, sabato e domenica i treni tra Bologna e Ferrara sono sostituiti da autobus, che partono dal piazzale davanti alla stazione.\n\n6. CERCASI CAMERIERE/A\nPizzeria in centro cerca cameriere/a con esperienza per il fine settimana. È necessario parlare inglese. Contratto fino a settembre. Presentarsi con il curriculum dalle 15 alle 17.","items":[{"q":"1. La domenica la piscina…","o":["è chiusa.","è aperta solo la mattina.","è aperta tutto il giorno."],"a":1},{"q":"2. La camera è adatta a…","o":["una studentessa che non fuma.","una coppia di studenti.","un ragazzo che lavora."],"a":0},{"q":"3. Ad agosto il pane del Panificio Rossi…","o":["non si può comprare.","costa meno.","si può comprare in un bar."],"a":2},{"q":"4. Nel prezzo del corso di cucina…","o":["sono compresi anche gli ingredienti.","non è compresa la cena.","è compreso un libro di ricette."],"a":0},{"q":"5. Nel fine settimana, per andare da Bologna a Ferrara…","o":["non ci sono collegamenti.","bisogna prendere l'autobus.","i treni partono in ritardo."],"a":1},{"q":"6. Per il lavoro in pizzeria bisogna…","o":["mandare il curriculum per email.","lavorare tutti i giorni.","conoscere l'inglese."],"a":2}]},{"t":"Tarea 2","ins":"Lea el correo electrónico que Francesca escribe a su amigo Javier. Indique si las afirmaciones son verdaderas (Vero) o falsas (Falso).","text":"Ciao Javier,\n\ncome stai? Scusa se non ti ho scritto prima, ma questo mese è stato pieno di novità. Come sai, a settembre mi sono trasferita a Bologna per lavoro. Adesso lavoro in una piccola casa editrice in centro e sono molto contenta: i colleghi sono simpatici e il lavoro è interessante.\n\nAll'inizio ho abitato per tre settimane da mia cugina, ma adesso ho finalmente un appartamento tutto mio. È piccolo, ma ha un balcone con vista sui tetti della città. Purtroppo l'affitto è un po' caro, come in tutto il centro.\n\nBologna mi piace moltissimo. Vado dappertutto a piedi e quando piove non è un problema, perché in centro quasi tutte le strade hanno i portici. E poi si mangia benissimo! Il sabato mattina vado spesso al Mercato delle Erbe a comprare frutta e verdura. La domenica, ogni tanto, faccio i tortellini con la mia vicina di casa, una signora di ottant'anni che mi insegna i segreti della cucina bolognese.\n\nAllora, quando vieni a trovarmi? Il divano del salotto diventa un letto, quindi puoi dormire da me. Ottobre è un buon mese: non fa troppo caldo e la città è piena di vita. Se vuoi, possiamo fare anche una gita a Modena, che è a mezz'ora di treno.\n\nTi mando qualche foto del mio balcone. Scrivimi presto!\nUn abbraccio,\nFrancesca","items":[{"q":"1. Francesca si è trasferita a Bologna per studiare.","o":["Vero","Falso"],"a":1},{"q":"2. Francesca è soddisfatta del suo nuovo lavoro.","o":["Vero","Falso"],"a":0},{"q":"3. Adesso Francesca vive con sua cugina.","o":["Vero","Falso"],"a":1},{"q":"4. L'appartamento di Francesca costa poco.","o":["Vero","Falso"],"a":1},{"q":"5. Secondo Francesca, a Bologna la pioggia non è un grande problema.","o":["Vero","Falso"],"a":0},{"q":"6. Una vicina insegna a Francesca a cucinare un piatto tipico.","o":["Vero","Falso"],"a":0},{"q":"7. Javier può dormire a casa di Francesca.","o":["Vero","Falso"],"a":0}]},{"t":"Tarea 3","ins":"Lea el texto y elija la opción correcta (a, b o c) para completar cada hueco (1–8).","text":"L'aperitivo\n\nL'aperitivo è un'abitudine molto amata dagli italiani. Di solito si fa (1) ______ cena, tra le sei e le otto di sera, al bar o a casa con gli amici. La parola viene dal latino «aperire», cioè «aprire»: l'aperitivo infatti (2) ______ ad «aprire» lo stomaco.\n\nUna delle bevande più famose è lo spritz, nato in Veneto (il nome viene dal tedesco «spritzen», cioè «spruzzare»): si prepara con prosecco, un liquore amaro e un po' di acqua frizzante. Il suo colore arancione è ormai conosciuto in tutto il mondo. Molti invece (3) ______ un vermut, un analcolico o un bicchiere di vino.\n\nCon le bevande, il bar offre quasi sempre qualcosa da mangiare: patatine, olive, piccoli panini. In molte città, soprattutto (4) ______ nord, è diffusa l'«apericena»: con il prezzo della bevanda si mangia a buffet pasta fredda, verdure, salumi e formaggi, e così molte persone non (5) ______ più cena. A Milano, per esempio, l'apericena è diventata quasi un'istituzione.\n\nPer gli italiani, però, l'aperitivo non è solo bere e mangiare: è un momento per (6) ______ con gli amici o con i colleghi dopo il lavoro. Se andate in Italia, provate (7) ______ fare l'aperitivo come un italiano: senza fretta e (8) ______ buona compagnia!","items":[{"q":"(1)","o":["dopo","prima di","senza"],"a":1},{"q":"(2)","o":["serve","usa","fa"],"a":0},{"q":"(3)","o":["vendono","cucinano","scelgono"],"a":2},{"q":"(4)","o":["dal","al","sul"],"a":1},{"q":"(5)","o":["fanno","sono","hanno"],"a":0},{"q":"(6)","o":["chiacchiera","chiacchierato","chiacchierare"],"a":2},{"q":"(7)","o":["di","a","da"],"a":1},{"q":"(8)","o":["a","per","in"],"a":2}]}]},{"k":"pcte","t":"Producción y coproducción escritas y mediación escrita","min":45,"tasks":[{"t":"Tarea 1 · Producción","ins":"Acaba de pasar un fin de semana en una ciudad italiana. Escriba una entrada para su blog personal (100–125 palabras) en la que cuente: adónde fue y con quién; qué visitó; qué comió y qué fue lo que más le gustó; su opinión general y si volvería.","words":[100,125],"source":"","model":["Il mio fine settimana a Torino\n\nLo scorso fine settimana sono andato a Torino con un mio amico. Siamo arrivati venerdì sera in aereo e abbiamo dormito in un piccolo albergo vicino a Piazza Castello.\n\nSabato mattina abbiamo visitato il Museo Egizio: è enorme e molto interessante. Nel pomeriggio siamo saliti sulla Mole Antonelliana, dove c'è il Museo del Cinema, e da lì abbiamo visto tutta la città e le Alpi.\n\nLa cosa che mi è piaciuta di più è stata la cucina: ho mangiato gli agnolotti del plin e ho bevuto un bicerin, una bevanda calda con caffè, cioccolato e crema di latte. Buonissimo!\n\nTorino è una città elegante e tranquilla. Ci tornerò sicuramente!","Il mio fíne set-timána a Toríno\n\nLo scórso fíne set-timána sóno andáto a Toríno con un mio amíco. Siámo ar-riváti venerdí séra in aéreo e ab-biámo dormíto in un píc-colo albérgo vichíno a Piát-tsa Castél-lo.\n\nSábato mat-tína ab-biámo visitáto il Muséo Edyít-tsio: e enórme e mólto interes-sánte. Nel pomeríd-dyo siámo salíti súl-la Móle Antonel-liána, dóve che il Muséo del Chínema, e da li ab-biámo vísto tút-ta la chit-tá e le Álpi.\n\nLa cósa ke mi e piachúta di piu e státa la cuchína: o mandyáto lli añ-ñolót-ti del plin e o bevúto un bicherín, úna bevánda cálda con caf-fé, choc-cólato e créma di lát-te. Buonís-simo!\n\nToríno e úna chit-tá elegánte e trancuíl-la. Chi torneró sicuraménte!"],"check":["Trato los cuatro puntos: lugar y compañía, visitas, comida y lo que más me gustó, opinión final.","El texto tiene entre 100 y 125 palabras.","Tiene título y párrafos, y uso conectores sencillos (e, ma, poi, perché, quindi).","Uso bien el passato prossimo: auxiliar correcto (essere/avere) y concordancia del participio con essere.","Uso vocabulario de viajes y comida sin palabras en español.","Registro informal adecuado a un blog; acentos gráficos correctos (è, città, più, perché)."]},{"t":"Tarea 2 · Coproducción","ins":"Ha recibido este mensaje de Matteo, un amigo italiano. Respóndale (80–100 palabras): alégrese de la noticia, recomiéndele dos lugares que visitar en su ciudad y un plato típico que probar, y proponga un día para verse y qué hacer juntos.","words":[80,100],"source":"Ciao!\nIl mese prossimo vengo in Andalusia per una settimana con la mia ragazza. Vorremmo passare due giorni nella tua città. Che cosa ci consigli di vedere? E dove possiamo mangiare bene? Ci piacerebbe tanto vederti: quando sei libero?\nUn abbraccio,\nMatteo","model":["Ciao Matteo!\n\nChe bella notizia! Sono molto contento di vedervi.\n\nNella mia città, Cadice, vi consiglio di vedere la cattedrale e la Torre Tavira: dall'alto si vede tutta la città con il mare intorno. Poi fate una passeggiata sulla spiaggia della Caleta al tramonto.\n\nPer mangiare, dovete provare le tortillitas de camarones, delle frittelle sottili con i gamberetti, e il pesce fritto.\n\nIo sono libero il sabato: se volete, vi porto a cena in una taverna che conosco. Fammi sapere!\n\nUn abbraccio,\nAlejandro","Cháo Mát-teo!\n\nKe bél-la notít-tsia! Sóno mólto conténto di vedérvi.\n\nNél-la mia chit-tá, Cádiche, vi consíll-llo di vedére la cat-tedrále e la Tór-re Tavíra: dal-lálto si véde tút-ta la chit-tá con il máre intórno. Poi fáte úna pas-sed-dyáta súl-la spiád-dya dél-la Caléta al tramónto.\n\nPer mandyáre, dovéte prováre le tortil-lítas de camarónes, dél-le frit-tél-le sot-tíli con i gamberét-ti, e il pésh-she frít-to.\n\nIo sóno líbero il sábato: se voléte, vi pórto a chéna in úna tavérna ke conósco. Fám-mi sapére!\n\nUn ab-brát-cho,\nAlejándro"],"check":["Respondo a todo lo que pregunta Matteo: qué ver, dónde o qué comer y cuándo puedo verlos.","El texto tiene entre 80 y 100 palabras.","Empiezo y termino como en un mensaje informal (Ciao…, Un abbraccio / A presto).","Uso bien el imperativo informal o «dovete / potete + infinitivo» para recomendar.","Uso el tú/vosotros con coherencia (ti, vi, tuo, vostro) sin pasar al Lei.","Ortografía y concordancias correctas (artículos, plurales, adjetivos)."]}]},{"k":"pcto","t":"Producción y coproducción orales y mediación oral","tasks":[{"t":"Tarea 1 · Mediación oral","ins":"Está con una amiga italiana, Giulia, que no habla español, delante del cartel de un mercado. Explíquele en italiano la información importante: días y horario, cuándo está cerrado, qué pasa los viernes por la tarde, cuándo no hay pescado y el servicio a domicilio. No hace falta traducir palabra por palabra.","prep":2,"speak":[1,2],"source":"MERCADO CENTRAL DE ABASTOS\nHorario: de lunes a sábado, de 8:00 a 14:30. Domingos y festivos, cerrado.\nLos viernes abrimos también por la tarde, de 18:00 a 21:00, con degustaciones en los puestos de la planta alta.\nPescado fresco todos los días, excepto los lunes.\nEntrega a domicilio gratuita en compras superiores a 40 €.","model":["Allora, Giulia, il cartello dice che il mercato è aperto dal lunedì al sabato, dalle otto alle due e mezza. La domenica e i giorni festivi è chiuso. Il venerdì è aperto anche la sera, dalle sei alle nove, e al piano di sopra puoi assaggiare i prodotti. Il pesce fresco c'è tutti i giorni, ma il lunedì no. E se spendi più di quaranta euro, ti portano la spesa a casa gratis.","Al-lóra, Dyúlia, il cartél-lo díche ke il mercáto e apérto dal lunedí al sábato, dál-le ót-to ál-le due e méd-dsa. La doménica e i dyórni festívi e kiúso. Il venerdí e apérto ánke la séra, dál-le sei ál-le nóve, e al piáno di sópra puoi as-sad-dyáre i prodót-ti. Il pésh-she frésco che tút-ti i dyórni, ma il lunedí no. E se spéndi piu di cuaránta éuro, ti pórtano la spésa a cása grátis."],"check":["Transmito los cinco datos: horario, cierre, viernes por la tarde, lunes sin pescado y entrega a domicilio.","Selecciono lo importante y no traduzco palabra por palabra.","Uso bien las horas y los días (dalle… alle…, il lunedì, la domenica).","Me dirijo a mi amiga de tú (puoi, spendi, ti portano).","Hablo con fluidez y pronuncio con claridad los números."]},{"t":"Tarea 2 · Monólogo","ins":"Hable de su trabajo o de sus estudios: qué hace y dónde, su horario, qué le gusta y qué no le gusta tanto, y sus planes para el futuro.","prep":2,"speak":[2,3],"source":"","model":["Sono professore in una scuola di formazione professionale in Andalusia. Insegno cucina a ragazzi tra i sedici e i vent'anni. Lavoro dal lunedì al venerdì, di solito dalle otto e un quarto alle tre. Le lezioni sono quasi tutte pratiche: siamo in una cucina professionale e prepariamo piatti di tutti i tipi, dalle salse ai dolci. Il mio lavoro mi piace molto perché i ragazzi imparano un mestiere, e alcuni poi lavorano in ristoranti importanti. La cosa più difficile è che le classi sono numerose e a casa ho molti compiti da correggere. In futuro mi piacerebbe fare un corso di cucina in Italia: per questo studio l'italiano.","Sóno profes-sóre in úna scúola di format-tsióne profes-sionále in Andalusía. Inséñ-ño cuchína a ragát-tsi tra i sédichi e i ventán-ni. Lavóro dal lunedí al venerdí, di sólito dál-le ót-to e un cuárto ál-le tre. Le let-tsióni sóno cuási tút-te prátike: siámo in úna cuchína profes-sionále e prepariámo piát-ti di tút-ti i típi, dál-le sálse ai dólchi. Il mio lavóro mi piáche mólto perké i ragát-tsi impárano un mestiére, e alcúni poi lávorano in ristoránti importánti. La cósa piu dif-fíchile e ke le clás-si sóno numeróse e a cása o mólti cómpiti da cor-réd-dyere. In futúro mi piacheréb-be fáre un córso di cuchína in Itália: per cuésto stúdio litaliáno."],"check":["Hablo de todos los puntos: qué hago, dónde, horario, lo que me gusta y lo que no, planes.","Hablo entre 2 y 3 minutos sin leer.","Ordeno las ideas con conectores (di solito, poi, perché, però, per questo).","Uso bien el presente y «mi piace / mi piacerebbe».","Tengo vocabulario suficiente del trabajo o los estudios.","Pronuncio de forma comprensible (dobles consonantes, c/g ante e/i)."]},{"t":"Tarea 3 · Diálogo","ins":"Usted y un compañero o compañera de clase organizan una cena para celebrar el final del curso. Pónganse de acuerdo sobre: el día y la hora, el lugar (restaurante o casa de alguien), la comida y el precio, y qué hace cada uno.","prep":1,"speak":[3,4],"source":"","model":["A: Allora, quando facciamo la cena di fine corso? Io propongo venerdì sera.\nB: Venerdì per me va bene, ma non prima delle nove, perché lavoro fino alle otto.\nA: D'accordo, alle nove e mezza. Andiamo al ristorante o facciamo la cena a casa di qualcuno?\nB: Al ristorante è più comodo, però siamo in ventidue e costa di più. Che ne dici della pizzeria vicino alla scuola?\nA: Buona idea! La pizza piace a tutti e con quindici euro mangiamo e beviamo.\nB: Perfetto. Chi chiama per prenotare?\nA: Chiamo io domani mattina. Tu puoi scrivere ai compagni nel gruppo della classe?\nB: Sì, certo. E poi raccolgo i soldi per il regalo all'insegnante.\nA: Ottimo. Allora venerdì alle nove e mezza in pizzeria!","A: Al-lóra, cuándo fat-chámo la chéna di fíne córso? Io propóngo venerdí séra.\nB: Venerdí per me va béne, ma non príma dél-le nóve, perké lavóro fíno ál-le ót-to.\nA: Dac-córdo, ál-le nóve e méd-dsa. Andiámo al ristoránte o fat-chámo la chéna a cása di cualcúno?\nB: Al ristoránte e piu cómodo, peró siámo in ventídue e cósta di piu. Ke ne díchi dél-la pit-tsería vichíno ál-la scúola?\nA: Buóna idéa! La pít-tsa piáche a tút-ti e con cuíndichi éuro mandyámo e beviámo.\nB: Perfét-to. Ki kiáma per prenotáre?\nA: Kiámo io dománi mat-tína. Tu puoi scrívere ai compáñ-ñi nel grúp-po dél-la clás-se?\nB: Si, chérto. E poi rac-cólgo i sóldi per il regálo al-linseñ-ñánte.\nA: Ót-timo. Al-lóra venerdí ál-le nóve e méd-dsa in pit-tsería!"],"check":["Llegamos a un acuerdo sobre día, hora, lugar, precio y reparto de tareas.","Propongo, acepto y rechazo con educación (Che ne dici…?, Per me va bene, Buona idea, però…).","Respondo a lo que dice mi compañero y no solo leo mi parte.","Hago preguntas para mantener la conversación.","Uso bien el presente con valor de futuro y los números (precios, horas).","Pronunciación y entonación comprensibles, especialmente en las preguntas."]}]}]},{"id":"B1","t":"Simulacro de examen B1","intro":"Simulacro completo de la prueba de certificación de nivel Intermedio B1 de italiano de las Escuelas Oficiales de Idiomas de Andalucía, con la estructura que describe la Guía del candidato (EOI de Chiclana, 2022-23). Tiene cuatro partes: comprensión de textos orales (45 min), comprensión de textos escritos (60 min), producción y coproducción escritas (60 min) y producción, coproducción y mediación orales. Cada audio se escucha dos veces. Según esa guía, para aprobar hay que hacer todas las partes, sacar al menos un 5 en cada una y una media de 6,5 o más. Confirma en tu escuela los criterios del curso actual. Las tareas de expresión se autoevalúan con la respuesta modelo y la lista de criterios.","parts":[{"k":"cto","t":"Comprensión de textos orales","min":45,"tasks":[{"t":"Tarea 1","ins":"Va a escuchar una entrevista radiofónica a Chiara Ferri, que lleva una trattoria en Turín. Escuchará la grabación dos veces. Elija la opción correcta (a, b o c).","audio":[["A","Buongiorno e benvenuti a «Gusto e dintorni». Oggi in studio abbiamo Chiara Ferri, che da cinque anni gestisce una trattoria nel centro di Torino. Benvenuta, Chiara.","Buondyórno e benvenúti a «Gústo e dintórni». Ód-dyi in stúdio ab-biámo Kiára Fér-ri, ke da chíncue án-ni dyestísh-she úna trat-toría nel chéntro di Toríno. Benvenúta, Kiára."],["B","Grazie a voi per l'invito.","Grát-tsie a voi per linvíto."],["A","Il suo locale è conosciuto in città perché non butta quasi niente. Come ci riuscite?","Il suo locále e conosh-shúto in chit-tá perké non bút-ta cuási niénte. Cóme chi riush-shíte?"],["B","Guardi, il segreto è organizzarsi. Il menù cambia ogni giorno e lo decido la mattina, dopo aver controllato che cosa c'è in frigorifero. Così usiamo prima i prodotti che scadono prima.","Guárdi, il segréto e organid-dsársi. Il menú cámbia óñ-ñi dyórno e lo dechído la mat-tína, dópo avér control-láto ke cósa che in frigorífero. Cosí usiámo príma i prodót-ti ke scádono príma."],["A","E con gli avanzi che cosa fate?","E con lli avántsi ke cósa fáte?"],["B","Con il pane del giorno prima facciamo le polpette o il dolce di pane, e con le verdure che restano prepariamo brodi e minestre. Quello che proprio non riusciamo a usare lo diamo, la sera, a un'associazione del quartiere che lo distribuisce alle famiglie in difficoltà.","Con il páne del dyórno príma fat-chámo le polpét-te o il dólche di páne, e con le verdúre ke réstano prepariámo bródi e minéstre. Cuél-lo ke próprio non riush-shámo a usáre lo diámo, la séra, a unas-sochat-tsióne del cuartiére ke lo distribuísh-she ál-le famíll-lle in dif-ficoltá."],["A","È complicato dal punto di vista burocratico?","E complicáto dal púnto di vísta burocrático?"],["B","Molto meno di una volta. Dal duemilasedici in Italia c'è una legge che rende più semplice donare il cibo invenduto. Prima avevamo paura di avere problemi; adesso è tutto più chiaro.","Mólto méno di úna vólta. Dal duemilasédichi in Itália che úna léd-dye ke rénde piu sémpliche donáre il chíbo invendúto. Príma avevámo paúra di avére problémi; adés-so e tút-to piu kiáro."],["A","E i clienti? Apprezzano?","E i cliénti? Ap-prét-tsano?"],["B","Sì, moltissimo. Molti chiedono la «doggy bag», cioè di portare a casa quello che non hanno finito. Qualche anno fa in Italia ci si vergognava un po'; oggi è normale. Noi diamo dei contenitori di cartone riciclabile.","Si, moltís-simo. Mólti kiédono la «dog-gy bag», choé di portáre a cása cuél-lo ke non án-no finíto. Cuálke án-no fa in Itália chi si vergoñ-ñáva un po; ód-dyi e normále. Noi diámo dei contenitóri di cartóne richiclábile."],["A","Un consiglio per chi ci ascolta da casa?","Un consíll-llo per ki chi ascólta da cása?"],["B","Fare la spesa più spesso e comprare di meno. E leggere bene le etichette: «da consumarsi preferibilmente entro» non vuol dire che, dopo quella data, il prodotto va buttato.","Fáre la spésa piu spés-so e compráre di méno. E léd-dyere béne le etikét-te: «da consumársi preferibilménte éntro» non vuol díre ke, dópo cuél-la dáta, il prodót-to va but-táto."],["A","Grazie mille, Chiara, e buon lavoro!","Grát-tsie míl-le, Kiára, e buon lavóro!"]],"items":[{"q":"1. Da quanto tempo Chiara gestisce la trattoria?","o":["Da due anni.","Da cinque anni.","Da quindici anni."],"a":1},{"q":"2. Il menù della trattoria…","o":["è sempre lo stesso.","cambia ogni settimana.","dipende dai prodotti che ci sono in cucina."],"a":2},{"q":"3. Con il pane avanzato preparano…","o":["polpette e un dolce.","minestre e brodi.","panini per la sera."],"a":0},{"q":"4. Il cibo che non riescono a usare…","o":["lo vendono a prezzo ridotto.","lo regalano a un'associazione.","lo danno ai dipendenti."],"a":1},{"q":"5. Secondo Chiara, oggi donare il cibo…","o":["è più facile che in passato.","è vietato dalla legge.","richiede molti documenti."],"a":0},{"q":"6. Per quanto riguarda la «doggy bag», oggi i clienti italiani…","o":["devono pagare il contenitore.","la chiedono raramente.","la chiedono senza imbarazzo."],"a":2},{"q":"7. Chiara consiglia di…","o":["fare una grande spesa alla settimana.","comprare meno, ma più spesso.","buttare i prodotti dopo la data indicata."],"a":1}]},{"t":"Tarea 2","ins":"Va a escuchar una conversación entre dos amigos, Marta y Davide; él acaba de volver de un viaje. Escuchará la grabación dos veces. Indique si las afirmaciones son verdaderas (Vero) o falsas (Falso).","audio":[["Marta","Allora, Davide, com'è andata in Sicilia?","Al-lóra, Davíde, comé andáta in Sichília?"],["Davide","Benissimo! Anche se il primo giorno è stato un disastro: il volo per Catania è partito con tre ore di ritardo e siamo arrivati all'agriturismo verso l'una di notte.","Benís-simo! Ánke se il prímo dyórno e státo un disástro: il vólo per Cátania e partíto con tre óre di ritárdo e siámo ar-riváti al-lagriturísmo vérso lúna di nót-te."],["Marta","Che sfortuna! E avevate noleggiato la macchina?","Ke sfortúna! E aveváte noled-dyáto la mák-kina?"],["Davide","Sì, e per fortuna l'autonoleggio in aeroporto era ancora aperto. Senza macchina, in Sicilia, ti muovi male: i treni ci sono, ma sono pochi e lenti, soprattutto nell'interno.","Si, e per fortúna lautonoléd-dyo in aeropórto éra ancóra apérto. Séntsa mák-kina, in Sichília, ti muóvi mále: i tréni chi sóno, ma sóno póki e lénti, soprat-tút-to nel-lintérno."],["Marta","E dove siete stati?","E dóve siéte státi?"],["Davide","I primi giorni nella zona dell'Etna. Siamo saliti verso i crateri con una guida, perché nella parte più alta non si può andare da soli. Poi siamo scesi a Siracusa e a Noto, e alla fine abbiamo passato due giorni a Palermo.","I prími dyórni nél-la dsóna del-létna. Siámo salíti vérso i cratéri con úna güída, perké nél-la párte piu álta non si puo andáre da sóli. Poi siámo shési a Siracúsa e a Nóto, e ál-la fíne ab-biámo pas-sáto due dyórni a Palérmo."],["Marta","E il cibo? Immagino che tu abbia mangiato di tutto.","E il chíbo? Im-mádyino ke tu áb-bia mandyáto di tút-to."],["Davide","Ah, guarda, ho preso tre kili! A Palermo abbiamo fatto un giro al mercato di Ballarò: panelle, arancine, sfincione… E a Noto, a colazione, ho preso la granita di mandorla, come fanno lì.","A, guárda, o préso tre kíli! A Palérmo ab-biámo fát-to un dyíro al mercáto di Bal-laró: panél-le, aranchíne, sfinchóne… E a Nóto, a colat-tsióne, o préso la graníta di mándorla, cóme fán-no li."],["Marta","Arancine o arancini? Ho sentito che i siciliani litigano su questo.","Aranchíne o aranchíni? O sentíto ke i sichiliáni lítigano su cuésto."],["Davide","Esatto: a Palermo si dice «arancina», al femminile, e a Catania «arancino». Io, per non sbagliare, le ho chiamate in tutti e due i modi!","Esát-to: a Palérmo si díche «aranchína», al fem-miníle, e a Cátania «aranchíno». Io, per non sball-lláre, le o kiamáte in tút-ti e due i módi!"],["Marta","E il caldo? Ad agosto…","E il cáldo? Ad agósto…"],["Davide","Non siamo andati ad agosto, ma a fine settembre. Il mare era ancora caldo e c'era molta meno gente che d'estate. Te lo consiglio.","Non siámo andáti ad agósto, ma a fíne set-témbre. Il máre éra ancóra cáldo e chéra mólta méno dyénte ke destáte. Te lo consíll-llo."],["Marta","Mi hai convinto. L'anno prossimo ci vado anch'io.","Mi ai convínto. Lán-no prós-simo chi vádo ankío."]],"items":[{"q":"1. Il volo di Davide è arrivato in orario.","o":["Vero","Falso"],"a":1},{"q":"2. Davide e i suoi compagni di viaggio hanno noleggiato un'auto all'aeroporto.","o":["Vero","Falso"],"a":0},{"q":"3. Secondo Davide, in Sicilia è comodo spostarsi in treno.","o":["Vero","Falso"],"a":1},{"q":"4. Sull'Etna sono saliti accompagnati da una guida.","o":["Vero","Falso"],"a":0},{"q":"5. L'ultima tappa del viaggio è stata Siracusa.","o":["Vero","Falso"],"a":1},{"q":"6. A Noto Davide ha mangiato la granita a colazione.","o":["Vero","Falso"],"a":0},{"q":"7. A Catania si dice «arancina».","o":["Vero","Falso"],"a":1},{"q":"8. Davide ha viaggiato in un periodo con meno turisti che in estate.","o":["Vero","Falso"],"a":0}]},{"t":"Tarea 3","ins":"Va a escuchar a seis personas que cuentan cómo van al trabajo. Escuchará la grabación dos veces. Relacione a cada persona con la frase que le corresponde (A–H). Hay dos frases que no necesitará.","audio":[["Elisa","Io abito in un paese a trenta chilometri da Verona e lì i mezzi pubblici sono pochissimi. Così, con tre colleghi, abbiamo deciso di andare in ufficio con una sola macchina: ogni settimana guida uno diverso e dividiamo le spese della benzina.","Io ábito in un paése a trénta kilómetri da Veróna e li i méd-dsi púb-blichi sóno pokís-simi. Cosí, con tre col-légui, ab-biámo dechíso di andáre in uf-fícho con úna sóla mák-kina: óñ-ñi set-timána güída úno divérso e dividiámo le spése dél-la bendsína."],["Marco","Fino all'anno scorso prendevo sempre la macchina, anche per fare cinquecento metri. Poi il medico mi ha detto che dovevo muovermi di più, e adesso vado a piedi: quaranta minuti all'andata e quaranta al ritorno. Mi sento molto meglio.","Fíno al-lán-no scórso prendévo sémpre la mák-kina, ánke per fáre chincuechénto métri. Poi il médico mi a dét-to ke dovévo muóvermi di piu, e adés-so vádo a piédi: cuaránta minúti al-landáta e cuaránta al ritórno. Mi sénto mólto méll-llo."],["Francesca","Io prendo la metropolitana e poi un autobus. Ci metto quasi un'ora, ma non mi dispiace: è l'unico momento della giornata in cui riesco a leggere un libro con calma. In macchina, invece, perderei solo tempo nel traffico.","Io préndo la metropolitána e poi un áutobus. Chi mét-to cuási unóra, ma non mi dispiáche: e lúnico moménto dél-la dyornáta in cui riésco a léd-dyere un líbro con cálma. In mák-kina, invéche, perderéi sólo témpo nel tráf-fico."],["Giorgio","Dopo la pandemia la mia azienda ha introdotto lo smart working: il lunedì e il venerdì lavoro da casa, gli altri giorni vado in ufficio in treno. Risparmio tempo e soldi, ma a volte mi mancano i colleghi.","Dópo la pandemía la mia at-tsiénda a introdót-to lo smart wórking: il lunedí e il venerdí lavóro da cása, lli áltri dyórni vádo in uf-fícho in tréno. Rispármio témpo e sóldi, ma a vólte mi máncano i col-légui."],["Silvia","Prima vivevo in periferia e passavo due ore al giorno in macchina. Ero sempre stanca e nervosa. L'anno scorso ho trovato un piccolo appartamento a dieci minuti dall'ospedale dove lavoro. Pago un affitto più alto, ma ne vale la pena.","Príma vivévo in perifería e pas-sávo due óre al dyórno in mák-kina. Éro sémpre stánca e nervósa. Lán-no scórso o trováto un píc-colo ap-partaménto a diéchi minúti dal-lospedále dóve lavóro. Págo un af-fít-to piu álto, ma ne vále la péna."],["Andrea","Io vado in ufficio in bici tutto l'anno. Mio fratello mi ha consigliato di comprare un monopattino elettrico, ma preferisco pedalare. Quando piove metto la giacca impermeabile e via! Bisogna solo portare una camicia di ricambio.","Io vádo in uf-fícho in bíchi tút-to lán-no. Mio fratél-lo mi a consill-lláto di compráre un monopát-tino elét-trico, ma preferísco pedaláre. Cuándo pióve mét-to la dyác-ca impermeábile e via! Bisóñ-ña sólo portáre úna camícha di ricámbio."]],"items":[{"q":"Elisa","o":["A. Ha cambiato modo di spostarsi per motivi di salute.","B. Lavora da casa alcuni giorni alla settimana.","C. Divide l'auto e le spese con dei colleghi.","D. Va in bicicletta anche quando piove.","E. Ha cambiato casa per stare più vicino al lavoro.","F. Preferisce i mezzi pubblici perché così può leggere.","G. Va al lavoro in monopattino elettrico.","H. Ha venduto la macchina per risparmiare."],"a":2},{"q":"Marco","o":["A. Ha cambiato modo di spostarsi per motivi di salute.","B. Lavora da casa alcuni giorni alla settimana.","C. Divide l'auto e le spese con dei colleghi.","D. Va in bicicletta anche quando piove.","E. Ha cambiato casa per stare più vicino al lavoro.","F. Preferisce i mezzi pubblici perché così può leggere.","G. Va al lavoro in monopattino elettrico.","H. Ha venduto la macchina per risparmiare."],"a":0},{"q":"Francesca","o":["A. Ha cambiato modo di spostarsi per motivi di salute.","B. Lavora da casa alcuni giorni alla settimana.","C. Divide l'auto e le spese con dei colleghi.","D. Va in bicicletta anche quando piove.","E. Ha cambiato casa per stare più vicino al lavoro.","F. Preferisce i mezzi pubblici perché così può leggere.","G. Va al lavoro in monopattino elettrico.","H. Ha venduto la macchina per risparmiare."],"a":5},{"q":"Giorgio","o":["A. Ha cambiato modo di spostarsi per motivi di salute.","B. Lavora da casa alcuni giorni alla settimana.","C. Divide l'auto e le spese con dei colleghi.","D. Va in bicicletta anche quando piove.","E. Ha cambiato casa per stare più vicino al lavoro.","F. Preferisce i mezzi pubblici perché così può leggere.","G. Va al lavoro in monopattino elettrico.","H. Ha venduto la macchina per risparmiare."],"a":1},{"q":"Silvia","o":["A. Ha cambiato modo di spostarsi per motivi di salute.","B. Lavora da casa alcuni giorni alla settimana.","C. Divide l'auto e le spese con dei colleghi.","D. Va in bicicletta anche quando piove.","E. Ha cambiato casa per stare più vicino al lavoro.","F. Preferisce i mezzi pubblici perché così può leggere.","G. Va al lavoro in monopattino elettrico.","H. Ha venduto la macchina per risparmiare."],"a":4},{"q":"Andrea","o":["A. Ha cambiato modo di spostarsi per motivi di salute.","B. Lavora da casa alcuni giorni alla settimana.","C. Divide l'auto e le spese con dei colleghi.","D. Va in bicicletta anche quando piove.","E. Ha cambiato casa per stare più vicino al lavoro.","F. Preferisce i mezzi pubblici perché così può leggere.","G. Va al lavoro in monopattino elettrico.","H. Ha venduto la macchina per risparmiare."],"a":3}]}]},{"k":"cte","t":"Comprensión de textos escritos","min":60,"tasks":[{"t":"Tarea 1","ins":"Lea el artículo y elija la opción correcta (a, b o c) para cada pregunta.","text":"Pioppi, il piccolo paese che ha insegnato al mondo a mangiare\n\nPioppi è un paesino di pescatori sulla costa del Cilento, in provincia di Salerno. In inverno ci abitano poche centinaia di persone e d'estate si riempie di turisti attratti dal mare pulito. Eppure il suo nome è conosciuto da medici e nutrizionisti di tutto il mondo. Il motivo è legato a un americano: Ancel Keys.\n\nKeys era un fisiologo dell'Università del Minnesota, noto per aver inventato durante la guerra la «razione K», il pasto di emergenza dei soldati americani. All'inizio degli anni Cinquanta, durante un soggiorno a Napoli, notò che le malattie del cuore erano molto meno frequenti nel Sud Italia che negli Stati Uniti, nonostante la povertà del dopoguerra. Si chiese se la ragione potesse essere l'alimentazione e decise di studiarla in modo scientifico. Nacque così il famoso «Studio dei sette paesi», che per decenni confrontò le abitudini alimentari e la salute di migliaia di uomini in Italia, Grecia, Jugoslavia, Paesi Bassi, Finlandia, Giappone e Stati Uniti.\n\nI risultati sembrarono confermare la sua intuizione: dove si mangiavano soprattutto pane, legumi, verdura, frutta e olio d'oliva, e poca carne, gli infarti erano più rari. Keys chiamò questo modello «dieta mediterranea» e lo fece conoscere al grande pubblico con alcuni libri scritti insieme alla moglie Margaret.\n\nInnamorato del Cilento, Keys si fece costruire una casa a Pioppi e vi trascorse buona parte dell'anno per quasi trent'anni. Gli abitanti più anziani lo ricordano ancora mentre passeggiava sul lungomare o comprava il pesce direttamente dai pescatori. Visse fino a cento anni: un buon argomento, dicono in paese, a favore delle sue teorie.\n\nNel 2010 l'UNESCO ha inserito la dieta mediterranea nel Patrimonio culturale immateriale dell'umanità, su proposta di Italia, Spagna, Grecia e Marocco; nel 2013 si sono aggiunti Cipro, Croazia e Portogallo. È importante capire che cosa significa: non si tratta solo di una lista di alimenti, ma di un insieme di conoscenze, tradizioni e pratiche che vanno dalla coltivazione della terra alla pesca, dalla conservazione dei cibi al modo di cucinarli e, soprattutto, di condividerli a tavola.\n\nOggi, paradossalmente, proprio nei paesi del Mediterraneo molte persone si allontanano da questo modello. I bambini italiani, per esempio, sono tra quelli con il tasso di sovrappeso più alto d'Europa. I cibi industriali, la mancanza di tempo per cucinare e la vita sedentaria hanno cambiato abitudini che duravano da secoli. Gli esperti ricordano inoltre un aspetto che spesso si dimentica: negli anni Cinquanta i contadini e i pescatori del Cilento non mangiavano soltanto in modo diverso, ma si muovevano molto di più. Camminavano per chilometri, lavoravano nei campi o in mare per molte ore al giorno e passavano poco tempo seduti.\n\nPer questo a Pioppi è nato un museo dedicato alla dieta mediterranea, che vuole far conoscere questa storia ai visitatori e soprattutto ai più giovani. L'obiettivo non è guardare con nostalgia al passato, ma ricordare che mangiare bene può essere semplice, economico e piacevole.","items":[{"q":"1. Pioppi è conosciuto dai medici di tutto il mondo perché…","o":["ha un ospedale molto importante.","è legato agli studi di Ancel Keys.","i suoi abitanti vivono tutti più di cento anni."],"a":1},{"q":"2. Keys cominciò a interessarsi all'alimentazione del Sud Italia quando…","o":["notò che lì le malattie cardiache erano meno frequenti.","lavorava come medico a Pioppi.","studiava la povertà del dopoguerra."],"a":0},{"q":"3. Lo «Studio dei sette paesi»…","o":["fu realizzato soltanto in Europa.","durò pochi mesi.","confrontò alimentazione e salute in paesi diversi."],"a":2},{"q":"4. Secondo lo studio, gli infarti erano più rari dove…","o":["si mangiavano molta carne e molto pesce.","si consumavano molti vegetali e olio d'oliva.","si mangiava poco pane."],"a":1},{"q":"5. A Pioppi, Keys…","o":["aprì un ristorante sul lungomare.","comprò una barca da pesca.","passò lunghi periodi per circa tre decenni."],"a":2},{"q":"6. Per l'UNESCO la dieta mediterranea è…","o":["un insieme di saperi e tradizioni legati al cibo.","un elenco di alimenti sani.","una dieta per perdere peso."],"a":0},{"q":"7. Secondo l'articolo, oggi in Italia…","o":["tutti seguono la dieta mediterranea.","molti bambini sono in sovrappeso.","si passa più tempo a cucinare che in passato."],"a":1}]},{"t":"Tarea 2","ins":"Lea los anuncios de ocho agriturismi (A–H) y lo que buscan siete personas (1–7). Relacione a cada persona con el alojamiento más adecuado. Hay un anuncio que no necesitará.","text":"A. IL POGGIO (Toscana)\nCasale del Cinquecento tra le colline della Val d'Orcia. Sei camere doppie e piscina panoramica. Colazione con prodotti del nostro orto; la cena si serve solo il venerdì e il sabato. Non si accettano animali. A pochi chilometri da Pienza e da Montalcino. Ideale per chi cerca silenzio: nelle camere non ci sono televisori.\n\nB. MASSERIA LE ULIVE (Puglia)\nAntica masseria fortificata nella campagna di Ostuni, la «città bianca», a quattro chilometri dal mare. Ogni mattina corso di cucina pugliese: orecchiette, focacce e conserve. Biciclette gratuite per gli ospiti. Animali ammessi.\n\nC. CASCINA BELVEDERE (Piemonte)\nAzienda vinicola a conduzione familiare nelle Langhe, i cui vigneti sono patrimonio UNESCO dal 2014. Ogni pomeriggio visita della cantina e degustazione dei nostri vini. Il ristorante è aperto tutte le sere con piatti tipici piemontesi. In autunno organizziamo uscite con i cercatori di tartufi e i loro cani.\n\nD. LA FATTORIA DEL SOLE (Umbria)\nSiamo un'azienda agricola con mucche, capre, galline e asini. I bambini possono aiutare a dare da mangiare agli animali e partecipare al laboratorio del formaggio. Area giochi e piscina per i più piccoli. Appartamenti per famiglie da quattro a sei persone, a venti minuti da Assisi.\n\nE. MALGA ALTA (Trentino)\nA 1.800 metri, raggiungibile solo a piedi (45 minuti dal parcheggio) o in seggiovia. Cucina di montagna con i formaggi che produciamo noi. Aperto da giugno a settembre. Dalla malga partono numerosi sentieri verso le cime vicine. Camere semplici con bagno in comune.\n\nF. TENUTA SAN MARCO (Sicilia)\nCamere accessibili alle persone con disabilità, ascensore e parcheggio privato. A quindici minuti dall'aeroporto di Catania, con navetta gratuita su prenotazione. Ristorante con menù senza glutine e vegano. La reception organizza escursioni guidate sull'Etna.\n\nG. LE QUERCE (Marche)\nPiccolo agriturismo biologico con quattro camere. Cucina vegetariana con le verdure dell'orto. Lezioni di yoga all'alba e passeggiate nei boschi. Si accettano cani di piccola taglia. Il paese più vicino è a otto chilometri.\n\nH. IL GRANAIO (Emilia-Romagna)\nA dieci minuti dall'uscita dell'autostrada di Modena. Visite guidate in un caseificio di Parmigiano Reggiano e in un'acetaia di aceto balsamico tradizionale. Su richiesta organizziamo anche la visita al Museo Enzo Ferrari. Camere con aria condizionata e wifi.","items":[{"q":"1. Paolo e Ines viaggiano con i loro figli di 5 e 8 anni, che adorano gli animali.","o":["A. Il Poggio","B. Masseria Le Ulive","C. Cascina Belvedere","D. La Fattoria del Sole","E. Malga Alta","F. Tenuta San Marco","G. Le Querce","H. Il Granaio"],"a":3},{"q":"2. Rosa è appassionata di vino e vuole assaggiarlo nel luogo dove si produce.","o":["A. Il Poggio","B. Masseria Le Ulive","C. Cascina Belvedere","D. La Fattoria del Sole","E. Malga Alta","F. Tenuta San Marco","G. Le Querce","H. Il Granaio"],"a":2},{"q":"3. Tomás è celiaco, si muove in sedia a rotelle e vuole vedere un vulcano.","o":["A. Il Poggio","B. Masseria Le Ulive","C. Cascina Belvedere","D. La Fattoria del Sole","E. Malga Alta","F. Tenuta San Marco","G. Le Querce","H. Il Granaio"],"a":5},{"q":"4. Lucía e Pedro vogliono imparare a fare la pasta fresca e andare al mare in bicicletta.","o":["A. Il Poggio","B. Masseria Le Ulive","C. Cascina Belvedere","D. La Fattoria del Sole","E. Malga Alta","F. Tenuta San Marco","G. Le Querce","H. Il Granaio"],"a":1},{"q":"5. Gianni vuole fare escursioni in alta montagna a luglio e non ha bisogno di comodità.","o":["A. Il Poggio","B. Masseria Le Ulive","C. Cascina Belvedere","D. La Fattoria del Sole","E. Malga Alta","F. Tenuta San Marco","G. Le Querce","H. Il Granaio"],"a":4},{"q":"6. Elena arriva in macchina e vuole vedere come si producono due prodotti tipici molto famosi.","o":["A. Il Poggio","B. Masseria Le Ulive","C. Cascina Belvedere","D. La Fattoria del Sole","E. Malga Alta","F. Tenuta San Marco","G. Le Querce","H. Il Granaio"],"a":7},{"q":"7. Carla cerca tranquillità assoluta, senza televisione, e vuole nuotare in piscina.","o":["A. Il Poggio","B. Masseria Le Ulive","C. Cascina Belvedere","D. La Fattoria del Sole","E. Malga Alta","F. Tenuta San Marco","G. Le Querce","H. Il Granaio"],"a":0}]},{"t":"Tarea 3","ins":"Lea el texto y elija la opción correcta (a, b o c) para completar cada hueco (1–8).","text":"Il caffè sospeso\n\nA Napoli il caffè non è solo una bevanda: è un rito che (1) ______ la giornata di moltissime persone. Tra le tradizioni legate al caffè, ce n'è una che negli ultimi anni è diventata famosa (2) ______ fuori dall'Italia: il «caffè sospeso». Il caffè è così importante per i napoletani che Pino Daniele gli ha dedicato una canzone, «'A tazzulella 'e cafè».\n\nFunziona così: un cliente entra in un bar, dove un espresso costa di solito poco più di un euro, beve il suo caffè e ne paga due. Il secondo resta «sospeso», cioè pagato ma non ancora consumato. Più tardi, una persona che non (3) ______ permettersi di spendere nemmeno un euro può entrare e chiedere se c'è un sospeso. Il barista glielo offre senza fare domande. Di solito chi lascia un sospeso non lo dice a nessuno: non lo fa per farsi vedere, ma per aiutare.\n\nNessuno sa con certezza quando sia nata questa abitudine. Secondo molti risale alla Seconda guerra mondiale o agli anni che la (4) ______, quando la povertà a Napoli era molto diffusa. Lo scrittore napoletano Luciano De Crescenzo ne ha parlato nei suoi libri e (5) ______ ha contribuito a farla conoscere.\n\nPer qualche tempo il caffè sospeso sembrava quasi scomparso, ma con la crisi economica degli ultimi decenni molti bar (6) ______ riportato in vita. Oggi esiste perfino una giornata dedicata al caffè sospeso, il 10 dicembre, e l'idea si è diffusa in altri paesi, dove a volte non si lascia solo un caffè, ma anche un panino o un libro.\n\nNaturalmente il sistema funziona solo se c'è fiducia: il cliente (7) ______ paga deve credere che il barista regalerà davvero il caffè a chi ne ha bisogno. Forse è proprio questo il suo valore più grande: un piccolo gesto anonimo, (8) ______ chi dà e chi riceve non si incontrano mai.","items":[{"q":"(1)","o":["accompagnato","accompagna","accompagnano"],"a":1},{"q":"(2)","o":["anche","neanche","ancora"],"a":0},{"q":"(3)","o":["sa","deve","può"],"a":2},{"q":"(4)","o":["seguì","seguirono","seguono"],"a":1},{"q":"(5)","o":["così","benché","perché"],"a":0},{"q":"(6)","o":["l'ha","lo sono","l'hanno"],"a":2},{"q":"(7)","o":["cui","che","chi"],"a":1},{"q":"(8)","o":["che","dove che","in cui"],"a":2}]}]},{"k":"pcte","t":"Producción y coproducción escritas y mediación escrita","min":60,"tasks":[{"t":"Tarea 1 · Producción","ins":"Una revista italiana de gastronomía en internet invita a sus lectores a escribir sobre «Un piatto che racconta la mia terra». Escriba un artículo (125–150 palabras) en el que explique: qué plato es y de dónde procede; cómo se prepara (ingredientes principales); qué recuerdos o momentos asocia a él; y por qué recomendaría probarlo.","words":[125,150],"source":"","model":["Il salmorejo: l'estate andalusa in una ciotola\n\nSe c'è un piatto che per me rappresenta l'Andalusia, è il salmorejo. È una crema fredda di pomodoro, tipica di Cordova, molto densa e vellutata.\n\nGli ingredienti sono pochi e semplici: pomodori molto maturi, pane raffermo, aglio, sale e tanto olio extravergine d'oliva. Si frulla tutto finché la crema diventa liscia e si serve ben fredda, con pezzetti di prosciutto crudo e di uovo sodo.\n\nPer me il salmorejo è legato ai pranzi d'estate a casa di mia nonna: quando faceva troppo caldo per mangiare, lei metteva in tavola una grande ciotola e tutti eravamo felici. Ancora oggi, quando lo preparo, sento il profumo di quella cucina.\n\nVe lo consiglio perché è sano, economico e perfetto nelle giornate calde. Ma attenzione: il segreto è usare un olio di qualità!","Il salmoréjo: lestáte andalúsa in úna chótola\n\nSe che un piát-to ke per me rap-presénta landalusía, e il salmoréjo. E úna créma fréd-da di pomodóro, típica di Córdova, mólto dénsa e vel-lutáta.\n\nLli ingrediénti sóno póki e sémplichi: pomodóri mólto matúri, páne raf-férmo, áll-llo, sále e tánto ólio ecstravérdyine dolíva. Si frúl-la tút-to finké la créma divénta lísh-sha e si sérve ben fréd-da, con pet-tsét-ti di prosh-shút-to crúdo e di uóvo sódo.\n\nPer me il salmoréjo e legáto ai prántsi destáte a cása di mia nón-na: cuándo fachéva tróp-po cáldo per mandyáre, lei met-téva in távola úna gránde chótola e tút-ti eravámo felíchi. Ancóra ód-dyi, cuándo lo prepáro, sénto il profúmo di cuél-la cuchína.\n\nVe lo consíll-llo perké e sáno, económico e perfét-to nél-le dyornáte cálde. Ma at-tentsióne: il segréto e usáre un ólio di cualitá!"],"check":["Trato los cuatro puntos: qué plato y de dónde, preparación, recuerdos y recomendación.","El texto tiene entre 125 y 150 palabras.","Tiene título atractivo, introducción y cierre, y párrafos bien separados.","Combino bien los tiempos del pasado (passato prossimo / imperfetto) y uso el «si» impersonal para la receta (si frulla, si serve).","Uso léxico preciso de cocina (ingredientes, verbos de preparación) y conectores variados (finché, quando, perché, ma).","Registro adecuado a una revista: cercano pero cuidado; ortografía y acentos correctos."]},{"t":"Tarea 2 · Coproducción","ins":"Ha recibido este correo de Lorenzo Gatti, profesor de un instituto de hostelería italiano. Respóndale con un correo formal (100–125 palabras): agradezca la propuesta y diga si le interesa, proponga dos o tres actividades para la semana del intercambio, comente las fechas y diga cuándo está disponible para la videollamada.","words":[100,125],"source":"Gentile collega,\n\nmi chiamo Lorenzo Gatti e insegno cucina in un istituto alberghiero della provincia di Rimini. Abbiamo trovato la vostra scuola tra i partecipanti al programma Erasmus+ e vorremmo proporvi uno scambio: un gruppo di quindici studenti del secondo anno potrebbe venire in Andalusia per una settimana a marzo, e i vostri studenti potrebbero venire da noi a maggio.\n\nLe sarei grato se potesse dirmi se la proposta vi interessa, quali attività potreste organizzare e se ci sono date più adatte per voi. Naturalmente sono disponibile per una videochiamata.\n\nCordiali saluti,\nLorenzo Gatti","model":["Gentile professor Gatti,\n\nLa ringrazio per la Sua proposta, che ci interessa moltissimo. Ne ho già parlato con la direzione e con i colleghi del dipartimento, e sono tutti d'accordo.\n\nDurante la settimana potremmo organizzare lezioni pratiche nella nostra cucina, dove i Suoi studenti preparerebbero piatti andalusi insieme ai nostri, e una visita a una cantina di Jerez.\n\nPer quanto riguarda le date, marzo va bene, ma Le consiglierei di evitare la settimana prima di Pasqua, se cade in quel mese, perché la scuola è chiusa.\n\nPer la videochiamata sono disponibile martedì o giovedì pomeriggio, dopo le sedici.\n\nIn attesa di una Sua risposta, Le invio cordiali saluti.\n\nAlejandro","Dyentíle profes-sór Gát-ti,\n\nLa ringrát-tsio per la Súa propósta, ke chi interés-sa moltís-simo. Ne o dya parláto con la diret-tsióne e con i col-légui del dipartiménto, e sóno tút-ti dac-córdo.\n\nDuránte la set-timána potrém-mo organid-dsáre let-tsióni prátike nél-la nóstra cuchína, dóve i Suoi studénti prepareréb-bero piát-ti andalúsi insiéme ai nóstri, e úna vísita a úna cantína di Jeréts.\n\nPer cuánto riguárda le dáte, mártso va béne, ma Le consill-lleréi di evitáre la set-timána príma di Páscua, se cáde in cuel mése, perké la scúola e kiúsa.\n\nPer la videokiamáta sóno disponíbile martedí o dyovedí pomeríd-dyo, dópo le sédichi.\n\nIn at-tésa di úna Súa rispósta, Le invío cordiáli salúti.\n\nAlejándro"],"check":["Respondo a las cuatro cuestiones: interés, actividades, fechas y disponibilidad para la videollamada.","El texto tiene entre 100 y 125 palabras.","Uso fórmulas formales de saludo y despedida (Gentile professore, La ringrazio, Cordiali saluti) y mantengo el Lei en todo el correo.","Uso el condicional para proponer con cortesía (potremmo, Le consiglierei).","Organizo el correo en párrafos con conectores (per quanto riguarda, perché, durante).","Ortografía, concordancias y pronombres de cortesía correctos (Le, Sua, Suoi)."]}]},{"k":"pcto","t":"Producción y coproducción orales y mediación oral","tasks":[{"t":"Tarea 1 · Mediación oral","ins":"Un amigo italiano, Giorgio, que no habla español, quiere participar este fin de semana en la ruta de la tapa de su ciudad. Explíquele en italiano lo esencial del folleto: las fechas, en qué consiste y cuánto cuesta, cómo funciona el «tapaporte» y el premio, los horarios y el consejo final. No traduzca palabra por palabra: adapte la información.","prep":2,"speak":[2,3],"source":"XV RUTA DE LA TAPA · CASCO ANTIGUO\nDel 14 al 16 de noviembre, 30 bares y restaurantes del centro ofrecen una tapa especial acompañada de una bebida (caña, copa de vino o refresco) por 3,50 €.\nRecoge tu «tapaporte» en cualquier establecimiento participante y pide que te lo sellen en cada parada. Con 6 sellos puedes votar tu tapa favorita y participar en el sorteo de una cena para dos personas.\nHorario: de 13:00 a 16:00 y de 20:00 a 23:30. Fuera de este horario no se sirven las tapas de la ruta.\nConsejo: el sábado por la noche hay mucha gente. ¡Ven el viernes o el domingo a mediodía!","model":["Allora, Giorgio, ti spiego. È una specie di giro dei bar: dal quattordici al sedici novembre trenta locali del centro storico preparano una tapa speciale, cioè un piattino, e te la danno insieme a una bevanda — una birra piccola, un bicchiere di vino o una bibita — per tre euro e cinquanta. In qualsiasi locale della ruta ti danno una specie di passaporto, il «tapaporte», e ogni volta che mangi una tapa ti mettono un timbro. Quando ne hai sei, puoi votare la tapa che ti è piaciuta di più e partecipi all'estrazione di una cena per due. Attenzione agli orari: le tapas si servono solo dall'una alle quattro e dalle otto alle undici e mezza. E un consiglio: il sabato sera c'è tantissima gente, quindi è meglio andare venerdì oppure domenica a pranzo.","Al-lóra, Dyórdyo, ti spiégo. E úna spéche di dyíro dei bar: dal cuat-tórdichi al sédichi novémbre trénta locáli del chéntro stórico prepárano úna tápa spéchale, choé un piat-tíno, e te la dán-no insiéme a úna bevánda — úna bír-ra píc-cola, un bik-kiére di víno o úna bíbita — per tre éuro e chincuánta. In cualsiási locále dél-la rúta ti dán-no úna spéche di pas-sapórto, il «tapapórte», e óñ-ñi vólta ke mándyi úna tápa ti mét-tono un tímbro. Cuándo ne ai sei, puoi votáre la tápa ke ti e piachúta di piu e partéchipi al-lestrat-tsióne di úna chéna per due. At-tentsióne áll-lli orári: le tápas si sérvono sólo dal-lúna ál-le cuát-tro e dál-le ót-to ál-le úndichi e méd-dsa. E un consíll-llo: il sábato séra che tantís-sima dyénte, cuíndi e méll-llo andáre venerdí op-púre doménica a prántso."],"check":["Transmito fechas, precio y qué incluye, cómo funciona el tapaporte, el premio, los horarios y el consejo.","Explico lo que mi amigo no conoce (qué es una tapa, una caña) en vez de dejar las palabras en español.","Selecciono y reorganizo la información; no traduzco palabra por palabra.","Uso bien números, fechas y horas (dal… al…, dall'una alle quattro).","Hablo con fluidez durante 2–3 minutos, con un registro informal coherente (ti, puoi, hai)."]},{"t":"Tarea 2 · Monólogo","ins":"Hable sobre el tema «Viajar» respondiendo a las tres preguntas (en el examen, las preguntas aparecen en italiano):\n1. ¿Prefiere viajar solo/a o acompañado/a? ¿Por qué?\n2. Hable de un viaje que recuerde especialmente.\n3. ¿Cree que el turismo masivo es un problema? ¿Qué se podría hacer?","prep":2,"speak":[3,4],"source":"Viaggiare\n1. Preferisci viaggiare da solo o in compagnia? Perché?\n2. Racconta un viaggio che ricordi in modo particolare.\n3. Secondo te, il turismo di massa è un problema? Che cosa si potrebbe fare?","model":["In generale preferisco viaggiare in compagnia, con la mia famiglia o con gli amici, perché mi piace condividere le esperienze: una cena o un paesaggio sono più belli se puoi commentarli con qualcuno. Però capisco chi viaggia da solo: si è più liberi e si conosce più gente del luogo. Un viaggio che ricordo in modo particolare è quello che ho fatto a Bologna e a Parma qualche anno fa. Ho visitato un caseificio di Parmigiano Reggiano, ho visto come si lavora il latte all'alba e ho assaggiato formaggi stagionati per trenta e più mesi. Per un cuoco è stata un'esperienza indimenticabile, e da allora uso questo formaggio in modo diverso. Per quanto riguarda il turismo di massa, credo che sia un problema serio, soprattutto per le città piccole e famose come Venezia o, in Spagna, alcuni quartieri di Barcellona e di Siviglia. Gli affitti aumentano, gli abitanti se ne vanno e i negozi tradizionali chiudono. Secondo me bisognerebbe limitare gli appartamenti turistici e promuovere mete meno conosciute. Anche noi turisti possiamo fare qualcosa: viaggiare fuori stagione e rispettare la vita di chi ci abita.","In dyenerále preferísco viad-dyáre in compañ-ñía, con la mia famíll-lla o con lli amíchi, perké mi piáche condivídere le esperiéntse: úna chéna o un paésad-dyo sóno piu bél-li se puoi com-mentárli con cualcúno. Peró capísco ki viád-dya da sólo: si e piu líberi e si conósh-she piu dyénte del lúogo. Un viád-dyo ke ricórdo in módo particólare e cuél-lo ke o fát-to a Bolóñ-ña e a Párma cuálke án-no fa. O visitáto un caseifícho di Parmidyáno Red-dyáno, o vísto cóme si lávora il lát-te al-lálba e o as-sad-dyáto formád-dyi stadyonáti per trénta e piu mési. Per un cuóco e státa unesperiéntsa indimenticábile, e da al-lóra úso cuésto formád-dyo in módo divérso. Per cuánto riguárda il turísmo di más-sa, crédo ke sia un probléma sério, soprat-tút-to per le chit-tá píc-cole e famóse cóme Venét-tsia o, in Spáñ-ña, alcúni cuartiéri di Barchel-lóna e di Sivíll-lla. Lli af-fít-ti auméntano, lli abitánti se ne ván-no e i negót-tsi tradit-tsionáli kiúdono. Secóndo me bisoñ-ñeréb-be limitáre lli ap-partaménti turístichi e promuóvere méte méno conosh-shúte. Ánke noi turísti pos-siámo fáre cualcósa: viad-dyáre fuóri stadyóne e rispet-táre la víta di ki chi ábita."],"check":["Respondo a las tres preguntas y desarrollo cada una con ejemplos.","Hablo entre 3 y 4 minutos de forma continuada, sin leer.","Doy y justifico opiniones (secondo me, credo che + congiuntivo, perché).","Narro el viaje combinando passato prossimo e imperfetto.","Uso conectores para organizar el discurso (in generale, però, per quanto riguarda, anche).","Pronunciación clara y entonación natural; me corrijo si me equivoco."]},{"t":"Tarea 3 · Diálogo","ins":"Un amigo común cumple cuarenta años y ustedes quieren hacerle un regalo juntos. Comenten las opciones (un viaje corto, un curso de cocina, una cena especial, un objeto…), el presupuesto y la forma de organizarlo, y lleguen a un acuerdo. Defienda su opinión, pero escuche la de su compañero/a.","prep":1,"speak":[4,5],"source":"","model":["A: Allora, per i quaranta anni di Luca che cosa gli regaliamo? Io pensavo a un fine settimana in un agriturismo.\nB: Mm, è un'idea carina, ma costa parecchio. E poi dovremmo scegliere noi le date, e lui lavora spesso nel fine settimana.\nA: Hai ragione. Che ne dici di un corso di cucina? Lui parla sempre di voler imparare a fare la pasta fresca.\nB: Questo mi piace di più. Ci sono corsi di una sera, quindi può scegliere lui il giorno. Quanto pensi che costi?\nA: Ho visto che un corso di tre ore costa circa sessanta euro. Se lo regaliamo in sei, sono dieci euro a testa.\nB: Allora possiamo aggiungere qualcosa: per esempio un grembiule con il suo nome.\nA: Perfetto! Tu ti occupi del corso e io del grembiule e di raccogliere i soldi?\nB: D'accordo. Glielo diamo sabato alla festa. Sono sicura che gli piacerà!","A: Al-lóra, per i cuaránta án-ni di Lúca ke cósa lli regaliámo? Io pensávo a un fíne set-timána in un agriturísmo.\nB: M-m, e unidéa carína, ma cósta parék-kio. E poi dovrém-mo shéll-llere noi le dáte, e lui lavóra spés-so nel fíne set-timána.\nA: Ai radyóne. Ke ne díchi di un córso di cuchína? Lui párla sémpre di volér imparáre a fáre la pásta frésca.\nB: Cuésto mi piáche di piu. Chi sóno córsi di úna séra, cuíndi puo shéll-llere lui il dyórno. Cuánto pénsi ke cósti?\nA: O vísto ke un córso di tre óre cósta chírca ses-sánta éuro. Se lo regaliámo in sei, sóno diéchi éuro a tésta.\nB: Al-lóra pos-siámo ad-dyúndyere cualcósa: per esémpio un grembiúle con il suo nóme.\nA: Perfét-to! Tu ti óc-cupi del córso e io del grembiúle e di rac-cóll-llere i sóldi?\nB: Dac-córdo. Llélo diámo sábato ál-la fésta. Sóno sicúra ke lli piacherá!"],"check":["Proponemos, comparamos opciones y llegamos a un acuerdo claro (qué regalo, cuánto cuesta, quién hace qué).","Expreso acuerdo y desacuerdo con matices (hai ragione, ma…; questo mi piace di più; secondo me…).","Uso el condicional y el congiuntivo básico para proponer y opinar (dovremmo, penso che costi).","Reacciono a lo que dice mi compañero y hago preguntas para avanzar.","Intervenciones equilibradas: ni monopolizo ni me quedo callado.","Pronunciación y entonación naturales, sin pausas largas."]}]}]}],"recipes":[{"id":"r01","t":"Spaghetti alla carbonara","tp":"Spaguét-ti ál-la carbonára","es_t":"Espaguetis a la carbonara","region":"Lazio","serves":4,"time":"25 min","ing":[["guanciale","guanchále","150 g","carrillada/papada de cerdo curada (guanciale)"],["spaghetti","spaguét-ti","320 g","espaguetis"],["tuorli d'uovo","tuórli duóvo","4","yemas de huevo"],["uovo intero","uóvo intéro","1","huevo entero"],["Pecorino Romano DOP grattugiato","Pecoríno Románo Dop grat-tudyáto","60 g","queso pecorino romano DOP (oveja), rallado"],["pepe nero macinato al momento","pépe néro machináto al moménto","al gusto (abundante)","pimienta negra recién molida"],["sale grosso","sále grós-so","para el agua","sal gruesa para el agua de cocción"]],"steps":[["Tagliare il guanciale a listarelle.","Tall-lláre il guanchále a listarél-le.","Cortar el guanciale en tiras."],["Rosolare il guanciale in padella, senza olio, finché diventa croccante.","Rosoláre il guanchále in padél-la, séntsa ólio, finké divénta croc-cánte.","Dorar el guanciale en la sartén, sin aceite, hasta que quede crujiente."],["Sbattere i tuorli e l'uovo con il pecorino e abbondante pepe nero.","Sbát-tere i tuórli e luóvo con il pecoríno e ab-bondánte pépe néro.","Batir las yemas y el huevo con el pecorino y abundante pimienta negra."],["Cuocere gli spaghetti in abbondante acqua salata.","Cuóchere lli spaguét-ti in ab-bondánte ác-cua saláta.","Cocer los espaguetis en abundante agua con sal."],["Scolare la pasta al dente e saltarla nella padella con il guanciale.","Scoláre la pásta al dénte e saltárla nél-la padél-la con il guanchále.","Escurrir la pasta al dente y saltearla en la sartén con el guanciale."],["Fuori dal fuoco, aggiungere la crema di uova e un po' d'acqua di cottura.","Fuóri dal fuóco, ad-dyúndyere la créma di uóva e un po dác-cua di cot-túra.","Fuera del fuego, añadir la crema de huevo y un poco de agua de cocción."],["Mescolare velocemente fino a ottenere una crema liscia.","Mescoláre velocheménte fíno a ot-tenére úna créma lísh-sha.","Mezclar rápidamente hasta obtener una crema lisa."],["Servire subito con altro pecorino e pepe.","Servíre súbito con áltro pecoríno e pépe.","Servir enseguida con más pecorino y pimienta."]],"notes":"Receta romana: solo guanciale, huevo, pecorino romano y pimienta negra; la cremosidad sale de la emulsión de huevo, queso, grasa del guanciale y agua de cocción. Errores típicos en España: añadir nata, cebolla, ajo o champiñones; usar bacon ahumado; cuajar el huevo en el fuego hasta que queda como un revuelto (hay que ligarlo fuera del fuego). Ojo con la sal: el guanciale y el pecorino ya son salados. Variantes aceptadas en Roma: rigatoni o mezze maniche en vez de espaguetis; solo yemas o yemas más algún huevo entero; parte de Parmigiano Reggiano mezclado con el pecorino. La panceta (pancetta) es un sustituto frecuente, pero no es la versión canónica.","all":["Cereali contenenti glutine","Uova","Latte"],"voc":[["rosolare","rosoláre","dorar (a fuego medio)"],["scolare","scoláre","escurrir"],["al dente","al dénte","al dente (cocida pero firme)"],["l'acqua di cottura","lác-cua di cot-túra","el agua de cocción"],["la padella","la padél-la","la sartén"],["mantecare","mantecáre","ligar con grasa y queso hasta dejar cremoso"]]},{"id":"r02","t":"Spaghetti all'amatriciana","tp":"Spaguét-ti al-lamatrichána","es_t":"Espaguetis a la amatriciana","region":"Lazio","serves":4,"time":"30 min","ing":[["guanciale","guanchále","150 g","carrillada/papada de cerdo curada (guanciale)"],["spaghetti","spaguét-ti","400 g","espaguetis"],["pomodori pelati San Marzano","pomodóri peláti San Martsáno","400 g","tomates pelados San Marzano (o 6–7 tomates frescos maduros)"],["Pecorino di Amatrice o Pecorino Romano grattugiato","Pecoríno di Amatríche o Pecoríno Románo grat-tudyáto","80 g","queso pecorino de Amatrice o romano, rallado"],["vino bianco secco","víno biánco séc-co","50 ml","vino blanco seco"],["olio extravergine d'oliva","ólio ecstravérdyine dolíva","1 cucharada","aceite de oliva virgen extra"],["peperoncino","peperonchíno","1 trocito","guindilla"],["pepe nero","pépe néro","al gusto","pimienta negra"],["sale","sále","al gusto","sal"]],"steps":[["Tagliare il guanciale a listarelle.","Tall-lláre il guanchále a listarél-le.","Cortar el guanciale en tiras."],["Rosolare il guanciale in padella con l'olio e il peperoncino.","Rosoláre il guanchále in padél-la con lólio e il peperonchíno.","Dorar el guanciale en la sartén con el aceite y la guindilla."],["Sfumare con il vino bianco.","Sfumáre con il víno biánco.","Regar con el vino blanco y dejar que se evapore."],["Togliere il guanciale e tenerlo da parte al caldo.","Toll-llére il guanchále e tenérlo da párte al cáldo.","Retirar el guanciale y reservarlo al calor."],["Aggiungere i pomodori, salare e cuocere per pochi minuti.","Ad-dyúndyere i pomodóri, saláre e cuóchere per póki minúti.","Añadir los tomates, salar y cocer unos minutos."],["Togliere il peperoncino e riunire il guanciale al sugo.","Toll-llére il peperonchíno e riuníre il guanchále al súgo.","Retirar la guindilla y volver a poner el guanciale en la salsa."],["Cuocere gli spaghetti al dente in acqua salata.","Cuóchere lli spaguét-ti al dénte in ác-cua saláta.","Cocer los espaguetis al dente en agua con sal."],["Condire la pasta con il pecorino e poi con il sugo, mescolando bene.","Condíre la pásta con il pecoríno e poi con il súgo, mescolándo béne.","Aliñar la pasta con el pecorino y luego con la salsa, mezclando bien."]],"notes":"Plato de Amatrice (provincia de Rieti, Lacio). El ayuntamiento de Amatrice defiende como únicos ingredientes guanciale, pecorino, vino blanco, tomate San Marzano, pimienta negra y guindilla. Nada de cebolla ni ajo, y nada de panceta ahumada. En Amatrice se hace con espaguetis; en Roma son muy habituales los bucatini (variante aceptada). Para sofreír se usa sobre todo aceite de oliva, aunque también hay quien usa manteca de cerdo (strutto). La versión sin tomate es otro plato clásico romano: la gricia.","all":["Cereali contenenti glutine","Latte","Anidride solforosa e solfiti"],"voc":[["sfumare","sfumáre","regar con vino y dejar evaporar"],["il sugo","il súgo","la salsa (de la pasta)"],["tenere da parte","tenére da párte","reservar"],["condire","condíre","aliñar, aderezar"],["quanto basta","cuánto básta","la cantidad necesaria (en las recetas se abrevia «q.b.»; en español, c. s.)"]]},{"id":"r03","t":"Ragù alla bolognese","tp":"Ragú ál-la boloñ-ñése","es_t":"Ragú a la boloñesa","region":"Emilia-Romagna","serves":6,"time":"2 h 30 min","ing":[["polpa di manzo macinata grossa","pólpa di mántso machináta grós-sa","400 g","carne magra de vacuno picada gruesa"],["pancetta fresca di maiale","panchét-ta frésca di maiále","150 g","panceta fresca de cerdo (sin ahumar), en lonchas"],["cipolla","chipól-la","½ (unos 60 g)","cebolla"],["carota","caróta","1 (unos 60 g)","zanahoria"],["sedano","sédano","1 rama (unos 60 g)","apio"],["vino rosso o bianco","víno rós-so o biánco","1 vaso","vino tinto o blanco"],["passata di pomodoro","pas-sáta di pomodóro","200 g","tomate triturado y colado (passata)"],["doppio concentrato di pomodoro","dóp-pio conchentráto di pomodóro","1 cucharada","doble concentrado de tomate"],["latte intero","lát-te intéro","1 vaso (opcional)","leche entera"],["brodo di carne o vegetale","bródo di cárne o vedyetále","según necesidad","caldo ligero de carne o de verduras (también de pastilla)"],["olio extravergine d'oliva","ólio ecstravérdyine dolíva","3 cucharadas","aceite de oliva virgen extra"],["sale e pepe","sále e pépe","al gusto","sal y pimienta"]],"steps":[["Sciogliere nell'olio la pancetta tagliata a dadini, in un tegame dal fondo spesso.","Shóll-llere nel-lólio la panchét-ta tall-lláta a dadíni, in un tegáme dal fóndo spés-so.","Fundir la panceta cortada en daditos en el aceite, en una cacerola de fondo grueso."],["Aggiungere cipolla, carota e sedano tritati al coltello e farli appassire a fuoco dolce.","Ad-dyúndyere chipól-la, caróta e sédano tritáti al coltél-lo e fárli ap-pas-síre a fuóco dólche.","Añadir la cebolla, la zanahoria y el apio picados a cuchillo y pocharlos a fuego suave."],["Alzare la fiamma, unire la carne e rosolarla per circa dieci minuti.","Altsáre la fiám-ma, uníre la cárne e rosolárla per chírca diéchi minúti.","Subir el fuego, incorporar la carne y dorarla unos diez minutos."],["Sfumare con il vino e lasciarlo evaporare completamente.","Sfumáre con il víno e lash-shárlo evaporáre completaménte.","Regar con el vino y dejar que se evapore por completo."],["Aggiungere il concentrato e la passata, poi il brodo caldo un mestolo alla volta.","Ad-dyúndyere il conchentráto e la pas-sáta, poi il bródo cáldo un méstolo ál-la vólta.","Añadir el concentrado y la passata, y luego el caldo caliente cazo a cazo."],["Cuocere piano, con il coperchio, per circa due ore.","Cuóchere piáno, con il copérkio, per chírca dúe óre.","Cocer a fuego lento, tapado, unas dos horas."],["A metà cottura aggiungere, se si vuole, il latte e farlo ritirare del tutto.","A metá cot-túra ad-dyúndyere, se si vuóle, il lát-te e fárlo ritiráre del tút-to.","A media cocción añadir, si se quiere, la leche y dejar que se absorba del todo."],["Regolare di sale e pepe a fine cottura.","Regoláre di sále e pépe a fíne cot-túra.","Rectificar de sal y pimienta al final de la cocción."]],"notes":"La Accademia Italiana della Cucina registró la receta en la Cámara de Comercio de Bolonia en 1982 (con «cartella», un corte de vacuno hoy difícil de encontrar) y en 2023 depositó una versión actualizada, que es la que sigue esta ficha (6 raciones). Variantes admitidas en 2023: carne mixta (≈60 % vacuno y 40 % cerdo, de lomo o cabecero), carne picada a cuchillo, panceta curada (stesa o arrotolata) en lugar de la fresca y un toque de nuez moscada. Es un ragú de carne, no una salsa de tomate: el tomate es poco. En Bolonia se sirve con tagliatelle al huevo (o en lasaña), no con espaguetis. Errores típicos: añadir ajo o hierbas, usar panceta ahumada, cocerlo poco tiempo. Si se sirve con tagliatelle al huevo, hay que añadir los alérgenos gluten y huevo.","all":["Sedano","Latte","Anidride solforosa e solfiti"],"voc":[["il soffritto","il sof-frít-to","el sofrito (cebolla, zanahoria y apio)"],["tritare al coltello","tritáre al coltél-lo","picar a cuchillo"],["il tegame","il tegáme","la cacerola baja"],["il mestolo","il méstolo","el cazo, el cucharón"],["cuocere a fuoco lento","cuóchere a fuóco lénto","cocer a fuego lento"],["far ritirare","far ritiráre","dejar reducir, dejar que se absorba"]]},{"id":"r04","t":"Pesto alla genovese","tp":"Pésto ál-la dyenovése","es_t":"Pesto a la genovesa","region":"Liguria","serves":6,"time":"20 min","ing":[["basilico genovese DOP","basílico dyenovése Dop","50 g (hojas)","albahaca genovesa DOP, de hoja pequeña"],["Parmigiano Reggiano DOP grattugiato","Parmidyáno Red-dyáno Dop grat-tudyáto","6 cucharadas","Parmigiano Reggiano rallado (o Grana Padano)"],["Fiore Sardo DOP grattugiato","Fióre Sárdo Dop grat-tudyáto","2 cucharadas","pecorino Fiore Sardo (queso de oveja sardo) rallado"],["olio extravergine d'oliva","ólio ecstravérdyine dolíva","½ vaso","aceite de oliva virgen extra (mejor de Liguria)"],["pinoli","pinóli","1 cucharada","piñones"],["spicchi d'aglio","spík-ki dáll-llo","2","dientes de ajo"],["sale grosso","sále grós-so","unos granos","sal gruesa"]],"steps":[["Lavare il basilico in acqua fredda e asciugarlo su un canovaccio, senza strofinarlo.","Laváre il basílico in ác-cua fréd-da e ash-shugárlo su un canovát-cho, séntsa strofinárlo.","Lavar la albahaca en agua fría y secarla sobre un paño, sin frotarla."],["Nel mortaio di marmo pestare l'aglio con qualche grano di sale grosso.","Nel mortáio di mármo pestáre láll-llo con cuálke gráno di sále grós-so.","En el mortero de mármol, machacar el ajo con unos granos de sal gruesa."],["Aggiungere i pinoli e ridurli in crema.","Ad-dyúndyere i pinóli e ridúrli in créma.","Añadir los piñones y reducirlos a crema."],["Unire il basilico poco alla volta e pestare con un movimento rotatorio contro le pareti.","Uníre il basílico póco ál-la vólta e pestáre con un moviménto rotatório cóntro le paréti.","Incorporar la albahaca poco a poco y machacar con un movimiento giratorio contra las paredes."],["Quando il basilico rilascia un liquido verde brillante, aggiungere i formaggi.","Cuándo il basílico rilásh-sha un lícuido vérde bril-lánte, ad-dyúndyere i formád-dyi.","Cuando la albahaca suelte un líquido verde brillante, añadir los quesos."],["Versare l'olio a filo, mescolando per amalgamare.","Versáre lólio a fílo, mescolándo per amalgamáre.","Verter el aceite en hilo, mezclando para amalgamar."],["Condire la pasta, allungando se occorre con un po' d'acqua di cottura.","Condíre la pásta, al-lungándo se oc-cór-re con un po dác-cua di cot-túra.","Aliñar la pasta, aligerando si hace falta con un poco de agua de cocción."]],"notes":"Receta del Consorzio del Pesto Genovese, pensada para unos 600 g de pasta. Tradicionalmente se hace en mortero de mármol con mano de madera y deprisa, para que la albahaca no se oxide. El Grana Padano se admite en lugar del Parmigiano. En Liguria se sirve con trofie o trenette, a menudo con patata y judía verde cocidas con la pasta. El pesto no se cocina: se añade en crudo a la pasta escurrida. Errores típicos: triturar mucho rato con batidora (calienta y oscurece la albahaca), sustituir los piñones por nueces o anacardos (no es la receta tradicional y, además, son alérgenos de declaración obligatoria). Los piñones no figuran entre los 14 alérgenos del Reglamento 1169/2011, pero conviene avisar a quien sea alérgico.","all":["Latte"],"voc":[["il mortaio","il mortáio","el mortero"],["il pestello","il pestél-lo","la mano del mortero"],["pestare","pestáre","machacar"],["a filo","a fílo","en hilo (verter)"],["il canovaccio","il canovát-cho","el paño de cocina"],["amalgamare","amalgamáre","amalgamar, ligar"]]},{"id":"r05","t":"Risotto alla milanese","tp":"Risót-to ál-la milanése","es_t":"Risotto a la milanesa","region":"Lombardia","serves":4,"time":"30 min","ing":[["riso Carnaroli o Vialone Nano","ríso Carnaróli o Vialóne Náno","320 g","arroz Carnaroli o Vialone Nano"],["brodo di carne","bródo di cárne","1,2 l aprox.","caldo de carne, caliente"],["midollo di bue","midól-lo di búe","40 g","tuétano de buey"],["burro","búr-ro","80 g","mantequilla (parte para el sofrito, parte fría para mantecar)"],["cipolla","chipól-la","½ (unos 50 g)","cebolla"],["zafferano","dsaf-feráno","0,2–0,3 g","azafrán (en hebras o en polvo)"],["Grana Padano o Parmigiano Reggiano grattugiato","Grána Padáno o Parmidyáno Red-dyáno grat-tudyáto","60 g","queso rallado"],["sale","sále","al gusto","sal"]],"steps":[["Sciogliere lo zafferano in un po' di brodo caldo.","Shóll-llere lo dsaf-feráno in un po di bródo cáldo.","Disolver el azafrán en un poco de caldo caliente."],["Far appassire la cipolla tritata finemente con il midollo e metà del burro.","Far ap-pas-síre la chipól-la tritáta fineménte con il midól-lo e metá del búr-ro.","Pochar la cebolla picada muy fina con el tuétano y la mitad de la mantequilla."],["Tostare il riso a fuoco vivace, mescolando, per un paio di minuti.","Tostáre il ríso a fuóco viváche, mescolándo, per un páio di minúti.","Nacarar el arroz a fuego vivo, removiendo, un par de minutos."],["Bagnare con il brodo bollente poco alla volta, mescolando spesso.","Bañ-ñáre con il bródo bol-lénte póco ál-la vólta, mescolándo spés-so.","Mojar con el caldo hirviendo poco a poco, removiendo a menudo."],["A metà cottura aggiungere lo zafferano sciolto.","A metá cot-túra ad-dyúndyere lo dsaf-feráno shólto.","A media cocción, añadir el azafrán disuelto."],["Cuocere per circa sedici-diciotto minuti, finché il riso è al dente.","Cuóchere per chírca sédichi-dichót-to minúti, finké il ríso e al dénte.","Cocer unos dieciséis-dieciocho minutos, hasta que el arroz esté al dente."],["Togliere dal fuoco e mantecare con il burro freddo e il formaggio.","Tóll-llere dal fuóco e mantecáre con il búr-ro fréd-do e il formád-dyo.","Retirar del fuego y mantecar con la mantequilla fría y el queso."],["Lasciare riposare un minuto e servire all'onda.","Lash-sháre riposáre un minúto e servíre al-lónda.","Dejar reposar un minuto y servir «all'onda» (cremoso y ondulante)."]],"notes":"El tuétano de buey es el ingrediente tradicional que da al plato su sabor característico; se puede hacer solo con mantequilla, pero ya no es la versión clásica. Muchas recetas añaden un chorrito de vino blanco seco después de nacarar el arroz: es una variante aceptada (entonces hay que añadir el alérgeno sulfitos). Es el acompañamiento clásico del ossobuco. Errores típicos: lavar el arroz (pierde el almidón que da la cremosidad), echar todo el caldo de golpe, añadir nata para ligar, o dejarlo seco y compacto: debe quedar «all'onda». El alérgeno apio procede del caldo de carne tradicional (lleva apio, zanahoria y cebolla).","all":["Latte","Sedano"],"voc":[["tostare il riso","tostáre il ríso","nacarar el arroz"],["bagnare","bañ-ñáre","mojar (con caldo)"],["mantecare","mantecáre","mantecar (ligar con mantequilla y queso fuera del fuego)"],["all'onda","al-lónda","«a la ola»: cremoso y suelto, que ondula en el plato"],["il mestolo","il méstolo","el cazo, el cucharón"]]},{"id":"r06","t":"Ossobuco alla milanese con gremolata","tp":"Os-sobúco ál-la milanése con gremoláta","es_t":"Ossobuco a la milanesa con gremolata","region":"Lombardia","serves":4,"time":"2 h","ing":[["ossibuchi di vitello","os-sibúki di vitél-lo","4 (unos 300 g cada uno)","rodajas de jarrete de ternera con hueso y tuétano"],["farina 00","farína 00","40 g","harina de trigo, para enharinar"],["burro","búr-ro","50 g","mantequilla"],["cipolla","chipól-la","1 (unos 100 g)","cebolla"],["vino bianco secco","víno biánco séc-co","150 ml","vino blanco seco"],["brodo di carne","bródo di cárne","500 ml aprox.","caldo de carne"],["scorza di limone","scórtsa di limóne","la de 1 limón","piel de limón (solo la parte amarilla)"],["spicchio d'aglio","spík-kio dáll-llo","1","diente de ajo"],["prezzemolo","pret-tsémolo","1 manojo pequeño","perejil"],["sale e pepe","sále e pépe","al gusto","sal y pimienta"]],"steps":[["Incidere la pellicola sul bordo degli ossibuchi, così restano piatti in cottura.","Inchídere la pel-lícola sul bórdo déll-lli os-sibúki, cosí réstano piát-ti in cot-túra.","Hacer unos cortes en la membrana del borde de los ossobuchi, para que se queden planos al cocerse."],["Infarinare leggermente gli ossibuchi.","Infarináre led-dyerménte lli os-sibúki.","Enharinar ligeramente los ossobuchi."],["Rosolarli nel burro da entrambi i lati.","Rosolárli nel búr-ro da entrámbi i láti.","Dorarlos en la mantequilla por ambos lados."],["Aggiungere la cipolla tritata e farla appassire.","Ad-dyúndyere la chipól-la tritáta e fárla ap-pas-síre.","Añadir la cebolla picada y pocharla."],["Sfumare con il vino bianco e lasciarlo evaporare.","Sfumáre con il víno biánco e lash-shárlo evaporáre.","Regar con el vino blanco y dejar que se evapore."],["Bagnare con il brodo caldo, coprire e cuocere a fuoco basso per circa un'ora e mezza.","Bañ-ñáre con il bródo cáldo, copríre e cuóchere a fuóco bás-so per chírca unóra e méd-dsa.","Mojar con el caldo caliente, tapar y cocer a fuego bajo alrededor de una hora y media."],["Tritare finemente scorza di limone, aglio e prezzemolo per la gremolata.","Tritáre fineménte scórtsa di limóne, áll-llo e pret-tsémolo per la gremoláta.","Picar muy fino la piel de limón, el ajo y el perejil para la gremolata."],["Cospargere gli ossibuchi con la gremolata pochi minuti prima di servirli.","Cospárdyere lli os-sibúki con la gremoláta póki minúti príma di servírli.","Espolvorear los ossobuchi con la gremolata unos minutos antes de servirlos."]],"notes":"Ossobuco significa «hueso hueco»: el tuétano del centro se come y es parte del plato. La versión milanesa tradicional es «in bianco», sin tomate; la versión con tomate está muy extendida y se acepta como variante. Se sirve típicamente con risotto alla milanese. La gremolata (limón, ajo y perejil) se añade al final para que conserve el aroma. Errores típicos: no cortar la membrana del borde (la pieza se curva), cocer a fuego fuerte (la carne se endurece) o añadir la gremolata al principio.","all":["Cereali contenenti glutine","Latte","Sedano","Anidride solforosa e solfiti"],"voc":[["incidere","inchídere","hacer cortes, incidir"],["infarinare","infarináre","enharinar"],["il coperchio","il copérkio","la tapa"],["cospargere","cospárdyere","espolvorear, esparcir por encima"],["la gremolata","la gremoláta","la gremolata (picada de limón, ajo y perejil)"]]},{"id":"r07","t":"Parmigiana di melanzane","tp":"Parmidyána di melandsáne","es_t":"Parmigiana de berenjenas","region":"Campania / Sicilia","serves":6,"time":"1 h 30 min","ing":[["melanzane","melandsáne","1,5 kg","berenjenas"],["passata di pomodoro","pas-sáta di pomodóro","700 ml","tomate triturado y colado (passata)"],["fiordilatte o mozzarella","fiordilát-te o mot-tsarél-la","400 g","mozzarella de vaca (fior di latte), bien escurrida"],["Parmigiano Reggiano grattugiato","Parmidyáno Red-dyáno grat-tudyáto","100 g","Parmigiano Reggiano rallado"],["basilico","basílico","1 manojo","albahaca"],["spicchio d'aglio","spík-kio dáll-llo","1","diente de ajo (o un poco de cebolla) para la salsa"],["olio extravergine d'oliva","ólio ecstravérdyine dolíva","2 cucharadas","aceite de oliva virgen extra para la salsa"],["olio per friggere","ólio per fríd-dyere","c. s.","aceite para freír"],["sale","sále","al gusto","sal"]],"steps":[["Tagliare le melanzane a fette di circa mezzo centimetro.","Tall-lláre le melandsáne a fét-te di chírca méd-dso chentímetro.","Cortar las berenjenas en rodajas de medio centímetro aproximadamente."],["Salarle e lasciarle spurgare per circa un'ora.","Salárle e lash-shárle spurgáre per chírca unóra.","Salarlas y dejarlas que suelten el agua durante una hora aproximadamente."],["Asciugare le fette, friggerle in olio caldo e sgocciolarle su carta assorbente.","Ash-shugáre le fét-te, fríd-dyerle in ólio cáldo e sgot-cholárle su cárta as-sorbénte.","Secar las rodajas, freírlas en aceite caliente y escurrirlas sobre papel absorbente."],["Preparare un sugo semplice con la passata, l'olio, l'aglio e qualche foglia di basilico.","Preparáre un súgo sémpliche con la pas-sáta, lólio, láll-llo e cuálke fóll-lla di basílico.","Preparar una salsa sencilla con la passata, el aceite, el ajo y unas hojas de albahaca."],["Tagliare la mozzarella a fette e lasciarla sgocciolare.","Tall-lláre la mot-tsarél-la a fét-te e lash-shárla sgot-choláre.","Cortar la mozzarella en lonchas y dejarla escurrir."],["In una pirofila alternare strati di sugo, melanzane, mozzarella, parmigiano e basilico.","In úna pirófila alternáre stráti di súgo, melandsáne, mot-tsarél-la, parmidyáno e basílico.","En una fuente de horno, alternar capas de salsa, berenjena, mozzarella, parmesano y albahaca."],["Finire con sugo e parmigiano e cuocere in forno a centottanta gradi per circa trenta minuti.","Finíre con súgo e parmidyáno e cuóchere in fórno a chentot-tánta grádi per chírca trénta minúti.","Terminar con salsa y parmesano y hornear a 180 grados unos treinta minutos."],["Lasciare riposare prima di tagliare.","Lash-sháre riposáre príma di tall-lláre.","Dejar reposar antes de cortar."]],"notes":"Su origen se lo disputan sobre todo Campania y Sicilia (también Parma reivindica el nombre); el origen del nombre es discutido. Esta ficha sigue la versión campana con fior di latte. Variantes aceptadas: en Nápoles muchas familias pasan las berenjenas por harina y huevo antes de freírlas (entonces hay que añadir gluten y huevo); en Sicilia se usa a menudo caciocavallo o pecorino. La berenjena a la plancha o al horno es una versión ligera, no la tradicional. Errores típicos: no escurrir la mozzarella (el plato queda aguado), no freír la berenjena y cortarla recién sacada del horno: necesita reposo para que las capas se asienten.","all":["Latte"],"voc":[["spurgare","spurgáre","desaguar (con sal)"],["friggere","fríd-dyere","freír"],["sgocciolare","sgot-choláre","escurrir, dejar gotear"],["la pirofila","la pirófila","la fuente de horno"],["lo strato","lo stráto","la capa"],["la carta assorbente","la cárta as-sorbénte","el papel absorbente"]]},{"id":"r08","t":"Focaccia genovese","tp":"Focát-cha dyenovése","es_t":"Focaccia genovesa","region":"Liguria","serves":6,"time":"3 h 30 min (con levados)","ing":[["farina di grano tenero tipo 0","farína di gráno ténero típo 0","500 g","harina de trigo tipo 0 (de fuerza media)"],["acqua","ác-cua","300 ml","agua"],["lievito di birra fresco","liévito di bír-ra frésco","12 g","levadura fresca de panadería"],["olio extravergine d'oliva","ólio ecstravérdyine dolíva","50 ml + 50 ml","aceite de oliva virgen extra (masa + salmuera y bandeja)"],["sale fino","sále fíno","10 g","sal fina"],["malto d'orzo o zucchero","málto dórtso o dsúk-kero","5 g","malta de cebada o azúcar"],["acqua per la salamoia","ác-cua per la salamóia","100 ml","agua para la salmuera"],["sale grosso","sále grós-so","c. s.","sal gruesa para la superficie"]],"steps":[["Impastare farina, acqua, lievito, malto, sale e olio fino a ottenere un impasto liscio.","Impastáre farína, ác-cua, liévito, málto, sále e ólio fíno a ot-tenére un impásto lísh-sho.","Amasar la harina, el agua, la levadura, la malta, la sal y el aceite hasta obtener una masa lisa."],["Lasciare lievitare l'impasto coperto per circa un'ora.","Lash-sháre lievitáre limpásto copérto per chírca unóra.","Dejar levar la masa tapada alrededor de una hora."],["Stendere l'impasto in una teglia ben unta d'olio.","Sténdere limpásto in úna téll-lla ben únta dólio.","Extender la masa en una bandeja bien untada de aceite."],["Lasciare lievitare ancora per circa un'ora.","Lash-sháre lievitáre ancóra per chírca unóra.","Dejar levar otra vez alrededor de una hora."],["Fare i buchi con i polpastrelli.","Fáre i búki con i polpastrél-li.","Hacer los agujeros con las yemas de los dedos."],["Versare sopra un'emulsione di acqua e olio e cospargere di sale grosso.","Versáre sópra unemulsióne di ác-cua e ólio e cospárdyere di sále grós-so.","Verter por encima una emulsión de agua y aceite y espolvorear con sal gruesa."],["Lasciare lievitare un'ultima volta per circa mezz'ora.","Lash-sháre lievitáre unúltima vólta per chírca med-dsóra.","Dejar levar una última vez durante media hora aproximadamente."],["Cuocere in forno caldo a duecentotrenta gradi per quindici-venti minuti.","Cuóchere in fórno cáldo a duechentotrénta grádi per cuíndichi-vénti minúti.","Hornear en horno caliente a 230 grados durante quince-veinte minutos."]],"notes":"En genovés se llama «fugassa». Debe tener entre 1,5 y 2 cm de grosor, base crujiente, superficie dorada y los típicos hoyos donde queda la salmuera de agua y aceite. En Génova se come también en el desayuno, incluso mojada en el capuchino. No hay que confundirla con la focaccia di Recco col formaggio (IGP), que es una masa fina rellena de queso, ni con la focaccia barese con tomate. Errores típicos: poco aceite en la bandeja, hoyos poco profundos, olvidar la salmuera o hacerla demasiado alta (entonces es más un pan que una focaccia genovesa).","all":["Cereali contenenti glutine"],"voc":[["l'impasto","limpásto","la masa"],["lievitare","lievitáre","levar, fermentar"],["la teglia","la téll-lla","la bandeja de horno"],["la salamoia","la salamóia","la salmuera"],["i polpastrelli","i polpastrél-li","las yemas de los dedos"],["stendere","sténdere","extender, estirar"]]},{"id":"r09","t":"Tiramisù","tp":"Tiramisú","es_t":"Tiramisú","region":"Veneto / Friuli-Venezia Giulia","serves":6,"time":"30 min + 6 h de frío","ing":[["mascarpone","mascarpóne","500 g","mascarpone"],["tuorli d'uovo","tuórli duóvo","4","yemas de huevo (pasteurizadas en restauración)"],["zucchero","dsúk-kero","100 g","azúcar"],["savoiardi","savoiárdi","300 g","bizcochos de soletilla (savoiardi)"],["caffè espresso","caf-fé esprés-so","300 ml, frío","café espresso sin azúcar"],["cacao amaro in polvere","cacáo amáro in pólvere","c. s.","cacao puro en polvo"]],"steps":[["Preparare il caffè e lasciarlo raffreddare.","Preparáre il caf-fé e lash-shárlo raf-fred-dáre.","Preparar el café y dejar que se enfríe."],["Montare i tuorli con lo zucchero fino a ottenere una crema chiara e spumosa.","Montáre i tuórli con lo dsúk-kero fíno a ot-tenére úna créma kiára e spumósa.","Montar las yemas con el azúcar hasta obtener una crema clara y espumosa."],["Aggiungere il mascarpone e mescolare fino a una crema liscia.","Ad-dyúndyere il mascarpóne e mescoláre fíno a úna créma lísh-sha.","Añadir el mascarpone y mezclar hasta obtener una crema lisa."],["Bagnare rapidamente i savoiardi nel caffè.","Bañ-ñáre rapidaménte i savoiárdi nel caf-fé.","Mojar rápidamente los bizcochos en el café."],["Disporre uno strato di savoiardi in una pirofila.","Dispór-re úno stráto di savoiárdi in úna pirófila.","Colocar una capa de bizcochos en una fuente."],["Coprire con uno strato di crema e ripetere, finendo con la crema.","Copríre con úno stráto di créma e ripétere, finéndo con la créma.","Cubrir con una capa de crema y repetir, terminando con la crema."],["Lasciare in frigorifero per almeno sei ore.","Lash-sháre in frigorífero per alméno sei óre.","Dejar en la nevera al menos seis horas."],["Spolverare con il cacao amaro prima di servire.","Spolveráre con il cacáo amáro príma di servíre.","Espolvorear con el cacao puro antes de servir."]],"notes":"Su origen se lo disputan Treviso (Véneto), donde se atribuye al restaurante Le Beccherie, y Friuli-Venecia Julia, que en 2017 lo incluyó en su lista oficial de productos agroalimentarios tradicionales. La versión de Treviso lleva solo savoiardi, café, mascarpone, yemas, azúcar y cacao: sin alcohol ni claras. Variantes muy extendidas: añadir claras montadas para aligerar la crema o un chorrito de marsala o licor (no forman parte de la versión de Treviso). Seguridad: lleva huevo crudo; en restauración usa yemas pasteurizadas o pasteurízalas tú montándolas con almíbar a 121 °C (pâte à bombe). Error típico: empapar demasiado los bizcochos, que sueltan café y dejan la base aguada.","all":["Cereali contenenti glutine","Uova","Latte"],"voc":[["montare","montáre","montar, batir"],["spumoso","spumóso","espumoso"],["bagnare","bañ-ñáre","mojar, empapar"],["lo strato","lo stráto","la capa"],["spolverare","spolveráre","espolvorear"],["la frusta","la frústa","las varillas"]]},{"id":"r10","t":"Panna cotta","tp":"Pán-na cót-ta","es_t":"Panna cotta","region":"Piemonte","serves":6,"time":"20 min + 4 h de frío","ing":[["panna fresca","pán-na frésca","500 ml","nata líquida fresca"],["zucchero","dsúk-kero","80 g","azúcar"],["gelatina in fogli","dyelatína in fóll-lli","8 g","gelatina en láminas («colla di pesce»)"],["baccello di vaniglia","bat-chél-lo di vaníll-lla","½","vaina de vainilla"]],"steps":[["Mettere in ammollo la gelatina in acqua fredda per dieci minuti.","Mét-tere in am-mól-lo la dyelatína in ác-cua fréd-da per diéchi minúti.","Poner a remojo la gelatina en agua fría durante diez minutos."],["Scaldare la panna con lo zucchero e i semi di vaniglia, senza far bollire.","Scaldáre la pán-na con lo dsúk-kero e i sémi di vaníll-lla, séntsa far bol-líre.","Calentar la nata con el azúcar y las semillas de vainilla, sin que llegue a hervir."],["Fuori dal fuoco, sciogliere nella panna la gelatina ben strizzata.","Fuóri dal fuóco, shóll-llere nél-la pán-na la dyelatína ben strit-tsáta.","Fuera del fuego, disolver en la nata la gelatina bien escurrida."],["Filtrare il composto e versarlo negli stampini.","Filtráre il compósto e versárlo néll-lli stampíni.","Colar la mezcla y verterla en los moldes individuales."],["Lasciare rassodare in frigorifero per almeno quattro ore.","Lash-sháre ras-sodáre in frigorífero per alméno cuát-tro óre.","Dejar cuajar en la nevera al menos cuatro horas."],["Per sformare, immergere un attimo gli stampini in acqua calda.","Per sformáre, im-mérdyere un át-timo lli stampíni in ác-cua cálda.","Para desmoldar, sumergir un momento los moldes en agua caliente."],["Servire con caramello, frutti di bosco o cioccolato.","Servíre con caramél-lo, frút-ti di bósco o choc-coláto.","Servir con caramelo, frutos rojos o chocolate."]],"notes":"Postre piamontés («nata cocida»), reconocido como producto agroalimentario tradicional del Piamonte; en la tradición se sirve a menudo con caramelo. Algunas recetas sustituyen parte de la nata por leche. Debe temblar al desmoldarla: si está gomosa, sobra gelatina. Errores típicos: hervir la nata con la gelatina, poner demasiada gelatina o no dejarla cuajar lo suficiente. Aunque en italiano se llame «colla di pesce», la gelatina en láminas del comercio suele ser de origen porcino o bovino (mira la etiqueta): el postre no es vegetariano. Con agar-agar se obtiene una versión vegetariana, pero cambia la textura.","all":["Latte"],"voc":[["mettere in ammollo","mét-tere in am-mól-lo","poner a remojo"],["strizzare","strit-tsáre","escurrir apretando"],["lo stampino","lo stampíno","el molde individual"],["rassodare","ras-sodáre","cuajar, solidificarse"],["sformare","sformáre","desmoldar"]]}],"allergens":[["Cereali contenenti glutine","Chereáli contenénti glútine","Cereales que contengan gluten","grano o frumento (trigo), segale (centeno), orzo (cebada), avena, farro (espelta), kamut y sus híbridos; en la pasta, el pan, la harina, el pan rallado, los rebozados"],["Crostacei","Crostáchei","Crustáceos","gamberi (gambas), scampi (cigalas), aragosta (langosta), astice (bogavante), granchio (cangrejo)"],["Uova","Uóva","Huevos","pasta all'uovo, maionese, frittata, tiramisù, impanature (rebozados con huevo)"],["Pesce","Pésh-she","Pescado","acciughe/alici (anchoas, boquerones), tonno (atún), baccalà (bacalao); también en salsas y fondos"],["Arachidi","Arákidi","Cacahuetes","arachidi o noccioline (cacahuetes), burro di arachidi (crema de cacahuete), olio di arachide"],["Soia","Sóia","Soja","soia, salsa di soia, tofu, lecitina di soia"],["Latte","Lát-te","Leche","latte, panna (nata), burro (mantequilla), formaggi (quesos), mozzarella, ricotta, mascarpone; incluye la lactosa"],["Frutta a guscio","Frút-ta a gúsh-sho","Frutos de cáscara","mandorle (almendras), nocciole (avellanas), noci (nueces), noci di acagiù (anacardos), noci pecan, noci del Brasile, pistacchi, noci macadamia. Los pinoli (piñones) NO están en esta lista"],["Sedano","Sédano","Apio","sedano (apio, también el apio nabo); muy frecuente en soffritto, brodi (caldos) y ragù"],["Senape","Senápe","Mostaza","senape, mostarda (fruta confitada con esencia de mostaza), salse"],["Semi di sesamo","Sémi di sésamo","Granos de sésamo","semi di sesamo (en panes, grissini, cracker), olio di sesamo"],["Anidride solforosa e solfiti","Anidríde solforósa e solfíti","Dióxido de azufre y sulfitos","más de 10 mg/kg o 10 mg/l (como SO2): vino, aceto (vinagre), fruta seca, algunos embutidos"],["Lupini","Lupíni","Altramuces","lupini (altramuces) y harina de altramuz"],["Molluschi","Mol-lúski","Moluscos","cozze (mejillones), vongole (almejas), calamari, seppie (sepias), polpo (pulpo), ostriche (ostras)"]],"cards":[["Soy celíaco","Sono celiaco: non posso mangiare glutine, nemmeno in piccole quantità. Per favore, è importante evitare la contaminazione crociata: niente pentole, acqua della pasta, olio di frittura o utensili già usati per cibi con glutine. Grazie!","Sóno chelíaco: non pós-so mandyáre glútine, nem-méno in píc-cole cuantitá. Per favóre, e importánte evitáre la contaminat-tsióne crocháta: niénte péntole, ác-cua dél-la pásta, ólio di frit-túra o uténsili dya usáti per chíbi con glútine. Grát-tsie!","Soy celíaco: no puedo comer gluten, ni siquiera en pequeñas cantidades. Por favor, es importante evitar la contaminación cruzada: nada de ollas, agua de cocer pasta, aceite de freír o utensilios ya usados para alimentos con gluten. ¡Gracias!"],["Alergia a frutos secos (adáptala)","Sono allergico alla frutta a guscio (noci, nocciole, mandorle, pistacchi). Anche piccole tracce possono essere pericolose. Il piatto contiene frutta a guscio o olio di frutta a guscio?","Sóno al-lérdyico ál-la frút-ta a gúsh-sho (nóchi, not-chóle, mándorle, pisták-ki). Ánke píc-cole trát-che pós-sono és-sere pericolóse. Il piát-to contiéne frút-ta a gúsh-sho o ólio di frút-ta a gúsh-sho?","Soy alérgico a los frutos de cáscara (nueces, avellanas, almendras, pistachos). Incluso pequeñas trazas pueden ser peligrosas. ¿El plato lleva frutos de cáscara o aceite de frutos de cáscara?"],["Soy vegetariano","Sono vegetariano: non mangio carne né pesce, nemmeno acciughe, strutto o brodo di carne. C'è qualcosa senza carne e senza pesce?","Sóno vedyetariáno: non mándyo cárne ne pésh-she, nem-méno at-chúgue, strút-to o bródo di cárne. Che cualcósa séntsa cárne e séntsa pésh-she?","Soy vegetariano: no como carne ni pescado, ni siquiera anchoas, manteca de cerdo o caldo de carne. ¿Hay algo sin carne y sin pescado?"],["No como cerdo","Non mangio carne di maiale. Per favore, mi può dire se in questo piatto c'è maiale, anche in piccola quantità (guanciale, pancetta, strutto, prosciutto, brodo o gelatina)?","Non mándyo cárne di maiále. Per favóre, mi puo díre se in cuésto piát-to che maiále, ánke in píc-cola cuantitá (guanchále, panchét-ta, strút-to, prosh-shút-to, bródo o dyelatína)?","No como carne de cerdo. Por favor, ¿me puede decir si este plato lleva cerdo, aunque sea en pequeña cantidad (guanciale, panceta, manteca, jamón, caldo o gelatina)?"],["¿Puede hablar más despacio?","Mi scusi, può parlare più piano, per favore?","Mi scúsi, puo parláre piu piáno, per favóre?","Disculpe, ¿puede hablar más despacio, por favor?"],["No hablo bien italiano","Mi dispiace, non parlo bene l'italiano: sono spagnolo. Può usare parole semplici?","Mi dispiáche, non párlo béne litaliáno: sóno spañ-ñólo. Puo usáre paróle sémplichi?","Lo siento, no hablo bien italiano: soy español. ¿Puede usar palabras sencillas?"],["¿Me lo puede escribir?","Me lo può scrivere, per favore?","Me lo puo scrívere, per favóre?","¿Me lo puede escribir, por favor?"],["Llamar a un médico","Per favore, chiami un medico! Mi sento male.","Per favóre, kiámi un médico! Mi sénto mále.","¡Por favor, llame a un médico! Me encuentro mal."],["Farmacia de guardia","Mi scusi, dov'è la farmacia di turno più vicina?","Mi scúsi, dové la farmachía di túrno piu vichína?","Disculpe, ¿dónde está la farmacia de guardia más cercana?"],["Emergencias: 112","È un'emergenza! Per favore, chiami il numero di emergenza 112 (uno uno due).","E unemerdyéntsa! Per favóre, kiámi il número di emerdyéntsa 112 (úno úno dúe).","¡Es una emergencia! Por favor, llame al número de emergencias 112 (uno uno dos)."],["He perdido la documentación","Ho perso i miei documenti e devo fare una denuncia di smarrimento. Dove si trova la stazione dei Carabinieri o il commissariato più vicino?","O pérso i miei documénti e dévo fáre úna denúncha di smar-riménto. Dóve si tróva la stat-tsióne dei Carabiniéri o il com-mis-sariáto piu vichíno?","He perdido mi documentación y tengo que poner una denuncia por extravío. ¿Dónde está el cuartel de los Carabinieri o la comisaría más cercana?"],["Necesito un taxi","Mi può chiamare un taxi, per favore? Devo andare a questo indirizzo: [indirizzo].","Mi puo kiamáre un tácsi, per favóre? Dévo andáre a cuésto indirít-tso: [indirít-tso].","¿Me puede llamar a un taxi, por favor? Tengo que ir a esta dirección: [dirección]."],["La cuenta, por favor","Il conto, per favore. Si può pagare con la carta?","Il cónto, per favóre. Si puo pagáre con la cárta?","La cuenta, por favor. ¿Se puede pagar con tarjeta?"],["Soy profesor de cocina","Sono un insegnante di cucina in Spagna. Complimenti, era tutto buonissimo! Se non disturbo, sarebbe possibile vedere la cucina un attimo? Capisco benissimo se non è possibile.","Sóno un inseñ-ñánte di cuchína in Spáñ-ña. Compliménti, éra tút-to buonís-simo! Se non distúrbo, saréb-be pos-síbile vedére la cuchína un át-timo? Capísco benís-simo se non e pos-síbile.","Soy profesor de cocina en España. ¡Enhorabuena, estaba todo buenísimo! Si no molesto, ¿sería posible ver la cocina un momento? Lo entiendo perfectamente si no es posible."]]};
